            {/* 3b. TRANG FLASH SALE */}
            <Route path="/flash-sale" element={<FlashSalePage flashSaleProducts={flashSaleProducts} onBuy={handleAddToCart} />} />

            {/* TRANG CHI TIẾT SẢN PHẨM */}
            <Route path="/product/:id" element={<ProductDetailPage products={allProducts} flashSaleProducts={flashSaleProducts} onAddToCart={handleAddToCart} onBuyNow={handleBuyNow} showToast={showToast} />} />

            {/* TRANG ĐĂNG NHẬP/ĐĂNG KÝ */}
            <Route path="/login" element={<LoginPage showToast={showToast} />} />

            {/* TRANG YÊU THÍCH */}
            <Route path="/wishlist" element={<WishlistPage onAddToCart={handleAddToCart} showToast={showToast} />} />

            {/* TRANG SO SÁNH */}
            <Route path="/compare" element={<ComparePage onAddToCart={handleAddToCart} showToast={showToast} />} />

            {/* PHÒNG SO SÁNH SIZE — Size Comparison Room */}
            <Route path="/size-compare" element={<SizeComparisonRoom onAddToCart={(size) => { showToast(`Đã chọn ${size}!`, 'success'); }} />} />

            {/* TRANG GIỎ HÀNG MỚI (LUXURY CART) */}
            <Route path="/cart" element={<CartPage cartItems={cartItems} onRemove={handleRemoveFromCart} onUpdateQuantity={handleUpdateQuantity} onAddToCart={handleAddToCart} showToast={showToast} suggestionProducts={suggestionProducts} />} />

            {/* TRANG CHỌN SẢN PHẨM THANH TOÁN */}
            <Route path="/checkout/choseproduct" element={<CartPage cartItems={cartItems} onRemove={handleRemoveFromCart} onUpdateQuantity={handleUpdateQuantity} onAddToCart={handleAddToCart} showToast={showToast} suggestionProducts={suggestionProducts} />} />

            {/* TRANG THANH TOÁN */}
            <Route path="/checkout/cart" element={<CheckoutPage cartItems={cartItems} onCheckoutSuccess={handleCheckoutSuccess} showToast={showToast} suggestionProducts={suggestionProducts} onAddToCart={handleAddToCart} />} />

            {/* TRANG GIỎ HÀNG & THANH TOÁN (Redirect cũ) */}
            <Route path="/checkout" element={<CartPage cartItems={cartItems} onRemove={handleRemoveFromCart} onUpdateQuantity={handleUpdateQuantity} onAddToCart={handleAddToCart} showToast={showToast} suggestionProducts={suggestionProducts} />} />

            {/* TRANG CÁ NHÂN NGƯỜI DÙNG */}
            <Route path="/profile" element={<UserProfilePage showToast={showToast} />} />

            {/* TRANG ĐƠN HÀNG (CŨ - GIỮ LẠI ĐỂ TƯƠNG THÍCH) */}
            <Route path="/orders" element={<OrderPage showToast={showToast} />} />

            {/* TRANG 3D VIRTUAL TRY-ON */}
            <Route path="/try-on" element={
              <VirtualTryOnWrapper
                defaultProduct={suggestionProducts[0]}
                allProducts={allProducts}
                onAddToCart={handleAddToCart}
                onBuyNow={handleBuyNow}
                showToast={showToast}
              />
            } />

            {/* TRANG QUẢN LÝ AVATAR */}
            <Route path="/avatar-studio" element={<AvatarStudioPage />} />

            {/* TRANG AI OUTFIT ROOM - PHÒNG AI GỢI Ý PHỐI ĐỒ (3D + AI) */}
            <Route path="/ai-outfit" element={<AIOutfitGenerator onAddToCart={handleAddToCart} onBuyNow={handleBuyNow} showToast={showToast} />} />

            {/* TRANG AI OUTFIT GENERATOR - PHIÊN BẢN CHAT CŨ */}
            <Route path="/ai-outfit-generator" element={<AIOutfitGenerator onAddToCart={handleAddToCart} onBuyNow={handleBuyNow} showToast={showToast} />} />

            {/* TRANG NỘI DUNG BANNER */}
            <Route path="/banner/:bannerId" element={<BannerContentPage />} />

            {/* TRANG TRUNG TÂM TRỢ GIÚP */}
            <Route path="/help" element={<HelpPage />} />

            {/* TRANG GIỚI THIỆU */}
            <Route path="/about" element={<AboutPage />} />

            {/* TRANG CHÍNH SÁCH */}
            <Route path="/guide" element={<PolicyPage />} />
            <Route path="/sell-guide" element={<PolicyPage />} />
            <Route path="/payment" element={<PolicyPage />} />
            <Route path="/shipping" element={<PolicyPage />} />
            <Route path="/return-policy" element={<PolicyPage />} />
            <Route path="/privacy" element={<PolicyPage />} />
            <Route path="/terms" element={<PolicyPage />} />
            <Route path="/cookies" element={<PolicyPage />} />

          </Routes>
        </Suspense>

        {/* Thông báo (Toast) hiển thị đè lên trên cùng */}
        {toast && <Toast message={toast.message} type={toast.type} onClose={handleToastClose} />}

        {/* Chat Widget - Hiển thị trên các trang khách */}
        {!isAdminRoute && !isTryOnPage && (
          <Suspense fallback={null}>
            <ChatWidget />
          </Suspense>
        )}

        {!isTryOnPage && !isAdminRoute && <Footer />}
      </div>
    );
  };

  // --- RENDER GIAO DIỆN ---
  return (
    <ThemeProvider>
      <AuthProvider>
        <FittingRoomProvider>
          <WishlistProvider>
            <CompareProvider>
              <LanguageProvider>
                <BrowserRouter>
                  <ScrollToTop />
                  <AppShell />
                </BrowserRouter>
              </LanguageProvider>
            </CompareProvider>
          </WishlistProvider>
        </FittingRoomProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}

export default App;

import { useState, useRef } from 'react';
import './AIOutfitChat.css';

const RAW_API_URL = import.meta.env.VITE_API_URL || '';
const API_BASE_URL = RAW_API_URL.trim().replace(/\/$/, '');
const AI_OUTFIT_SUGGEST_ENDPOINT = API_BASE_URL
    ? `${API_BASE_URL}/api/ai/outfit-suggest`
    : '/api/ai/outfit-suggest';

interface OutfitItem {
    itemId?: string;
    productId?: number;
    name: string;
    slot: string;
    reason: string;
    source: 'closet' | 'shop';
    price?: number;
}

interface AIResult {
    outfit: OutfitItem[];
    suggestions: OutfitItem[];
    explanation: string;
    occasion?: string;
    weatherTip?: string;
}

interface Props {
    closetItems: any[];
    avatarData: any;
    token?: string;
    onWearOutfit: (items: OutfitItem[]) => void;
    onAddToCart: (productId: number) => void;
}

export default function AIOutfitChat({ closetItems, avatarData, token, onWearOutfit, onAddToCart }: Props) {
    const [open, setOpen] = useState(false);
    const [input, setInput] = useState('');
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState<AIResult | null>(null);
    const [error, setError] = useState('');
    const inputRef = useRef<HTMLInputElement>(null);

    const QUICK_PROMPTS = [
        'Đi làm sáng mai 🏢',
        'Đi cafe cuối tuần ☕',
        'Hẹn hò tối nay 🌙',
        'Đi biển ngày nóng 🏖️',
        'Ở nhà chill 🏠',
        'Dự tiệc quan trọng 🎉',
    ];

    const handleAsk = async (prompt?: string) => {
        const q = (prompt ?? input).trim();
        if (!q) return;

        const authToken =
            token ||
            localStorage.getItem('token') ||
            localStorage.getItem('accessToken') ||
            localStorage.getItem('authToken') ||
            localStorage.getItem('jwt') ||
            sessionStorage.getItem('token') ||
            '';

        console.log('Token khi gọi AI:', authToken);
        console.log('Token type:', typeof authToken);

        if (!authToken) {
            setError('Vui lòng đăng nhập để sử dụng AI Stylist');
            return;
        }

        setLoading(true);
        setResult(null);
        setError('');

        try {
            const res = await fetch(AI_OUTFIT_SUGGEST_ENDPOINT, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${authToken}`
                },
                body: JSON.stringify({
                    userPrompt: q,
                    closetItems: closetItems?.slice(0, 10) ?? [],
                    avatarData: avatarData ?? {}
                })
            });

            if (res.status === 401) {
                setError('Phiên đăng nhập hết hạn. Vui lòng đăng nhập lại.');
                return;
            }

            const data = await res.json();

            if (!res.ok) {
                setError(data.error ?? 'Có lỗi xảy ra');
                return;
            }

            setResult(data);

            // Tự động mặc đồ từ tủ lên avatar
            const closetOutfit = (data.outfit ?? []).filter((i: OutfitItem) => i.source === 'closet');
            if (closetOutfit.length > 0) onWearOutfit(closetOutfit);

        } catch (e) {
            setError('Không kết nối được AI. Vui lòng thử lại.');
        } finally {
            setLoading(false);
            setInput('');
        }
    };

    // Slot icon
    const slotIcon = (slot: string) => ({
        tops: '👕', bottoms: '👖', dress: '👗', outerwear: '🧥'
    }[slot] ?? '👔');

    const outfitItems = result?.outfit ?? [];
    const suggestionItems = result?.suggestions ?? [];

    return (
        <>
            {/* Nút mở chat — floating góc dưới trái canvas */}
            <button
                className={`ai-chat-fab ${open ? 'ai-chat-fab--open' : ''}`}
                onClick={() => setOpen(v => !v)}
                title="Hỏi AI Stylist"
            >
                {open ? '✕' : '✦'}
            </button>

            {/* Panel chat */}
            {open && (
                <div className="ai-chat-panel">
                    <div className="ai-chat-header">
                        <span className="ai-chat-title">✦ AI Stylist</span>
                        <span className="ai-chat-sub">Hỏi tôi muốn mặc gì hôm nay</span>
                    </div>

                    {/* Quick prompts */}
                    {!result && !loading && (
                        <div className="ai-quick-prompts">
                            {QUICK_PROMPTS.map(p => (
                                <button
                                    key={p}
                                    className="ai-quick-btn"
                                    onClick={() => handleAsk(p)}
                                >
                                    {p}
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Loading */}
                    {loading && (
                        <div className="ai-loading">
                            <div className="ai-loading-dots">
                                <span /><span /><span />
                            </div>
                            <p>AI đang phân tích tủ đồ...</p>
                        </div>
                    )}

                    {/* Error */}
                    {error && (
                        <div className="ai-error">
                            ⚠️ {error}
                            <button onClick={() => setError('')}>Thử lại</button>
                        </div>
                    )}

                    {/* Result */}
                    {result && (
                        <div className="ai-result">
                            {/* Explanation */}
                            <div className="ai-explanation">
                                <span className="ai-explanation-icon">✦</span>
                                {result.explanation}
                            </div>

                            {/* Đồ từ tủ */}
                            {outfitItems.length > 0 && (
                                <div className="ai-section">
                                    <div className="ai-section-title">Từ tủ đồ của bạn</div>
                                    {outfitItems.map((item, i) => (
                                        <div key={i} className="ai-item ai-item--closet">
                                            <span className="ai-item-icon">{slotIcon(item.slot)}</span>
                                            <div className="ai-item-info">
                                                <div className="ai-item-name">{item.name}</div>
                                                <div className="ai-item-reason">{item.reason}</div>
                                            </div>
                                            <span className="ai-item-badge ai-item-badge--closet">Tủ đồ ✓</span>
                                        </div>
                                    ))}
                                </div>
                            )}

                            {/* Gợi ý mua thêm */}
                            {suggestionItems.length > 0 && (
                                <div className="ai-section">
                                    <div className="ai-section-title">Gợi ý mua thêm</div>
                                    {suggestionItems.map((item, i) => (
                                        <div key={i} className="ai-item ai-item--shop">
                                            <span className="ai-item-icon">{slotIcon(item.slot)}</span>
                                            <div className="ai-item-info">
                                                <div className="ai-item-name">{item.name}</div>
                                                <div className="ai-item-reason">{item.reason}</div>
                                                {item.price && (
                                                    <div className="ai-item-price">
                                                        {item.price.toLocaleString('vi-VN')}đ
                                                    </div>
                                                )}
                                            </div>
                                            <button
                                                className="ai-item-add-btn"
                                                onClick={() => item.productId && onAddToCart(item.productId)}
                                            >
                                                + Giỏ
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}

                            {/* Weather tip */}
                            {result.weatherTip && (
                                <div className="ai-weather-tip">🌤️ {result.weatherTip}</div>
                            )}

                            {/* Hỏi lại */}
                            <button className="ai-ask-again" onClick={() => setResult(null)}>
                                Hỏi lại ↩
                            </button>
                        </div>
                    )}

                    {/* Input */}
                    <div className="ai-chat-input-wrap">
                        <input
                            ref={inputRef}
                            className="ai-chat-input"
                            value={input}
                            onChange={e => setInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && handleAsk()}
                            placeholder="Hôm nay tôi muốn mặc gì?"
                            disabled={loading}
                        />
                        <button
                            className="ai-chat-send"
                            onClick={() => handleAsk()}
                            disabled={loading || !input.trim()}
                        >
                            {loading ? '...' : '↑'}
                        </button>
                    </div>
                </div>
            )}
        </>
    );
}

import React, { useEffect, useState, useRef } from 'react';
import type { AIOutfit } from '../types/aiOutfit';
import OutfitCard from './OutfitCard.tsx';

const RAW_API_URL = import.meta.env.VITE_API_URL || '';
const API_BASE_URL = RAW_API_URL.trim().replace(/\/$/, '');
const AI_OUTFIT_SUGGEST_ENDPOINT = API_BASE_URL
    ? `${API_BASE_URL}/api/ai/outfit-suggest`
    : '/api/ai/outfit-suggest';

export default function AIOutfitSidebar({ initialPrompt = '' }: { initialPrompt?: string }) {
    const [prompt, setPrompt] = useState(initialPrompt);
    const [outfits, setOutfits] = useState<AIOutfit[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const suggestionsRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (initialPrompt.trim()) {
            setPrompt(initialPrompt);
        }
    }, [initialPrompt]);

    const handleGenerateOutfits = async () => {
        if (!prompt.trim()) {
            setError('Vui lòng nhập yêu cầu phối đồ');
            return;
        }

        setIsLoading(true);
        setError(null);

        try {
            const token = localStorage.getItem('token') || sessionStorage.getItem('token');

            if (!token) {
                setError('Vui lòng đăng nhập để sử dụng AI Stylist');
                setIsLoading(false);
                return;
            }

            const response = await fetch(AI_OUTFIT_SUGGEST_ENDPOINT, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({
                    userPrompt: prompt,
                    includeClosetItems: true,
                    includeNewArrivals: true,
                }),
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                throw new Error(errorData.message || `API Error: ${response.status}`);
            }

            const data = await response.json();

            // Transform API response to AIOutfit format
            const transformedOutfits: AIOutfit[] = (data.outfits || []).map(
                (outfit: any, index: number) => ({
                    id: `outfit-${Date.now()}-${index}`,
                    name: outfit.name || `Phối Đồ ${index + 1}`,
                    description: outfit.description,
                    occasion: outfit.occasion,
                    items: (outfit.items || []).map((item: any) => ({
                        productId: item.productId || item.id,
                        type: item.type || 'shop',
                        layer: item.layer || 'tops',
                        model3DUrl: item.model3DUrl || '',
                        thumbnail: item.thumbnail || item.image || '',
                        name: item.name || '',
                        price: item.price,
                        source: item.source,
                    })),
                })
            );

            setOutfits(transformedOutfits);

            // Scroll to suggestions
            setTimeout(() => {
                suggestionsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }, 200);
        } catch (err) {
            console.error('AI Outfit Generation Error:', err);
            setError(err instanceof Error ? err.message : 'Không thể tạo gợi ý phối đồ');
        } finally {
            setIsLoading(false);
        }
    };

    const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter' && !isLoading) {
            handleGenerateOutfits();
        }
    };

    return (
        <div className="ai-outfit-sidebar">
            {/* Header */}
            <div className="ai-outfit-header">
                <h2 className="ai-outfit-title">✦ AI Phối Đồ</h2>
                <p className="ai-outfit-subtitle">Nhập yêu cầu phối đồ của bạn</p>
            </div>

            {/* Suggestions List */}
            <div
                ref={suggestionsRef}
                className="ai-outfit-suggestions"
                style={{
                    flex: 1,
                    overflowY: 'auto',
                    padding: '16px',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '12px',
                }}
            >
                {outfits.length === 0 && !isLoading && (
                    <div className="ai-outfit-empty">
                        <p style={{ color: '#999', textAlign: 'center', fontSize: '13px' }}>
                            Nhập yêu cầu để bắt đầu tạo gợi ý phối đồ
                        </p>
                    </div>
                )}

                {outfits.map((outfit) => (
                    <OutfitCard
                        key={outfit.id}
                        outfit={outfit}
                        onWear={() => {
                            console.log('Wear outfit:', outfit.name);
                        }}
                    />
                ))}

                {isLoading && (
                    <div className="ai-outfit-loading">
                        <div className="spinner"></div>
                        <p>Đang tạo gợi ý...</p>
                    </div>
                )}

                {error && (
                    <div className="ai-outfit-error">
                        <p>{error}</p>
                        <button
                            className="ai-outfit-error-dismiss"
                            onClick={() => setError(null)}
                        >
                            ✕
                        </button>
                    </div>
                )}
            </div>

            {/* Input Section */}
            <div className="ai-outfit-input-section">
                <input
                    type="text"
                    className="ai-outfit-input"
                    placeholder="VD: Phối đồ đi Đà Lạt mùa đông..."
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    onKeyPress={handleKeyPress}
                    disabled={isLoading}
                />
                <button
                    className="ai-outfit-submit-btn"
                    onClick={handleGenerateOutfits}
                    disabled={isLoading}
                >
                    {isLoading ? '⏳' : '→'}
                </button>
            </div>

            <style>{`
        .ai-outfit-sidebar {
          display: flex;
          flex-direction: column;
          height: 100%;
          background: linear-gradient(135deg, #ffffff 0%, #f9f7f4 100%);
          border-left: 1px solid #e8e4df;
        }

        .ai-outfit-header {
          padding: 16px;
          border-bottom: 1px solid #e8e4df;
          background: linear-gradient(135deg, #fafaf8 0%, #f5f1e8 100%);
        }

        .ai-outfit-title {
          margin: 0 0 4px 0;
