        }
        @keyframes avatarPulse {
          0%, 100% { opacity: 0.4; transform: scale(1); }
          50% { opacity: 0.7; transform: scale(1.02); }
        }
        .ap-silhouette {
          width: 120px;
          height: 200px;
          background: linear-gradient(180deg, var(--gold-light) 0%, transparent 100%);
          border-radius: 60px 60px 40px 40px;
          border: 1px dashed var(--gold-border);
          margin: 0 auto 24px;
          position: relative;
          animation: avatarPulse 3s ease-in-out infinite;
        }
        .ap-head {
          position: absolute;
          top: -20px;
          left: 50%;
          transform: translateX(-50%);
          width: 40px;
          height: 40px;
          border-radius: 50%;
          background: var(--gold-light);
          border: 1px dashed var(--gold-border);
        }
      `}</style>
      
      {/* Background Theme Controls */}
      <div style={{
        position: 'absolute',
        left: 16,
        top: 16,
        zIndex: 101,
        display: 'flex',
        gap: 10,
        padding: '10px 14px',
        borderRadius: 16,
        border: '1px solid var(--vfit-border)',
        background: 'var(--vfit-bg-panel)',
        backdropFilter: 'blur(14px)',
        boxShadow: '0 6px 18px rgba(0,0,0,0.15)',
        alignItems: 'center',
      }}>
        <div style={{ fontSize: '10px', fontWeight: 700, color: 'var(--vfit-text-secondary)', letterSpacing: '0.04em', paddingRight: '4px' }}>NỀN</div>
        <button onClick={() => setBgTheme('light')} title="Sáng" style={{ width: 18, height: 18, borderRadius: '50%', background: '#E4DFF5', border: bgTheme === 'light' ? '2px solid var(--vfit-accent)' : '1px solid var(--vfit-border)', cursor: 'pointer' }} />
        <button onClick={() => setBgTheme('dark')} title="Tối" style={{ width: 18, height: 18, borderRadius: '50%', background: '#1A1625', border: bgTheme === 'dark' ? '2px solid var(--vfit-accent)' : '1px solid var(--vfit-border)', cursor: 'pointer' }} />
      </div>

      {/* Badge */}
      <div style={badgeStyle}>
        {isGenerating ? 'Generating outfit...' : `Current Outfit: ${selectedOutfit?.name ?? 'Default Preview'}`}
      </div>

      {/* Empty State */}
      {!currentAvatar && !selectedOutfit && (
        <div style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1,
          pointerEvents: 'none'
        }}>
          <div className="ap-silhouette">
            <div className="ap-head" />
          </div>
          <div style={{
            fontSize: '15px',
            fontWeight: '500',
            color: 'var(--text-primary)',
            opacity: 0.6,
            marginBottom: '6px',
            textAlign: 'center'
          }}>
            Chưa có avatar của bạn
          </div>
          <div style={{
            fontSize: '12px',
            color: 'var(--text-secondary)',
            opacity: 0.45,
            textAlign: 'center',
            lineHeight: 1.5,
            whiteSpace: 'pre-wrap'
          }}>
            Nhập mô tả ở panel trái{'\n'}rồi bấm Tạo outfit với AI
          </div>
        </div>
      )}

      {/* Background Pattern Overlay removed */}

      <div
        ref={canvasAreaRef}
        className="vfit-bg-canvas"
        style={{ position: 'relative', width: '100%', height: '100%', minHeight: 420, flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}
      >
        <div className="vfit-canvas-floor" />
        <div className="vfit-canvas-podium" />
        <div className="vfit-canvas-vignette" />
        <div className="vfit-canvas-spotlight" />
        <div className="vfit-canvas-shadow" />
        <div className="vfit-canvas-rim-light" />

        {/* Canvas Container */}
        <div style={{ flex: 1, position: 'relative', width: '100%', overflow: 'hidden', zIndex: 4 }}>
          <Canvas
            key={`canvas-vto-${lossCount}`}
            frameloop={isWebglContextLost ? 'never' : 'always'}
            dpr={fallbackMode ? 1 : [1.5, 2]}
            performance={{ min: fallbackMode ? 0.25 : 0.5 }}
            camera={{ position: cameraPreset.position, fov: 32 }}
            shadows={false}
            gl={{
              antialias: true,
              preserveDrawingBuffer: false,
              powerPreference: 'high-performance',
              stencil: false,
              depth: true,
              alpha: true,
            }}
            onCreated={handleCanvasCreated}
            style={{ width: '100%', height: '100%', display: 'block' }}
          >
            <ambientLight intensity={fallbackMode ? 0.6 : 0.55} />
            <directionalLight
              position={[3, 6, 4]}
              intensity={fallbackMode ? 1.0 : 1.25}
            />
            <directionalLight position={[-2, 3, -2]} intensity={0.4} />
            <hemisphereLight args={['#f5f0e8', '#3a3228', 0.5]} />

            <CameraViewController view={viewAngle} controlsRef={controlsRef} />

            <TryOnScene
              body={currentAvatar}
              onSceneReady={setAvatarScene}
              layeredGarments={layeredGarments}
              showEnvironment={!fallbackMode}
              showContactShadows={!fallbackMode}
              showGrid={false}
            />

            <OrbitControls
              ref={controlsRef}
              enablePan={false}
              enableZoom
              enableDamping
              dampingFactor={0.08}
              minDistance={2.5}
              maxDistance={5.5}
            />
          </Canvas>


        </div>

        {/* Loading Overlay */}
        {isGenerating && (
          <div style={{ position: 'absolute', inset: 0, background: 'rgba(255,255,255,0.18)', zIndex: 3, pointerEvents: 'none' }} />
        )}
      </div>

      {/* View Controls */}
      <div style={controlsStyle}>
        {(['front', 'back', 'left'] as ViewAngle[]).map(angle => (
          <button
            key={angle}
            onClick={() => onViewChange(angle)}
            style={{
              fontSize: 12,
              padding: '8px 12px',
              borderRadius: 10,
              border: '1px solid',
              borderColor: viewAngle === angle ? 'var(--gold-primary)' : 'rgba(212,169,66,0.3)',
              background: viewAngle === angle ? 'var(--gold-primary)' : 'rgba(255,255,255,0.8)',
              color: viewAngle === angle ? 'var(--vfit-text-primary)' : 'var(--vfit-text-secondary)',
              cursor: 'pointer',
            }}
          >
            {angle === 'front' && 'Front'}
            {angle === 'back' && 'Back'}
            {angle === 'left' && 'Side'}
          </button>
        ))}
      </div>

      {/* Background Theme Controls Removed */}
    </div>
  )
}

export default memo(AvatarPanel, (prevProps, nextProps) => {
  return (
    prevProps.selectedOutfit?.id === nextProps.selectedOutfit?.id &&
    prevProps.isGenerating === nextProps.isGenerating &&
    prevProps.viewAngle === nextProps.viewAngle &&
    prevProps.activeOutfitIndex === nextProps.activeOutfitIndex &&
    prevProps.outfits?.length === nextProps.outfits?.length
  )
})

import { useState } from 'react'
import { MessageCircle, X } from 'lucide-react'
import ResultPanel from './ResultPanel'
import type { OutfitResult, ChatMessage, ViewAngle, OutfitItem } from '../../types/outfit'

interface FloatingAISuggestionsProps {
    outfits: OutfitResult[]
    selectedOutfitId: string | null
    onSelectOutfit: (id: string) => void
    onTryItem: (item: OutfitItem) => void
    isGenerating: boolean
    messages: ChatMessage[]
    onSendMessage: (text: string) => void
    activeTab: 'describe' | 'occasion'
}

export default function FloatingAISuggestions({
    outfits,
    selectedOutfitId,
    onSelectOutfit,
    onTryItem,
    isGenerating,
    messages,
    onSendMessage,
    activeTab,
}: FloatingAISuggestionsProps) {
    const [isOpen, setIsOpen] = useState(false)

    if (isOpen) {
        return (
            <div style={{
                position: 'fixed',
                bottom: 16,
                right: 16,
                width: 420,
                height: '70vh',
                maxHeight: 'calc(100vh - 100px)',
                background: 'rgba(255,255,255,0.96)',
                border: '1px solid rgba(148,163,184,0.35)',
                borderRadius: 24,
                boxShadow: '0 20px 50px rgba(15,23,42,0.20)',
                backdropFilter: 'blur(18px)',
                display: 'flex',
                flexDirection: 'column',
                overflow: 'hidden',
                zIndex: 1000,
            }}>
                {/* Header */}
                <div style={{
                    padding: '12px 16px',
                    borderBottom: '1px solid rgba(226,232,240,0.9)',
                    background: 'rgba(255,255,255,0.65)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                }}>
                    <h3 style={{ fontSize: 14, fontWeight: 700, color: '#0f172a', margin: 0 }}>AI Suggestions</h3>
                    <button
                        onClick={() => setIsOpen(false)}
                        style={{
                            background: 'transparent',
                            border: 'none',
                            color: '#475569',
                            cursor: 'pointer',
                            fontSize: 18,
                            padding: 4,
                        }}
                    >
                        <X size={20} />
                    </button>
                </div>

                {/* Content */}
                <div style={{ flex: 1, overflow: 'hidden' }}>
                    <ResultPanel
                        outfits={outfits}
                        selectedOutfitId={selectedOutfitId}
                        onSelectOutfit={onSelectOutfit}
                        onTryItem={onTryItem}
                        isGenerating={isGenerating}
                        messages={messages}
                        onSendMessage={onSendMessage}
                        activeTab={activeTab}
                    />
                </div>
            </div>
        )
    }

    // Floating button (closed state)
    return (
        <button
            onClick={() => setIsOpen(true)}
            style={{
                position: 'fixed',
                bottom: 24,
                right: 24,
                width: 60,
                height: 60,
                borderRadius: '50%',
                background: '#10b981',
                border: 'none',
                color: '#fff',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0 8px 24px rgba(16,185,129,0.32)',
                transition: 'transform 0.2s ease',
                zIndex: 1000,
            }}
            onMouseEnter={(e) => (e.currentTarget.style.transform = 'scale(1.1)')}
            onMouseLeave={(e) => (e.currentTarget.style.transform = 'scale(1)')}
        >
            <MessageCircle size={24} />
        </button>
    )
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import type { OutfitResult, OutfitItem } from '../../types/outfit';

interface OutfitCardProps {
    outfit: OutfitResult;
    isSelected: boolean;
    index: number;
    onSelect: (id: string) => void;
    onTryItem: (item: OutfitItem) => void;
    isLocalFallback?: boolean;
    onUpdateItem?: (outfitId: string, itemId: string, updates: Partial<OutfitItem>) => void;
    onOpenTryonPanel?: (outfitId: string) => void;
}

export default function OutfitCard({
    outfit,
    isSelected,
    index,
    onSelect,
    onTryItem,
    isLocalFallback = false,
    onUpdateItem,
    onOpenTryonPanel,
}: OutfitCardProps) {
    const [expanded, setExpanded] = useState(isSelected);
    const [isLoadingSession, setIsLoadingSession] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        setExpanded(isSelected);
    }, [isSelected]);

    const items = outfit.items ?? (outfit as any).products ?? [];
    const rawScore = outfit.matchScore ?? (outfit as any).score ?? 0;
    const score = Math.round(parseFloat(String(rawScore)) || 0);
    
    let scoreColor = 'var(--text-secondary)';
    let scoreFill = 'var(--text-secondary)';
    if (score >= 90) {
        scoreColor = '#4CAF50';
        scoreFill = 'linear-gradient(90deg, #4CAF50, #81C784)';
    } else if (score >= 70) {
        scoreColor = 'var(--gold-primary)';
        scoreFill = 'linear-gradient(90deg, var(--gold-primary), #E8B84B)';
    }

    return (
        <div
            className={`outfit-card ${isSelected ? 'selected' : ''}`}
            onClick={() => onSelect(outfit.id)}
            style={{
                position: 'relative',
                background: 'var(--surface-card)',
                border: isSelected ? '1.5px solid var(--gold-primary)' : '1px solid var(--gold-border)',
                borderRadius: '14px',
                overflow: 'hidden',
                transition: 'transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s',
                cursor: 'pointer',
                boxShadow: isSelected ? '0 0 0 3px var(--gold-light)' : 'none',
                flexShrink: 0,
            }}
        >
            <style>{`
                .outfit-card:hover {
                    transform: translateY(-2px);
                    box-shadow: 0 8px 24px rgba(201,150,63,0.1);
                    border-color: var(--gold-primary);
                }
                .ai-reason-content {
                    max-height: 0;
                    overflow: hidden;
                    transition: max-height 0.25s ease;
                }
                .ai-reason-content.expanded {
                    max-height: 200px;
                }
                .oc-color-swatch {
                    width: 18px;
                    height: 18px;
                    border-radius: 50%;
                    cursor: pointer;
                    border: 1px solid rgba(0,0,0,0.1);
                    display: inline-block;
                }
                .oc-color-swatch.selected {
                    border: 2px solid var(--gold-primary);
                    transform: scale(1.1);
                }
                .oc-size-select {
                    background: var(--surface-card);
                    border: 1px solid var(--gold-border);
                    color: var(--text-secondary);
                    border-radius: 4px;
                    padding: 2px 6px;
                    font-size: 10px;
                    outline: none;
                }
            `}</style>

            {isSelected && (
                <div style={{
                    position: 'absolute',
                    top: '8px',
                    right: '8px',
                    background: 'var(--gold-primary)',
                    color: '#0F0B07',
                    borderRadius: '6px',
                    padding: '2px 8px',
                    fontSize: '9px',
                    fontWeight: '700',
                    letterSpacing: '0.06em',
                    zIndex: 2
                }}>
                    ĐANG XEM
                </div>
            )}

            <div style={{ padding: '12px 14px 10px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                    <div style={{
                        display: 'inline-block',
                        background: 'var(--gold-light)',
                        border: '1px solid var(--gold-border)',
                        borderRadius: '6px',
                        padding: '2px 8px',
                        fontSize: '10px',
                        color: 'var(--gold-primary)',
                        fontWeight: '600'
                    }}>
                        Outfit {index + 1}
                    </div>
                    {outfit.name && (
                        <div style={{ fontSize: '13px', fontWeight: '600', color: 'var(--text-primary)', marginTop: '4px' }}>
                            {outfit.name}
                        </div>
                    )}
                    {/* Mini product thumbnails */}
                    <div style={{
                        display: 'flex',
                        gap: '4px',
                        marginTop: '8px',
                    }}>
                        {items.slice(0, 3).map((p: any, i: number) => {
                            const pImage = p.image || p.thumbnail || p.img || p.imageUrl || p.images?.[0];
                            return (
                                <div key={i} style={{
                                    width: '36px',
                                    height: '44px',
                                    borderRadius: '6px',
                                    overflow: 'hidden',
                                    background: 'var(--gold-light)',
                                    border: '1px solid var(--gold-border)',
                                    flexShrink: 0,
                                }}>
                                    {pImage && (
                                        <img
                                            src={pImage}
                                            alt=""
                                            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                                        />
                                    )}
                                </div>
                            );
                        })}
                        {items.length > 3 && (
                            <div style={{
                                width: '36px', height: '44px',
                                borderRadius: '6px',
                                background: 'var(--gold-light)',
                                border: '1px solid var(--gold-border)',
                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                fontSize: '10px', color: 'var(--gold-primary)', fontWeight: '600',
                            }}>
                                +{items.length - 3}
                            </div>
                        )}
                    </div>
                </div>
                {!isSelected && (
                    <div style={{ fontSize: '13px', fontWeight: '700', color: scoreColor }}>
                        {score}%
                    </div>
                )}
                {isSelected && <div style={{ width: 60 }} />}
            </div>

            <div style={{ margin: '0 14px 10px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <div style={{ fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.06em', minWidth: '28px', display: 'flex', alignItems: 'center', gap: '4px' }}>
                    <span style={{ color: 'var(--gold-primary)' }}>⭐</span> ĐỘ PHÙ HỢP
                </div>
                <div style={{ flex: 1, height: '6px', background: 'var(--gold-light)', borderRadius: '3px', position: 'relative', overflow: 'hidden' }}>
                    <div style={{
                        position: 'absolute',
                        left: 0,
                        top: 0,
                        height: '6px',
                        borderRadius: '3px',
                        background: scoreFill,
                        width: `${score}%`,
                        transition: 'width 0.6s ease 0.1s'
                    }} />
                </div>
                <div style={{ fontSize: '11px', fontWeight: '700', color: scoreColor }}>{score}%</div>
            </div>

            <div style={{ padding: '0 14px 10px', display: 'flex', flexDirection: 'column', gap: '6px' }}>
                {items.map((item, i) => {
                    const isCloset = item.source === 'closet' || item.owned || (item as any).fromCloset || (item as any).inCloset;
                    const itemImage = (item as any).image || (item as any).thumbnail || (item as any).img || (item as any).imageUrl || (item as any).images?.[0];
                    return (
                        <div
                            key={i}
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: '10px',
                                padding: '8px 10px',
                                background: 'var(--surface-subtle)',
                                borderRadius: '10px',
                                marginBottom: '6px',
                                cursor: 'pointer',
                                transition: 'background 0.15s',
                            }}
                            onMouseEnter={e => e.currentTarget.style.background = 'var(--gold-light)'}
                            onMouseLeave={e => e.currentTarget.style.background = 'var(--surface-subtle)'}
                            onClick={(e) => {
                                e.stopPropagation();
                                onTryItem(item);
                            }}
                        >
                            {/* THUMBNAIL */}
                            <div style={{
                                width: '56px',
                                height: '68px',
                                flexShrink: 0,
                                borderRadius: '8px',
                                overflow: 'hidden',
                                background: 'var(--surface-card)',
                                border: '1px solid var(--gold-border)',
                            }}>
                                {itemImage ? (
                                    <img
                                        src={itemImage}
                                        alt={item.name}
                                        style={{
                                            width: '100%',
                                            height: '100%',
                                            objectFit: 'cover',
                                            display: 'block',
                                        }}
                                        onError={e => {
                                            e.currentTarget.style.display = 'none';
                                            if (e.currentTarget.parentElement) {
                                                e.currentTarget.parentElement.style.background = 'var(--gold-light)';
                                            }
                                        }}
                                    />
                                ) : (
                                    <div style={{
                                        width: '100%', height: '100%',
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        fontSize: '18px', opacity: 0.3,
                                    }}>
                                        👕
                                    </div>
                                )}
                            </div>

                            {/* PRODUCT INFO */}
                            <div style={{ flex: 1, minWidth: 0 }}>
                                <div style={{
                                    fontSize: '11px',
                                    fontWeight: '500',
                                    color: 'var(--text-primary)',
                                    lineHeight: '1.4',
                                    display: '-webkit-box',
                                    WebkitLineClamp: 2,
                                    WebkitBoxOrient: 'vertical',
                                    overflow: 'hidden',
                                    marginBottom: '4px',
                                }}>
                                    {item.name}
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '5px', flexWrap: 'wrap' }}>
                                    {isCloset ? (
                                        <span style={{
                                            background: 'rgba(76,175,80,0.1)',
                                            border: '1px solid rgba(76,175,80,0.3)',
                                            color: '#4CAF50',
                                            borderRadius: '4px',
                                            padding: '1px 6px',
                                            fontSize: '9px',
                                            fontWeight: '600',
                                            letterSpacing: '0.04em',
                                        }}>TỦ ĐỒ ✓</span>
                                    ) : (
                                        <span style={{
                                            background: 'var(--gold-light)',
                                            border: '1px solid var(--gold-border)',
                                            color: 'var(--gold-primary)',
                                            borderRadius: '4px',
                                            padding: '1px 6px',
                                            fontSize: '9px',
                                            fontWeight: '500',
                                        }}>Mua mới</span>
                                    )}
                                </div>
                                {isSelected && (
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginTop: '6px', flexWrap: 'wrap' }}>
                                        {/* Color Selector */}
                                        <div style={{ display: 'flex', gap: '4px', alignItems: 'center' }}>
                                            {(() => {
                                                let colorsToRender = item.availableColors;
                                                const itemName = (item.name || '').toLowerCase();
                                                
                                                if (itemName.includes('áo')) {
                                                    colorsToRender = ['#f5f5f5', '#222222', '#47484c', '#d4c3a3']; // Trắng, Đen, Xám, Kaki
                                                } else if (itemName.includes('quần')) {
                                                    colorsToRender = ['#222222']; // Đen
                                                }

                                                const finalColors = (colorsToRender || ['#000000', '#ffffff', '#808080']).map((c: any) => typeof c === 'string' ? c : c.hex).filter(Boolean);
                                                
                                                return finalColors.map((c: string) => (
                                                    <div
                                                        key={c}
                                                        className={`oc-color-swatch ${item.selectedColor === c || (!item.selectedColor && item.color === c) ? 'selected' : ''}`}
                                                        style={{ background: c }}
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            onUpdateItem?.(outfit.id, item.id, { selectedColor: c });
                                                        }}
                                                    />
                                                ));
                                            })()}
                                            {/* fallback color picker if availableColors is just fake */}
                                            {!(item.name?.toLowerCase().includes('áo') || item.name?.toLowerCase().includes('quần')) && (
                                                <input 
                                                    type="color" 
                                                    value={item.selectedColor || item.color || '#000000'}
                                                    onChange={(e) => {
                                                        onUpdateItem?.(outfit.id, item.id, { selectedColor: e.target.value });
                                                    }}
                                                    onClick={e => e.stopPropagation()}
                                                    style={{ width: '20px', height: '20px', padding: 0, border: 'none', cursor: 'pointer', background: 'transparent' }}
                                                />
                                            )}
                                        </div>
                                        {/* Size Selector */}
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                            <select 
                                                className="oc-size-select"
                                                value={item.selectedSize || item.suggestedSize || 'M'}
                                                onChange={(e) => {
                                                    onUpdateItem?.(outfit.id, item.id, { selectedSize: e.target.value });
                                                }}
                                                onClick={e => e.stopPropagation()}
                                            >
                                                {(item.availableSizes || ['S', 'M', 'L', 'XL']).map((s: string) => (
                                                    <option key={s} value={s}>{s}</option>
                                                ))}
                                            </select>
                                            <span style={{ fontSize: '9px', color: 'var(--gold-primary)', background: 'var(--gold-light)', padding: '2px 4px', borderRadius: '4px' }}>AI Gợi ý</span>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* PRICE + ACTION */}
                            <div style={{
                                flexShrink: 0,
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'flex-end',
                                gap: '6px',
                            }}>
                                {item.price && (
                                    <span style={{
                                        fontSize: '12px',
                                        fontWeight: '700',
                                        color: 'var(--gold-primary)',
                                        whiteSpace: 'nowrap',
                                    }}>
                                        {typeof item.price === 'number'
                                            ? item.price.toLocaleString('vi-VN') + 'đ'
                                            : item.price}
                                    </span>
                                )}
                                <div style={{ display: 'flex', gap: '4px' }}>
                                        <button
                                            onClick={e => {
                                                e.stopPropagation();
                                                onTryItem(item);
                                            }}
                                            style={{
                                                background: 'var(--gold-primary)',
                                                border: '1px solid var(--gold-primary)',
                                                borderRadius: '6px',
                                                padding: '3px 8px',
                                                fontSize: '9px',
                                                fontWeight: '600',
                                                color: '#0F0B07',
                                                cursor: 'pointer',
                                                whiteSpace: 'nowrap',
                                                transition: 'all 0.15s',
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: '4px'
                                            }}
                                            onMouseEnter={e => {
                                                e.currentTarget.style.opacity = '0.9';
                                            }}
                                            onMouseLeave={e => {
                                                e.currentTarget.style.opacity = '1';
                                            }}
                                        >
                                            <span>✨</span> Thử ngay
                                        </button>
                                    <button
                                        onClick={e => {
                                            e.stopPropagation();
                                            const productId = (item as any)._id || item.id || (item as any).productId;
                                            if (productId) {
                                                window.open(`/product/${productId}`, '_blank');
                                            }
                                        }}
                                        style={{
                                            background: 'transparent',
                                            border: '1px solid var(--gold-border)',
                                            borderRadius: '6px',
                                            padding: '3px 8px',
                                            fontSize: '9px',
                                            color: 'var(--gold-primary)',
                                            cursor: 'pointer',
                                            whiteSpace: 'nowrap',
                                            transition: 'all 0.15s',
                                        }}
                                        onMouseEnter={e => {
                                            e.currentTarget.style.background = 'var(--gold-primary)';
                                            e.currentTarget.style.color = '#0F0B07';
                                        }}
                                        onMouseLeave={e => {
                                            e.currentTarget.style.background = 'transparent';
                                            e.currentTarget.style.color = 'var(--gold-primary)';
                                        }}
                                    >
                                        Xem →
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>

            {isSelected && (
                <div style={{ borderTop: '1px solid var(--gold-divider)', padding: '12px 14px' }}>
                    <div style={{ display: 'flex', gap: '8px', marginBottom: '10px' }}>
                        <div style={{ fontSize: '16px' }}>✨</div>
                        <div style={{ fontSize: '11px', color: 'var(--text-primary)', lineHeight: 1.5, fontStyle: 'italic', opacity: 0.9 }}>
                            "Với phong cách Casual và ngân sách 2 triệu, tôi đề xuất outfit này vì sự thoải mái và phù hợp hoàn hảo."
                        </div>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                        <div style={{ fontSize: '11px', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '6px' }}>
                            <span style={{ color: 'var(--gold-primary)' }}>✓</span> Hợp dáng người
                        </div>
                        <div style={{ fontSize: '11px', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '6px' }}>
                            <span style={{ color: 'var(--gold-primary)' }}>✓</span> Hợp ngân sách
                        </div>
                        <div style={{ fontSize: '11px', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center', gap: '6px' }}>
                            <span style={{ color: 'var(--gold-primary)' }}>✓</span> Đúng phong cách
                        </div>
                    </div>
                    {outfit.aiReason && (
                        <div style={{ marginTop: '10px', fontSize: '11px', color: 'var(--text-secondary)', lineHeight: 1.5, opacity: 0.8, paddingTop: '10px', borderTop: '1px dashed var(--gold-border)' }}>
                            {outfit.aiReason}
                        </div>
                    )}
                </div>
            )}
            
            {/* Try Entire Outfit Banner */}
            {isSelected && outfit.items?.length > 0 && (
                <div style={{ padding: '0 14px 14px' }}>
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            onOpenTryonPanel?.(outfit.id);
                        }}
                        style={{
                            width: '100%',
                            background: 'linear-gradient(135deg, var(--gold-primary) 0%, #B8860B 100%)',
                            color: '#0F0B07',
                            border: 'none',
                            borderRadius: '8px',
                            padding: '10px',
                            fontSize: '13px',
                            fontWeight: '700',
                            cursor: 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: '8px',
                            transition: 'all 0.2s ease',
                            boxShadow: '0 4px 12px rgba(212,169,66,0.3)'
                        }}
                    >
                        <>
                            <span style={{ fontSize: '16px' }}>👕</span> Thử cả bộ Outfit này
                        </>
                    </button>
                </div>
            )}
        </div>
    );
}

import React from 'react';
import { useFittingRoom, type GarmentSlot } from '../../contexts/FittingRoomContext';

export default function OutfitColorPicker() {
    const { layeredGarments, applySilentWear } = useFittingRoom();

    const handleColorChange = (slot: GarmentSlot, color: string) => {
        const garment = layeredGarments[slot];
        if (garment) {
            applySilentWear({
                ...garment,
                purchasedColor: color,
            });
        }
    };

    const handleSaveToCloset = async (slot: GarmentSlot) => {
        const garment = layeredGarments[slot];
        if (!garment) return;
        
        // This is a placeholder for the actual API call
        console.log('Lưu vào tủ đồ:', {
            itemId: garment.itemId,
            size: garment.purchasedSize,
            color: garment.purchasedColor,
        });
        alert(`Đã lưu ${garment.name} vào tủ đồ!`);
    };

    const handleAddToCart = async (slot: GarmentSlot) => {
        const garment = layeredGarments[slot];
        if (!garment) return;
        
        // This is a placeholder for the actual API call
        console.log('Thêm vào giỏ hàng:', {
            itemId: garment.itemId,
            variantId: `${garment.purchasedSize}-${garment.purchasedColor}`,
        });
        alert(`Đã thêm ${garment.name} vào giỏ hàng!`);
    };

    const activeGarments = Object.entries(layeredGarments).filter(
        ([_, garment]) => garment && garment.model3D
    ) as [GarmentSlot, NonNullable<typeof layeredGarments[GarmentSlot]>][];

    if (activeGarments.length === 0) {
        return null;
    }

    return (
        <div className="outfit-color-picker-panel">
            <h4 className="ocp-title">Tuỳ chỉnh Outfit</h4>
            <div className="ocp-items">
                {activeGarments.map(([slot, garment]) => (
                    <div key={slot} className="ocp-item">
                        <div className="ocp-item-info">
                            <span className="ocp-item-name">{garment.name}</span>
                            {garment.purchasedSize && (
                                <span className="ocp-item-size">Size: {garment.purchasedSize}</span>
                            )}
                        </div>
                        
                        <div className="ocp-item-controls">
                            <label className="ocp-color-label">
                                <input
                                    type="color"
                                    value={garment.purchasedColor || '#000000'}
                                    onChange={(e) => handleColorChange(slot, e.target.value)}
                                    className="ocp-color-input"
                                />
                                <span className="ocp-color-hex">{garment.purchasedColor || '#000000'}</span>
                            </label>
                            
                            <div className="ocp-actions">
                                <button 
                                    onClick={() => handleSaveToCloset(slot)}
                                    className="ocp-btn ocp-btn-save"
                                    title="Lưu vào tủ đồ"
                                >
                                    💾 Lưu
                                </button>
                                <button 
                                    onClick={() => handleAddToCart(slot)}
                                    className="ocp-btn ocp-btn-cart"
                                    title="Thêm vào giỏ hàng"
                                >
                                    🛒 Mua
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            <style>{`
                .outfit-color-picker-panel {
                    position: absolute;
                    bottom: 20px;
                    right: 20px;
                    background: rgba(33, 28, 23, 0.95);
                    border: 1px solid rgba(200, 168, 103, 0.3);
                    border-radius: 12px;
                    padding: 16px;
                    width: 280px;
                    backdrop-filter: blur(10px);
                    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
                    z-index: 100;
                    color: white;
                }

                .ocp-title {
                    margin: 0 0 12px 0;
                    font-size: 14px;
                    font-weight: 600;
                    color: rgba(200, 168, 103, 0.9);
                    text-transform: uppercase;
                    letter-spacing: 0.05em;
                    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
                    padding-bottom: 8px;
                }

                .ocp-items {
                    display: flex;
                    flex-direction: column;
                    gap: 12px;
                    max-height: 300px;
                    overflow-y: auto;
                    scrollbar-width: thin;
                    scrollbar-color: rgba(200,168,103,0.5) transparent;
                }

                .ocp-item {
                    background: rgba(255, 255, 255, 0.05);
                    border-radius: 8px;
                    padding: 10px;
                    border: 1px solid rgba(255, 255, 255, 0.05);
                }

                .ocp-item-info {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    margin-bottom: 8px;
                }

                .ocp-item-name {
                    font-size: 12px;
                    font-weight: 500;
                    white-space: nowrap;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    max-width: 160px;
                }

                .ocp-item-size {
                    font-size: 10px;
                    background: rgba(200, 168, 103, 0.2);
                    color: #f5d9a0;
                    padding: 2px 6px;
                    border-radius: 4px;
                }

                .ocp-item-controls {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                }

                .ocp-color-label {
                    display: flex;
                    align-items: center;
                    gap: 6px;
                    cursor: pointer;
                }

                .ocp-color-input {
                    -webkit-appearance: none;
                    -moz-appearance: none;
                    appearance: none;
                    width: 24px;
                    height: 24px;
                    background: transparent;
                    border: none;
                    cursor: pointer;
                    padding: 0;
                }

                .ocp-color-input::-webkit-color-swatch-wrapper {
                    padding: 0;
                }

                .ocp-color-input::-webkit-color-swatch {
                    border: 2px solid rgba(255,255,255,0.2);
                    border-radius: 4px;
                }

                .ocp-color-hex {
                    font-size: 11px;
                    font-family: monospace;
                    color: rgba(255, 255, 255, 0.6);
                }

                .ocp-actions {
                    display: flex;
                    gap: 6px;
                }

                .ocp-btn {
                    background: transparent;
                    border: 1px solid rgba(255,255,255,0.1);
                    color: rgba(255,255,255,0.8);
                    border-radius: 4px;
                    padding: 4px 8px;
                    font-size: 11px;
                    cursor: pointer;
                    transition: all 0.2s;
                }

                .ocp-btn:hover {
                    background: rgba(255,255,255,0.1);
                    color: white;
                }

                .ocp-btn-save:hover {
                    border-color: rgba(200, 168, 103, 0.6);
                    color: #f5d9a0;
                }

                .ocp-btn-cart:hover {
                    background: rgba(238, 77, 45, 0.2);
                    border-color: rgba(238, 77, 45, 0.5);
                    color: #ff9d8a;
                }
            `}</style>
        </div>
    );
}

