import { useState, useEffect, useMemo } from 'react';
import type { OutfitResult, OutfitItem } from '../../types/outfit';

interface TryOnPanelProps {
    isOpen: boolean;
    outfits: OutfitResult[];
    currentIndex: number;
    closetItems?: any[];
    onClose: () => void;
    onIndexChange: (index: number) => void;
    onUpdateItem: (outfitId: string, itemId: string, updates: Partial<OutfitItem>) => void;
    onAddToCart: (outfit: OutfitResult) => void;
    onBuyNow: (outfit: OutfitResult) => void;
    onTryOutfit?: (outfit: OutfitResult) => void;
}

export default function TryOnPanel({
    isOpen,
    outfits,
    currentIndex,
    closetItems = [],
    onClose,
    onIndexChange,
    onUpdateItem,
    onAddToCart,
    onBuyNow,
    onTryOutfit
}: TryOnPanelProps) {
    const [isAnimating, setIsAnimating] = useState(false);
    const [selectedForPurchase, setSelectedForPurchase] = useState<Record<string, boolean>>({});
    
    // Check if an item is owned based on current size/color variant
    const checkIsOwned = (item: OutfitItem) => {
        const size = item.selectedSize || item.suggestedSize || 'M';
        const color = item.selectedColor || item.color;
        // Find if this exact variant is in closet
        return closetItems.some(c => 
            String(c.productId) === String(item.id) && 
            c.size === size && 
            (c.colorHex === color || c.color === color)
        );
    };

    const outfit = outfits[currentIndex];

    // Initialize selection when outfit changes
    useEffect(() => {
        if (!outfit) return;
        const initialSelection: Record<string, boolean> = {};
        outfit.items.forEach(item => {
            const isOwned = checkIsOwned(item);
            initialSelection[item.id] = !isOwned;
        });
        setSelectedForPurchase(initialSelection);
    }, [outfit?.id, closetItems]);

    // Update selection dynamically when size or color changes
    useEffect(() => {
        if (!outfit) return;
        setSelectedForPurchase(prev => {
            const next = { ...prev };
            let changed = false;
            outfit.items.forEach(item => {
                const isOwned = checkIsOwned(item);
                // Only automatically uncheck if it becomes owned and was previously checked,
                // or check if it becomes unowned and was previously unchecked.
                // Wait, if user manually toggled, we might not want to override, 
                // but for simplicity we re-evaluate default if it changes status.
                const shouldBeSelected = !isOwned;
                if (isOwned && prev[item.id] === true) {
                    next[item.id] = false;
                    changed = true;
                } else if (!isOwned && prev[item.id] === false) {
                    next[item.id] = true;
                    changed = true;
                }
            });
            return changed ? next : prev;
        });
    }, [outfit, closetItems]);

    // Prevent rendering if not open and not animating
    if (!isOpen && !isAnimating) return null;
    if (!outfit) return null;

    const handleAnimationEnd = () => {
        if (!isOpen) {
            setIsAnimating(false);
        }
    };

    const togglePurchase = (itemId: string) => {
        setSelectedForPurchase(prev => ({ ...prev, [itemId]: !prev[itemId] }));
    };

    const isAllSelected = outfit.items.every(item => selectedForPurchase[item.id]);
    const toggleAllPurchase = () => {
        const nextState = !isAllSelected;
        const nextSelection: Record<string, boolean> = {};
        outfit.items.forEach(item => {
            nextSelection[item.id] = nextState;
        });
        setSelectedForPurchase(nextSelection);
    };

    const selectedItems = outfit.items.filter(item => selectedForPurchase[item.id]);
    const currentTotalPrice = selectedItems.reduce((sum, item) => sum + (item.price || 0), 0);

    const handleBuyAction = (action: (outfit: OutfitResult) => void) => {
        if (selectedItems.length === 0) {
            alert('Vui lòng chọn ít nhất 1 sản phẩm để mua!');
            return;
        }
        action({ ...outfit, items: selectedItems, totalPrice: currentTotalPrice });
    };

    return (
        <div 
            className={`tryon-panel-container ${isOpen ? 'open' : 'closed'}`}
            onAnimationEnd={handleAnimationEnd}
            style={{
                position: 'absolute',
                top: 0,
                right: 0,
                bottom: 0,
                width: '380px',
                background: 'var(--surface-elevated)',
                borderLeft: '1px solid var(--gold-divider)',
                zIndex: 50,
                display: 'flex',
                flexDirection: 'column',
                transform: isOpen ? 'translateX(0)' : 'translateX(100%)',
                transition: 'transform 250ms ease-in-out',
                boxShadow: '-8px 0 32px rgba(0,0,0,0.1)'
            }}
        >
            <style>{`
                @media (prefers-reduced-motion: reduce) {
                    .tryon-panel-container {
                        transition: none !important;
                    }
                }
                .top-item-card {
                    background: var(--surface-subtle);
                    border: 1px solid var(--gold-border);
                    border-radius: 12px;
                    padding: 12px;
                    margin-bottom: 12px;
                    position: relative;
                }
            `}</style>
            
            {/* Header */}
            <div style={{
                padding: '16px',
                borderBottom: '1px solid var(--gold-divider)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between'
            }}>
                <div>
                    <h3 style={{ margin: 0, fontSize: '16px', color: 'var(--text-primary)' }}>{outfit.name || `Outfit ${currentIndex + 1}`}</h3>
                    <div style={{ fontSize: '12px', color: 'var(--gold-primary)', fontWeight: '600', marginTop: '4px' }}>
                        {outfit.matchScore}% Phù hợp
                    </div>
                </div>
                
                <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                    {/* Navigation */}
                    <div style={{ display: 'flex', background: 'var(--surface-subtle)', borderRadius: '20px', padding: '2px' }}>
                        <button 
                            onClick={() => onIndexChange(currentIndex > 0 ? currentIndex - 1 : outfits.length - 1)}
                            style={{ background: 'transparent', border: 'none', padding: '4px 8px', cursor: 'pointer', color: 'var(--text-secondary)' }}
                        >
                            ←
                        </button>
                        <span style={{ fontSize: '12px', padding: '4px 8px', color: 'var(--text-primary)' }}>
                            {currentIndex + 1} / {outfits.length}
                        </span>
                        <button 
                            onClick={() => onIndexChange((currentIndex + 1) % outfits.length)}
                            style={{ background: 'transparent', border: 'none', padding: '4px 8px', cursor: 'pointer', color: 'var(--text-secondary)' }}
                        >
                            →
                        </button>
                    </div>
                    
                    <button 
                        onClick={onClose}
                        style={{ background: 'transparent', border: 'none', fontSize: '20px', cursor: 'pointer', color: 'var(--text-secondary)' }}
                    >
                        ✕
                    </button>
                </div>
            </div>

            {/* Scrollable Content */}
            <div style={{ flex: 1, overflowY: 'auto', padding: '16px' }}>
                <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '12px', color: 'var(--text-primary)' }}>
                    Các món đồ trong Outfit
                </div>
                
                {outfit.items.map(item => {
                    const isOwned = checkIsOwned(item);
                    const isSelected = selectedForPurchase[item.id] || false;
                    
                    return (
                        <div key={item.id} className="top-item-card" style={{ border: isSelected ? '1px solid var(--gold-primary)' : '1px solid var(--gold-border)' }}>
                            <div style={{ display: 'flex', gap: '12px' }}>
                                {/* Checkbox & Thumbnail */}
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', alignItems: 'center' }}>
                                    <input 
                                        type="checkbox" 
                                        checked={isSelected}
                                        onChange={() => togglePurchase(item.id)}
                                        style={{ cursor: 'pointer', width: '16px', height: '16px', accentColor: 'var(--gold-primary)' }}
                                    />
                                    <div style={{ width: '60px', height: '76px', borderRadius: '8px', overflow: 'hidden', background: 'var(--surface-card)', flexShrink: 0 }}>
                                        <img 
                                            src={item.imageUrl || (item as any).image || (item as any).thumbnail} 
                                            alt={item.name}
                                            style={{ width: '100%', height: '100%', objectFit: 'cover', opacity: isSelected ? 1 : 0.6 }}
                                        />
                                    </div>
                                </div>
                                
                                {/* Details */}
                                <div style={{ flex: 1 }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                        <div style={{ fontSize: '12px', fontWeight: '500', color: 'var(--text-primary)', marginBottom: '4px', paddingRight: '8px' }}>
                                            {item.name}
                                        </div>
                                        {isOwned && (
                                            <span style={{ background: '#ecfdf5', color: '#047857', padding: '2px 6px', borderRadius: '4px', fontSize: '10px', fontWeight: '600', whiteSpace: 'nowrap' }}>
                                                ✓ Đã có
                                            </span>
                                        )}
                                    </div>
                                    <div style={{ fontSize: '13px', fontWeight: '700', color: isSelected ? 'var(--gold-primary)' : 'var(--text-secondary)', marginBottom: '8px' }}>
                                        {typeof item.price === 'number' ? item.price.toLocaleString('vi-VN') + 'đ' : item.price}
                                    </div>
                                    
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                                        {/* Color Picker */}
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <span style={{ fontSize: '11px', color: 'var(--text-secondary)', width: '30px' }}>Màu:</span>
                                            <div style={{ display: 'flex', gap: '6px' }}>
                                                {(() => {
                                                    let colorsToRender = item.availableColors;
                                                    const itemName = (item.name || '').toLowerCase();
                                                    
                                                    if (itemName.includes('áo')) {
                                                        colorsToRender = ['#f5f5f5', '#222222', '#47484c', '#d4c3a3']; // Trắng, Đen, Xám, Kaki
                                                    } else if (itemName.includes('quần')) {
                                                        colorsToRender = ['#222222']; // Đen
                                                    }

                                                    const finalColors = (colorsToRender && colorsToRender.length > 0 ? colorsToRender : ['#000000', '#ffffff', '#808080'])
                                                        .map((c: any) => typeof c === 'string' ? c : c.hex)
                                                        .filter(Boolean);

                                                    return finalColors.map((hex: string, cIdx: number) => {
                                                        const isColorSelected = (item.selectedColor || item.color) === hex;
                                                        
                                                        return (
                                                            <div 
                                                                key={hex || cIdx}
                                                                onClick={() => onUpdateItem(outfit.id, item.id, { selectedColor: hex })}
                                                                style={{ 
                                                                    width: '20px', height: '20px', borderRadius: '50%', cursor: 'pointer',
                                                                    background: hex,
                                                                    border: isColorSelected ? '2px solid var(--gold-primary)' : '1px solid rgba(0,0,0,0.1)',
                                                                    transform: isColorSelected ? 'scale(1.1)' : 'none'
                                                                }}
                                                            />
                                                        );
                                                    });
                                                })()}
                                                {!(item.name?.toLowerCase().includes('áo') || item.name?.toLowerCase().includes('quần')) && (!item.availableColors || item.availableColors.length === 0) && (
                                                    <input 
                                                        type="color" 
                                                        value={item.selectedColor || item.color || '#000000'}
                                                        onChange={(e) => onUpdateItem(outfit.id, item.id, { selectedColor: e.target.value })}
                                                        style={{ width: '22px', height: '22px', padding: 0, border: 'none', cursor: 'pointer', background: 'transparent' }}
                                                    />
                                                )}
                                            </div>
                                        </div>
                                        
                                        {/* Size Picker */}
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <span style={{ fontSize: '11px', color: 'var(--text-secondary)', width: '30px' }}>Size:</span>
                                            <select 
                                                value={item.selectedSize || item.suggestedSize || 'M'}
                                                onChange={(e) => onUpdateItem(outfit.id, item.id, { selectedSize: e.target.value })}
                                                style={{
                                                    background: 'var(--surface-card)',
                                                    border: '1px solid var(--gold-border)',
                                                    color: 'var(--text-primary)',
                                                    borderRadius: '4px',
                                                    padding: '4px 8px',
                                                    fontSize: '11px',
                                                    outline: 'none',
                                                }}
                                            >
                                                {(item.availableSizes || ['S', 'M', 'L', 'XL']).map(s => (
                                                    <option key={s} value={s}>{s} {item.suggestedSize === s ? '(AI Gợi ý)' : ''}</option>
                                                ))}
                                            </select>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Footer */}
            <div style={{
                padding: '16px',
                borderTop: '1px solid var(--gold-divider)',
                display: 'flex',
                flexDirection: 'column',
                gap: '10px'
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                    <input 
                        type="checkbox" 
                        id="selectAllItems"
                        checked={isAllSelected}
                        onChange={toggleAllPurchase}
                        style={{ cursor: 'pointer', width: '14px', height: '14px', accentColor: 'var(--gold-primary)' }}
                    />
                    <label htmlFor="selectAllItems" style={{ fontSize: '12px', color: 'var(--text-primary)', cursor: 'pointer', fontWeight: '500' }}>
                        Chọn tất cả ({selectedItems.length}/{outfit.items.length})
                    </label>
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                    <span style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>Tổng thanh toán</span>
                    <span style={{ fontSize: '16px', fontWeight: '700', color: 'var(--gold-primary)' }}>
                        {currentTotalPrice.toLocaleString('vi-VN')}đ
                    </span>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <button 
                        onClick={() => handleBuyAction(onAddToCart)}
                        style={{
                            flex: 1,
                            background: 'transparent',
                            border: '1px solid var(--gold-primary)',
                            color: 'var(--gold-primary)',
                            padding: '10px',
                            borderRadius: '8px',
                            fontWeight: '600',
                            fontSize: '13px',
                            cursor: 'pointer',
                            opacity: selectedItems.length === 0 ? 0.5 : 1
                        }}
                    >
                        Thêm giỏ hàng
                    </button>
                    {onTryOutfit && (
                        <button 
                            onClick={() => onTryOutfit(outfit)}
                            style={{
                                flex: 1,
                                background: '#10b981',
                                border: 'none',
                                color: '#fff',
                                padding: '10px',
                                borderRadius: '8px',
                                fontWeight: '600',
                                fontSize: '13px',
                                cursor: 'pointer'
                            }}
                        >
                            Mặc thử Outfit
                        </button>
                    )}
                    <button 
                        onClick={() => handleBuyAction(onBuyNow)}
                        style={{
                            flex: 1,
                            background: 'var(--gold-primary)',
                            border: 'none',
                            color: '#0F0B07',
                            padding: '10px',
                            borderRadius: '8px',
                            fontWeight: '600',
                            fontSize: '13px',
                            cursor: 'pointer',
                            opacity: selectedItems.length === 0 ? 0.5 : 1
                        }}
                    >
                        Mua ngay
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useRef, useEffect } from 'react';

type MeasurementData = {
  height: number;
  weight: number;
  chest: number;
  waist: number;
  hip: number;
  shoulder: number;
  [key: string]: number;
};

interface PhotoUploadFlowProps {
  onComplete: (measurements: MeasurementData) => void;
  onSwitchToManual: () => void;
}

export default function PhotoUploadFlow({ onComplete, onSwitchToManual }: PhotoUploadFlowProps) {
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [frontPhoto, setFrontPhoto] = useState<string | null>(null);
  const [sidePhoto, setSidePhoto] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisMessage, setAnalysisMessage] = useState('Đang chuẩn bị...');
  const [estimatedMeasurements, setEstimatedMeasurements] = useState<MeasurementData | null>(null);

  // ─── BƯỚC 3: AI đang phân tích (Mock) ───
  useEffect(() => {
    if (step === 3) {
      const analyzePhotos = async () => {
        setIsAnalyzing(true);
        
        // Simulate AI processing stages
        const stages = [
          { message: 'Đang phát hiện điểm mốc cơ thể...', duration: 1200 },
          { message: 'Đang tính toán tỷ lệ các chiều...', duration: 1000 },
          { message: 'Đang ước tính số đo 3D...', duration: 1400 },
          { message: 'Đang hiệu chỉnh với dữ liệu chuẩn...', duration: 800 },
          { message: 'Hoàn tất phân tích!', duration: 600 },
        ];
        
        for (const stage of stages) {
          setAnalysisMessage(stage.message);
          await new Promise(resolve => setTimeout(resolve, stage.duration));
        }
        
        // Mock estimated measurements
        setEstimatedMeasurements({
          height: 165,
          weight: 55,
          chest: 86,
          waist: 68,
          hip: 92,
          shoulder: 38,
        });
        
        setIsAnalyzing(false);
        setStep(4);
      };
      
      analyzePhotos();
    }
  }, [step]);

  return (
    <div style={{ padding: '0 4px' }}>
      
      {/* ─── BƯỚC 1: Hướng dẫn chụp ảnh ─── */}
      {step === 1 && (
        <div style={{ textAlign: 'center', padding: '8px 0 24px' }}>
          {/* Icon */}
          <div style={{
            width: '64px', height: '64px',
            background: 'var(--gold-light)',
            border: '1px solid var(--gold-border)',
            borderRadius: '50%',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            margin: '0 auto 16px',
            fontSize: '28px',
          }}>📸</div>

          <div style={{
            fontSize: '18px', fontWeight: '600',
            color: 'var(--text-primary)', marginBottom: '6px',
          }}>
            AI đo số đo từ ảnh của bạn
          </div>
          <div style={{
            fontSize: '12px', color: 'var(--text-secondary)',
            lineHeight: '1.6', marginBottom: '24px',
          }}>
            Cần 2 ảnh để AI phân tích chính xác nhất
          </div>

          {/* 2 instruction cards */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '24px' }}>
            {/* Card ảnh mặt trước */}
            <div style={{
              background: 'var(--surface-subtle)',
              border: '1px solid var(--gold-border)',
              borderRadius: '12px', padding: '16px 12px',
            }}>
              <svg width="48" height="80" viewBox="0 0 48 80" style={{ margin: '0 auto 10px', display: 'block' }}>
                <circle cx="24" cy="10" r="8" fill="none" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="24" y1="18" x2="24" y2="50" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="24" y1="26" x2="10" y2="40" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="24" y1="26" x2="38" y2="40" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="24" y1="50" x2="16" y2="72" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="24" y1="50" x2="32" y2="72" stroke="var(--gold-primary)" strokeWidth="1.5"/>
              </svg>
              <div style={{ fontSize: '11px', fontWeight: '600', color: 'var(--text-primary)', marginBottom: '4px' }}>
                Ảnh mặt trước
              </div>
              <div style={{ fontSize: '10px', color: 'var(--text-secondary)', lineHeight: '1.4' }}>
                Đứng thẳng, nhìn thẳng, 2 tay thả tự nhiên
              </div>
            </div>

            {/* Card ảnh mặt bên */}
            <div style={{
              background: 'var(--surface-subtle)',
              border: '1px solid var(--gold-border)',
              borderRadius: '12px', padding: '16px 12px',
            }}>
              <svg width="48" height="80" viewBox="0 0 48 80" style={{ margin: '0 auto 10px', display: 'block' }}>
                <circle cx="28" cy="10" r="8" fill="none" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="24" y1="18" x2="22" y2="50" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="23" y1="26" x2="12" y2="38" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="23" y1="28" x2="30" y2="42" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="22" y1="50" x2="18" y2="72" stroke="var(--gold-primary)" strokeWidth="1.5"/>
                <line x1="22" y1="50" x2="28" y2="72" stroke="var(--gold-primary)" strokeWidth="1.5"/>
              </svg>
              <div style={{ fontSize: '11px', fontWeight: '600', color: 'var(--text-primary)', marginBottom: '4px' }}>
                Ảnh mặt bên
              </div>
              <div style={{ fontSize: '10px', color: 'var(--text-secondary)', lineHeight: '1.4' }}>
                Đứng nghiêng 90°, nhìn thẳng phía trước
              </div>
            </div>
          </div>

          {/* Tips */}
          <div style={{
            background: 'var(--gold-light)',
            border: '1px solid var(--gold-border)',
            borderRadius: '10px', padding: '12px 14px',
            textAlign: 'left', marginBottom: '24px',
          }}>
            <div style={{ fontSize: '10px', color: 'var(--gold-primary)', fontWeight: '600',
              letterSpacing: '0.08em', marginBottom: '6px' }}>
              ✦ MẸO ĐỂ AI ĐO CHÍNH XÁC
            </div>
            {[
              'Mặc quần áo ôm sát hoặc đồ thể thao',
              'Chụp cách 1.5–2m, thấy toàn thân',
              'Nền tường sáng, ánh sáng đều',
              'Đứng thẳng, không cúi người',
            ].map((tip, i) => (
              <div key={i} style={{
                fontSize: '11px', color: 'var(--text-secondary)',
                display: 'flex', gap: '6px', marginBottom: '3px',
              }}>
                <span style={{ color: 'var(--gold-primary)' }}>•</span>
                {tip}
              </div>
            ))}
          </div>

          <button
            onClick={() => setStep(2)}
            style={{
              width: '100%',
              background: 'linear-gradient(135deg, var(--gold-primary), #E8B84B)',
              border: 'none', borderRadius: '12px',
              padding: '13px', fontSize: '13px', fontWeight: '600',
              color: '#0F0B07', cursor: 'pointer',
              letterSpacing: '0.03em',
              boxShadow: '0 4px 16px rgba(201,150,63,0.25)',
            }}
          >
            Bắt đầu chụp ảnh →
          </button>

          <button
            onClick={() => onSwitchToManual()}
            style={{
              background: 'transparent', border: 'none',
              color: 'var(--text-secondary)', fontSize: '11px',
              cursor: 'pointer', marginTop: '10px', padding: '4px',
              textDecoration: 'underline',
            }}
          >
            Nhập số đo thủ công
          </button>
        </div>
      )}

      {/* ─── BƯỚC 2: Upload 2 ảnh ─── */}
      {step === 2 && (
        <div style={{ padding: '8px 0' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '20px' }}>
            {[1, 2, 3, 4].map(s => (
              <React.Fragment key={s}>
                <div style={{
                  width: s <= step ? '24px' : '20px',
                  height: s <= step ? '24px' : '20px',
                  borderRadius: '50%',
                  background: s < step ? 'var(--gold-primary)'
                    : s === step ? 'var(--gold-light)'
                    : 'var(--surface-subtle)',
                  border: s === step ? '2px solid var(--gold-primary)'
                    : s < step ? 'none'
                    : '1px solid var(--gold-border)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '10px', fontWeight: '600',
                  color: s < step ? '#0F0B07' : s === step ? 'var(--gold-primary)' : 'var(--text-secondary)',
                  transition: 'all 0.2s',
                  flexShrink: 0,
                }}>
                  {s < step ? '✓' : s}
                </div>
                {s < 4 && (
                  <div style={{
                    flex: 1, height: '1px',
                    background: s < step ? 'var(--gold-primary)' : 'var(--gold-border)',
                    transition: 'background 0.3s',
                  }} />
                )}
              </React.Fragment>
            ))}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '24px' }}>
            <UploadZone label="front" photo={frontPhoto} setPhoto={setFrontPhoto} />
            <UploadZone label="side" photo={sidePhoto} setPhoto={setSidePhoto} />
          </div>

          <button
            onClick={() => setStep(3)}
            disabled={!frontPhoto || !sidePhoto}
            style={{
              width: '100%',
              background: (!frontPhoto || !sidePhoto) ? 'var(--surface-subtle)' : 'linear-gradient(135deg, var(--gold-primary), #E8B84B)',
              border: (!frontPhoto || !sidePhoto) ? '1px solid var(--gold-border)' : 'none',
              borderRadius: '12px',
              padding: '13px', fontSize: '13px', fontWeight: '600',
              color: (!frontPhoto || !sidePhoto) ? 'var(--text-secondary)' : '#0F0B07',
              cursor: (!frontPhoto || !sidePhoto) ? 'not-allowed' : 'pointer',
              letterSpacing: '0.03em',
              boxShadow: (!frontPhoto || !sidePhoto) ? 'none' : '0 4px 16px rgba(201,150,63,0.25)',
              opacity: (!frontPhoto || !sidePhoto) ? 0.45 : 1,
              transition: 'all 0.2s ease'
            }}
          >
            Tiếp tục phân tích →
          </button>
        </div>
      )}

      {/* ─── BƯỚC 3: AI đang phân tích ─── */}
      {step === 3 && (
        <div style={{ textAlign: 'center', padding: '32px 16px' }}>
          <div style={{ position: 'relative', width: '120px', height: '200px', margin: '0 auto 24px' }}>
            <svg width="120" height="200" viewBox="0 0 120 200">
              <circle cx="60" cy="24" r="20" fill="none" stroke="var(--gold-border)" strokeWidth="1.5"/>
              <line x1="60" y1="44" x2="60" y2="130" stroke="var(--gold-border)" strokeWidth="1.5"/>
              <line x1="60" y1="70" x2="28" y2="100" stroke="var(--gold-border)" strokeWidth="1.5"/>
              <line x1="60" y1="70" x2="92" y2="100" stroke="var(--gold-border)" strokeWidth="1.5"/>
              <line x1="60" y1="130" x2="42" y2="190" stroke="var(--gold-border)" strokeWidth="1.5"/>
              <line x1="60" y1="130" x2="78" y2="190" stroke="var(--gold-border)" strokeWidth="1.5"/>
              
              <line
                x1="20" y1="0" x2="100" y2="0"
                stroke="var(--gold-primary)" strokeWidth="2" opacity="0.8"
                style={{ animation: 'scanLine 2s ease-in-out infinite' }}
              />
              
              {[
                {cx:60, cy:24}, {cx:60, cy:60}, {cx:60, cy:90},
                {cx:60, cy:130}, {cx:42, cy:190}, {cx:78, cy:190}
              ].map((pt, i) => (
                <circle key={i} cx={pt.cx} cy={pt.cy} r="4"
                  fill="var(--gold-primary)" opacity="0.9"
                  style={{ animation: `dotAppear 0.3s ease ${i * 0.4}s both` }}
                />
              ))}
            </svg>
          </div>
          
          <div style={{
            fontSize: '13px', fontWeight: '500',
            color: 'var(--text-primary)', marginBottom: '8px',
            minHeight: '20px',
          }}>
            {analysisMessage}
          </div>
          
          <div style={{
            width: '200px', height: '3px',
            background: 'var(--gold-light)',
            borderRadius: '2px', margin: '0 auto 16px',
            overflow: 'hidden',
          }}>
            <div style={{
              height: '100%',
              background: 'linear-gradient(90deg, var(--gold-primary), #E8B84B)',
              borderRadius: '2px',
              animation: 'progressFill 5s linear forwards',
            }} />
          </div>
          
          <div style={{ fontSize: '11px', color: 'var(--text-secondary)', opacity: 0.6 }}>
            Đang xử lý ảnh của bạn...
          </div>
        </div>
      )}

      {/* ─── BƯỚC 4: Kết quả + Confirm ─── */}
      {step === 4 && (
        <div style={{ padding: '4px 0' }}>
          <div style={{
            display: 'flex', alignItems: 'center', gap: '10px',
            marginBottom: '16px',
          }}>
            <div style={{
              width: '36px', height: '36px',
              background: 'rgba(76,175,80,0.1)',
              border: '1px solid rgba(76,175,80,0.3)',
              borderRadius: '50%',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: '16px',
            }}>✓</div>
            <div>
              <div style={{ fontSize: '14px', fontWeight: '600', color: 'var(--text-primary)' }}>
                AI đã đo xong!
              </div>
              <div style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                Kiểm tra và điều chỉnh nếu cần
              </div>
            </div>
          </div>

          <div style={{
            background: 'var(--gold-light)',
            border: '1px solid var(--gold-border)',
            borderRadius: '10px', padding: '10px 14px',
            display: 'flex', justifyContent: 'space-between',
            alignItems: 'center', marginBottom: '16px',
          }}>
            <div style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
              Độ chính xác ước tính
            </div>
            <div style={{ fontSize: '14px', fontWeight: '700', color: 'var(--gold-primary)' }}>
              ~85–92%
            </div>
          </div>

          <div style={{
            display: 'grid', gridTemplateColumns: '1fr 1fr',
            gap: '8px', marginBottom: '20px',
          }}>
            {[
              { key: 'height', label: 'Chiều cao', unit: 'cm', icon: '↕' },
              { key: 'weight', label: 'Cân nặng', unit: 'kg', icon: '⚖' },
              { key: 'chest', label: 'Vòng ngực', unit: 'cm', icon: '○' },
              { key: 'waist', label: 'Vòng eo', unit: 'cm', icon: '○' },
              { key: 'hips', label: 'Vòng hông', unit: 'cm', icon: '○' },
              { key: 'shoulder', label: 'Vai rộng', unit: 'cm', icon: '↔' },
            ].map(field => (
              <div key={field.key} style={{
                background: 'var(--surface-subtle)',
                border: '1px solid var(--gold-border)',
                borderRadius: '10px', padding: '10px 12px',
              }}>
                <div style={{
                  fontSize: '9px', color: 'var(--text-secondary)',
                  letterSpacing: '0.08em', marginBottom: '4px',
                  display: 'flex', justifyContent: 'space-between',
                }}>
                  <span>{field.label}</span>
                  <span style={{ color: 'var(--gold-primary)', opacity: 0.6 }}>AI ✦</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                  <input
                    type="number"
                    value={estimatedMeasurements?.[field.key] || ''}
                    onChange={e => {
                      const val = parseFloat(e.target.value);
                      if (!isNaN(val)) {
                        setEstimatedMeasurements(prev => prev ? ({
                          ...prev,
                          [field.key]: val
                        }) : null);
                      }
                    }}
                    style={{
                      flex: 1, background: 'transparent',
                      border: 'none', outline: 'none',
                      fontSize: '18px', fontWeight: '700',
                      color: 'var(--text-primary)',
                      width: '100%',
                    }}
                  />
                  <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                    {field.unit}
                  </span>
                </div>
              </div>
            ))}
          </div>

          <div style={{
            fontSize: '10px', color: 'var(--text-secondary)',
            textAlign: 'center', marginBottom: '16px', opacity: 0.6,
          }}>
            Bạn có thể chỉnh số đo bằng cách nhấn vào ô
          </div>

          <button
            onClick={() => estimatedMeasurements && onComplete(estimatedMeasurements)}
            style={{
              width: '100%',
              background: 'linear-gradient(135deg, var(--gold-primary), #E8B84B)',
              border: 'none', borderRadius: '12px',
              padding: '13px', fontSize: '13px', fontWeight: '600',
              color: '#0F0B07', cursor: 'pointer',
              letterSpacing: '0.03em',
              boxShadow: '0 4px 16px rgba(201,150,63,0.25)',
              marginBottom: '8px',
            }}
          >
            Tạo avatar 3D với số đo này →
          </button>

          <button
            onClick={() => setStep(2)}
            style={{
              width: '100%', background: 'transparent',
              border: '1px solid var(--gold-border)',
              borderRadius: '12px', padding: '10px',
              fontSize: '12px', color: 'var(--text-secondary)',
              cursor: 'pointer',
            }}
          >
            ← Chụp lại ảnh
          </button>
        </div>
      )}
    </div>
  );
}

// ─── Component Phụ Trợ ───
function UploadZone({ label, photo, setPhoto }: { label: 'front'|'side', photo: string | null, setPhoto: (url: string) => void }) {
  const [isDragging, setIsDragging] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = (file?: File) => {
    if (!file || !file.type.startsWith('image/')) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      if (e.target?.result) {
        setPhoto(e.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div
      onClick={() => inputRef.current?.click()}
      onDragOver={e => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={e => { e.preventDefault(); setIsDragging(false); handleFile(e.dataTransfer.files?.[0]); }}
      style={{
        border: photo
          ? '1.5px solid var(--gold-primary)'
          : isDragging
          ? '1.5px dashed var(--gold-primary)'
          : '1.5px dashed var(--gold-border)',
        borderRadius: '14px',
        padding: photo ? '0' : '24px 16px',
        textAlign: 'center',
        cursor: 'pointer',
        background: photo ? 'transparent' : 'var(--surface-subtle)',
        transition: 'all 0.2s',
        overflow: 'hidden',
        aspectRatio: photo ? '3/4' : 'auto',
        position: 'relative',
      }}
    >
      {photo ? (
        <>
          <img src={photo} alt={label} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
          <div style={{
            position: 'absolute', inset: 0,
            background: 'rgba(15,11,7,0.6)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            opacity: 0, transition: 'opacity 0.2s',
          }}
          onMouseEnter={e => e.currentTarget.style.opacity = '1'}
          onMouseLeave={e => e.currentTarget.style.opacity = '0'}
          >
            <span style={{ color: '#fff', fontSize: '12px', fontWeight: '500' }}>Đổi ảnh</span>
          </div>
          <div style={{
            position: 'absolute', top: '8px', right: '8px',
            background: 'var(--gold-primary)', borderRadius: '50%',
            width: '22px', height: '22px',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '11px', color: '#0F0B07', fontWeight: '700',
          }}>✓</div>
        </>
      ) : (
        <>
          <div style={{ fontSize: '28px', marginBottom: '8px' }}>
            {label === 'front' ? '🧍' : '🧍'}
          </div>
          <div style={{ fontSize: '12px', fontWeight: '500', color: 'var(--text-primary)', marginBottom: '4px' }}>
            {label === 'front' ? 'Ảnh mặt trước' : 'Ảnh mặt bên'}
          </div>
          <div style={{ fontSize: '10px', color: 'var(--text-secondary)' }}>
            Nhấn hoặc kéo thả ảnh vào đây
          </div>
        </>
      )}
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        capture="user"
        style={{ display: 'none' }}
        onChange={e => handleFile(e.target.files?.[0])}
      />
    </div>
  );
}

import { Suspense } from 'react'
import { Grid, ContactShadows, Environment, Html } from '@react-three/drei'
import * as THREE from 'three'
import { Avatar } from '../../three/controls/avatar/Avatar'
import GarmentModel from '../../features/virtual-tryon/GarmentModel'
import type { Profile } from '../../contexts/FittingRoomContext'

function LoaderFallback() {
    return (
        <Html center>
            <div style={{ color: '#334155', fontSize: 14 }}>Đang tải mô hình...</div>
        </Html>
    )
}

export default function TryOnScene({
    body,
    onSceneReady,
    layeredGarments,
    showEnvironment = true,
    showContactShadows = true,
    showGrid = true,
}: {
    body: Profile | null | undefined
    onSceneReady?: (g: THREE.Group | null) => void
    layeredGarments?: Record<string, any>
    showEnvironment?: boolean
    showContactShadows?: boolean
    showGrid?: boolean
}) {
    return (
        <>
            {showEnvironment && <Environment preset="city" />}

            <group position={[0, -1.08, 0]}>
                {showGrid && <Grid position={[0, 0, 0]} args={[10, 10]} cellColor="#f3efe9" sectionColor="#ede9e2" fadeDistance={40} />}

                <Suspense fallback={<LoaderFallback />}>
                    <Avatar body={body} pose={'Idle'} skinColor="#F2C9AC" onSceneReady={onSceneReady} />

                    {layeredGarments && Object.entries(layeredGarments).map(([slot, garment]) => {
                        if (!garment?.model3D) return null

                        const config = garment.model3D;
                        const size = garment.purchasedSize || 'M';

                        return (
                            <Suspense key={`${slot}-${garment.itemId}`} fallback={null}>
                                <GarmentModel
                                    config={config}
                                    selectedSize={size}
                                    selectedColor={garment.purchasedColor}
                                    avatarScene={undefined}
                                    heatmapEnabled={false}
                                    avatarProfile={body}
                                />
                            </Suspense>
                        )
                    })}
                </Suspense>

                {showContactShadows && <ContactShadows position={[0, 0.01, 0]} opacity={0.08} blur={1} resolution={512} frames={1} />}
            </group>
        </>
    )
}

