/* eslint-disable react-refresh/only-export-components */
import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { sanitizeBodyMeasurements } from '../utils/bodyProfileConstraints';

export interface Profile {
    id: string;
    name: string;
    height: number;
    weight: number;
    chest: number;
    waist: number;
    hips: number;
    shoulder: number;
    arm: number;
    thigh: number;
    belly: number;
    legLength: number;
    skinTone?: string;
}

export type GarmentSlot = 'tops' | 'bottoms' | 'outerwear' | 'dresses';

export interface SilentWearItem {
    itemId: string;
    productId?: string | number;
    name: string;
    category: GarmentSlot;
    purchasedSize?: string;
    purchasedColor?: string;
    thumbnail?: string;
    source?: 'order' | 'fallback' | 'import';
    updatedAt: number;
    model3D?: Record<string, unknown>;
}

interface FittingRoomContextType {
    avatars: Profile[];
    currentAvatarId: string | null;
    currentAvatar: Profile;
    selectedSize: string | null;
    isHeatmapOpen: boolean;
    setCurrentAvatarId: (id: string) => void;
    setSelectedSize: (size: string | null) => void;
    toggleHeatmap: () => void;
    updateAvatar: (id: string, updates: Partial<Profile>) => void;
    addAvatar: (profile: Profile) => void;
    removeAvatar: (id: string) => void;

    // Backward-compatible aliases for existing Try-On code.
    profiles: Profile[];
    activeProfileId: string;
    activeProfile: Profile | null;
    setActiveProfileId: (id: string) => void;
    updateProfile: (id: string, updates: Partial<Profile>) => void;
    addProfile: (profile: Profile) => void;

    // Virtual closet silent-wear state.
    layeredGarments: Partial<Record<GarmentSlot, SilentWearItem>>;
    lastSilentWear: SilentWearItem | null;
    applySilentWear: (item: Omit<SilentWearItem, 'updatedAt'>) => void;
    applyFullOutfit: (items: Array<Omit<SilentWearItem, 'updatedAt'>>) => void;
}

const FittingRoomContext = createContext<FittingRoomContextType | undefined>(undefined);

const AVATARS_STORAGE_KEY = 'vfit_avatars';
const ACTIVE_AVATAR_STORAGE_KEY = 'vfit_current_avatar_id';

const DEFAULT_MEASUREMENTS: Omit<Profile, 'id' | 'name'> = {
    height: 165,
    weight: 55,
    chest: 85,
    waist: 68,
    hips: 92,
    shoulder: 38,
    arm: 26,
    thigh: 50,
    belly: 70,
    legLength: 95,
    skinTone: '#F2C9AC',
};

const GUEST_AVATAR: Profile = sanitizeBodyMeasurements({
    id: 'guest-avatar',
    name: 'Khách',
    ...DEFAULT_MEASUREMENTS,
});

const toNumber = (value: unknown, fallback: number) => {
    const parsed = typeof value === 'number' ? value : Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
};

const normalizeProfile = (input: unknown, index: number): Profile | null => {
    if (!input || typeof input !== 'object') {
        return null;
    }

    const candidate = input as Partial<Profile>;
    const id = typeof candidate.id === 'string' && candidate.id.trim().length > 0
        ? candidate.id.trim()
        : `avatar-${index + 1}`;
    const name = typeof candidate.name === 'string' && candidate.name.trim().length > 0
        ? candidate.name.trim()
        : `Avatar ${index + 1}`;

    return sanitizeBodyMeasurements({
        id,
        name,
        height: toNumber(candidate.height, DEFAULT_MEASUREMENTS.height),
        weight: toNumber(candidate.weight, DEFAULT_MEASUREMENTS.weight),
        chest: toNumber(candidate.chest, DEFAULT_MEASUREMENTS.chest),
        waist: toNumber(candidate.waist, DEFAULT_MEASUREMENTS.waist),
        hips: toNumber(candidate.hips, DEFAULT_MEASUREMENTS.hips),
        shoulder: toNumber(candidate.shoulder, DEFAULT_MEASUREMENTS.shoulder),
        arm: toNumber(candidate.arm, DEFAULT_MEASUREMENTS.arm),
        thigh: toNumber(candidate.thigh, DEFAULT_MEASUREMENTS.thigh),
        belly: toNumber(candidate.belly, DEFAULT_MEASUREMENTS.belly),
        legLength: toNumber(candidate.legLength, DEFAULT_MEASUREMENTS.legLength),
        skinTone: typeof candidate.skinTone === 'string' ? candidate.skinTone : DEFAULT_MEASUREMENTS.skinTone,
    });
};

const loadStoredAvatars = (): Profile[] => {
    if (typeof window === 'undefined') {
        return [];
    }

    try {
        const raw = localStorage.getItem(AVATARS_STORAGE_KEY);
        if (!raw) {
            return [];
        }

        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) {
            return [];
        }

        const normalized = parsed
            .map((item, index) => normalizeProfile(item, index))
            .filter((item): item is Profile => item !== null);

        const deduped = normalized.filter((profile, index, all) =>
            all.findIndex((item) => item.id === profile.id) === index,
        );

        return deduped;
    } catch {
        return [];
    }
};

const loadStoredActiveAvatarId = (): string | null => {
    if (typeof window === 'undefined') {
        return null;
    }

    const raw = localStorage.getItem(ACTIVE_AVATAR_STORAGE_KEY);
    if (!raw) {
        return null;
    }

    const id = raw.trim();
    return id.length > 0 ? id : null;
};

const generateAvatarId = () => `avatar-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

export const FittingRoomProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [avatars, setAvatars] = useState<Profile[]>(loadStoredAvatars);
    const [currentAvatarId, setCurrentAvatarIdState] = useState<string | null>(loadStoredActiveAvatarId);
    const [selectedSize, setSelectedSize] = useState<string | null>(null);
    const [isHeatmapOpen, setIsHeatmapOpen] = useState(false);
    const [layeredGarments, setLayeredGarments] = useState<Partial<Record<GarmentSlot, SilentWearItem>>>({});
    const [lastSilentWear, setLastSilentWear] = useState<SilentWearItem | null>(null);

    useEffect(() => {
        if (avatars.length === 0) {
            if (currentAvatarId !== null) {
                setCurrentAvatarIdState(null);
            }
            return;
        }

        if (!currentAvatarId || !avatars.some((avatar) => avatar.id === currentAvatarId)) {
            setCurrentAvatarIdState(avatars[0].id);
        }
    }, [avatars, currentAvatarId]);

    useEffect(() => {
        if (typeof window === 'undefined') {
            return;
        }

        if (avatars.length === 0) {
            localStorage.removeItem(AVATARS_STORAGE_KEY);
            return;
        }

        localStorage.setItem(AVATARS_STORAGE_KEY, JSON.stringify(avatars));
    }, [avatars]);

    useEffect(() => {
        if (typeof window === 'undefined') {
            return;
        }

        if (!currentAvatarId) {
            localStorage.removeItem(ACTIVE_AVATAR_STORAGE_KEY);
            return;
        }

        localStorage.setItem(ACTIVE_AVATAR_STORAGE_KEY, currentAvatarId);
    }, [currentAvatarId]);

    const activeAvatar = useMemo(
        () => avatars.find((avatar) => avatar.id === currentAvatarId) || null,
        [avatars, currentAvatarId],
    );

    const currentAvatar = activeAvatar || GUEST_AVATAR;

    const setCurrentAvatarId = (id: string) => {
        const normalizedId = id.trim();
        setCurrentAvatarIdState(normalizedId.length > 0 ? normalizedId : null);
    };

    const addAvatar = (profile: Profile) => {
        const sanitized = normalizeProfile(profile, avatars.length) || {
            ...GUEST_AVATAR,
            id: generateAvatarId(),
            name: `Avatar ${avatars.length + 1}`,
        };

        setAvatars((prev) => {
            const exists = prev.some((item) => item.id === sanitized.id);
            if (exists) {
                return prev.map((item) => (item.id === sanitized.id ? sanitized : item));
            }
            return [...prev, sanitized];
        });
        setCurrentAvatarIdState((prev) => prev || sanitized.id);
    };

    const updateAvatar = (id: string, updates: Partial<Profile>) => {
        setAvatars((prev) => prev.map((avatar) => {
            if (avatar.id !== id) {
                return avatar;
            }

            const nextName = typeof updates.name === 'string' && updates.name.trim().length > 0
                ? updates.name.trim()
                : avatar.name;

            return sanitizeBodyMeasurements({
                ...avatar,
                ...updates,
                id: avatar.id,
                name: nextName,
            });
        }));
    };

    const removeAvatar = (id: string) => {
        setAvatars((prev) => prev.filter((avatar) => avatar.id !== id));

        if (currentAvatarId === id) {
            setCurrentAvatarIdState(null);
        }
    };

    const applySilentWear = (item: Omit<SilentWearItem, 'updatedAt'>) => {
        const payload: SilentWearItem = {
            ...item,
            updatedAt: Date.now(),
        };

        setLayeredGarments((prev) => ({
            ...prev,
            [payload.category]: payload,
        }));
        setLastSilentWear(payload);
    };

    const applyFullOutfit = (items: Array<Omit<SilentWearItem, 'updatedAt'>>) => {
        const now = Date.now();
        const newGarments: Partial<Record<GarmentSlot, SilentWearItem>> = {};

        items.forEach((item) => {
            const payload: SilentWearItem = {
                ...item,
                updatedAt: now,
            };
            newGarments[payload.category] = payload;
        });

        setLayeredGarments(newGarments);
        if (items.length > 0) {
            setLastSilentWear({
                ...items[items.length - 1],
                updatedAt: now,
            } as SilentWearItem);
        }
    };

    const value: FittingRoomContextType = {
        avatars,
        currentAvatarId,
        currentAvatar,
        selectedSize,
        isHeatmapOpen,
        setCurrentAvatarId,
        setSelectedSize,
        toggleHeatmap: () => setIsHeatmapOpen((prev) => !prev),
        updateAvatar,
        addAvatar,
        removeAvatar,

        profiles: avatars,
        activeProfileId: currentAvatarId || '',
        activeProfile: activeAvatar,
        setActiveProfileId: setCurrentAvatarId,
        updateProfile: updateAvatar,
        addProfile: addAvatar,

        layeredGarments,
        lastSilentWear,
        applySilentWear,
        applyFullOutfit,
    };

    return (
        <FittingRoomContext.Provider value={value}>
            {children}
        </FittingRoomContext.Provider>
    );
};

export const useFittingRoom = () => {
    const context = useContext(FittingRoomContext);
    if (!context) {
        throw new Error('useFittingRoom must be used within a FittingRoomProvider');
    }
    return context;
};

import { Suspense, useEffect, useMemo, useRef } from 'react';
import { useFrame, useLoader } from '@react-three/fiber';
import * as THREE from 'three';
import { GLTFLoader, type GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone } from 'three/examples/jsm/utils/SkeletonUtils.js';
import { useAnimations } from '@react-three/drei';

import {
    applyGarmentColor,
    applyGarmentHeatmap,
    bindGarmentToAvatarSkeleton,
    createGarmentMorphBindings,
    type GarmentFabricProfile,
    type GarmentHeatmapZone,
    prepareGarmentMaterialsWithTuning,
    syncGarmentMorphTargets,
    setGarmentTargetColor,
    lerpGarmentColor,
} from './garmentBinding';

import type { FitZone } from './components/SizeRecommendation';

type GarmentSoftnessConfig = {
    morphInfluence?: number;
    morphSmoothing?: number;
    maxMorphInfluence?: number;
    roughness?: number;
    metalness?: number;
    envMapIntensity?: number;
    /** Small outward offset (in model units) to prevent body-through-cloth clipping. */
    skinOffset?: number;
};

type GarmentSizeConfig = {
    url: string;
    autoNormalize?: boolean;
    followAvatarBones?: boolean;
    /** Optional uniform scale to apply to the garment when rendered (1 = original). */
    scale?: number;
    /** Optional translation [x,y,z] (model units) applied after normalization and scaling. */
    translate?: [number, number, number];
    softness?: GarmentSoftnessConfig;
    fabric?: GarmentFabricProfile;
};

type GarmentConfig = {
    enable?: boolean;
    sizes?: Record<string, GarmentSizeConfig>;
    autoNormalize?: boolean;
    followAvatarBones?: boolean;
    softness?: GarmentSoftnessConfig;
    fabric?: GarmentFabricProfile;
};

type ResolvedGarmentConfig = {
    url: string;
    autoNormalize: boolean;
    followAvatarBones: boolean;
    softness: GarmentSoftnessConfig;
    fabric?: GarmentFabricProfile;
    garmentType?: string;
    scale: number;
    translate: [number, number, number];
};

interface GarmentModelProps {
    config?: GarmentConfig;
    selectedSize?: string | null;
    selectedColor?: string;
    fabricOverride?: GarmentFabricProfile;
    avatarScene?: THREE.Group | null;
    heatmapEnabled?: boolean;
    heatmapZones?: FitZone[];
    avatarProfile?: any;
}

const mergeSoftnessConfig = (
    base?: GarmentSoftnessConfig,
    override?: GarmentSoftnessConfig,
): GarmentSoftnessConfig => ({
    ...(base || {}),
    ...(override || {}),
});

const mergeFabricConfig = (
    base?: GarmentFabricProfile,
    override?: GarmentFabricProfile,
): GarmentFabricProfile | undefined => {
    const merged = {
        ...(base || {}),
        ...(override || {}),
    };

    return Object.keys(merged).length > 0 ? merged : undefined;
};

const resolveGarmentConfig = (
    config?: GarmentConfig,
    selectedSize?: string | null
): ResolvedGarmentConfig | null => {
    if (!config || config.enable === false) {
        return null;
    }

    const normalizedSize = String(selectedSize || 'M').trim().toUpperCase();
    const sizeConfig = config.sizes?.[normalizedSize];

    if (!sizeConfig?.url) {
        return null;
    }

    return {
        url: sizeConfig.url,
        autoNormalize: sizeConfig.autoNormalize ?? config.autoNormalize ?? true,
        followAvatarBones: sizeConfig.followAvatarBones ?? config.followAvatarBones ?? false,
        softness: mergeSoftnessConfig(config.softness, sizeConfig.softness),
        fabric: mergeFabricConfig(config.fabric, sizeConfig.fabric),
        garmentType: (config as any).measurementProfile?.garmentType,
        scale: typeof sizeConfig.scale === 'number' ? sizeConfig.scale : (typeof (config as any).scale === 'number' ? (config as any).scale : 1),
        translate: Array.isArray(sizeConfig.translate) ? sizeConfig.translate as [number, number, number] : (Array.isArray((config as any).translate) ? (config as any).translate as [number, number, number] : [0, 0, 0]),
    };
};

type GarmentInstanceProps = {
    garment: ResolvedGarmentConfig;
    selectedColor: string;
    fabricOverride?: GarmentFabricProfile;
    avatarScene: THREE.Group | null;
    heatmapEnabled: boolean;
    heatmapZones: GarmentHeatmapZone[];
    wireframeColor?: string;
    ghostOpacity?: number;
    emissiveIntensity?: number;
    avatarProfile?: any;
    config?: GarmentConfig;
    selectedSize?: string | null;
};

function GarmentInstance({
    garment,
    selectedColor,
    fabricOverride,
    avatarScene,
    heatmapEnabled,
    heatmapZones,
    wireframeColor,
    ghostOpacity,
    emissiveIntensity,
    avatarProfile,
    config,
    selectedSize,
}: GarmentInstanceProps) {
    const gltf = useLoader(GLTFLoader, garment.url) as GLTF;

    const garmentScaleFactors = useMemo(() => {
        let scaleX = 1;
        let scaleY = 1;
        let scaleZ = 1;

        if (avatarProfile && garment.followAvatarBones) {
            const safeHeight = Number.isFinite(avatarProfile.height) && avatarProfile.height > 0 ? avatarProfile.height : 165;
            const globalScale = Math.min(Math.max(safeHeight / 165, 0.75), 1.45);

            // Width axes (X, Z) map from product size -> Fixed physical width.
            // We must counteract the avatar's global uniform scale so the garment keeps its authored width.
            scaleX = 1 / globalScale;
            scaleZ = 1 / globalScale;
            
            // Length axis (Y) maps from avatar body.
            // The 3D skinning naturally stretches Y to match the avatar's bones.
            scaleY = 1; 
        }

        let sizeRatio = 1;
        let widthRatio = 1;
        const normalizedSize = String(selectedSize || 'M').trim().toUpperCase();
        const sizeSpecs = (config as any)?.measurementProfile?.sizeSpecs;
        if (sizeSpecs) {
            // Length Ratio (Y axis)
            const currentLength = sizeSpecs[normalizedSize]?.garmentLength;
            const refLength = sizeSpecs['M']?.garmentLength || (Object.values(sizeSpecs)[0] as any)?.garmentLength;
            if (currentLength && refLength) {
                sizeRatio = currentLength / refLength;
            }

            // Width Ratio (X, Z axes)
            // Use waist, hips, or chest to determine the proportional width difference between sizes
            const currentWidth = sizeSpecs[normalizedSize]?.waist || sizeSpecs[normalizedSize]?.hips || sizeSpecs[normalizedSize]?.chest;
            const refWidth = sizeSpecs['M']?.waist || sizeSpecs['M']?.hips || sizeSpecs['M']?.chest || (Object.values(sizeSpecs)[0] as any)?.waist || (Object.values(sizeSpecs)[0] as any)?.hips || (Object.values(sizeSpecs)[0] as any)?.chest;
            
            if (currentWidth && refWidth) {
                widthRatio = currentWidth / refWidth;
            }
        }

        return new THREE.Vector3(scaleX * widthRatio, scaleY * sizeRatio, scaleZ * widthRatio);
    }, [avatarProfile, garment.followAvatarBones, config, selectedSize]);

    const garmentScene = useMemo(() => {
        const cloned = clone(gltf.scene) as THREE.Group;
        const effectiveFabric = mergeFabricConfig(garment.fabric, fabricOverride);

        if (garment.autoNormalize) {
            const box = new THREE.Box3().setFromObject(cloned);
            if (!box.isEmpty()) {
                const center = box.getCenter(new THREE.Vector3());
                cloned.position.sub(center);
            }
        }

        try {
            if (typeof garment.scale === 'number' && Math.abs(garment.scale - 1) > 1e-6) {
                cloned.scale.multiplyScalar(garment.scale);
            }

            try {
                const t = garment.translate || [0, 0, 0];
                if (Array.isArray(t) && t.length === 3 && (t[0] !== 0 || t[1] !== 0 || t[2] !== 0)) {
                    cloned.position.add(new THREE.Vector3(t[0], t[1], t[2]));
                }
            } catch (innerErr) {}
        } catch (e) {
            console.warn('[GarmentModel] Failed to apply dress scale', e);
        }

        prepareGarmentMaterialsWithTuning(cloned, {
            roughness: garment.softness.roughness,
            metalness: garment.softness.metalness,
            envMapIntensity: garment.softness.envMapIntensity,
            fabricProfile: effectiveFabric,
        });

        if (ghostOpacity !== undefined) {
            cloned.traverse((child) => {
                const mesh = child as THREE.Mesh;
                if (mesh.isMesh) {
                    const originalMat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
                    const newMat = originalMat.clone() as THREE.MeshStandardMaterial;
                    newMat.transparent = true;
                    newMat.opacity = ghostOpacity;
                    newMat.depthWrite = false;
                    
                    if (emissiveIntensity !== undefined && emissiveIntensity > 0) {
                        newMat.emissive = new THREE.Color(wireframeColor || '#FFFFFF');
                        newMat.emissiveIntensity = emissiveIntensity;
                    }
                    
                    mesh.material = newMat;
                }
            });
        }
        return cloned;
    }, [
        fabricOverride,
        gltf.scene,
        garment.autoNormalize,
        garment.fabric,
        garment.softness.envMapIntensity,
        garment.softness.metalness,
        garment.softness.roughness,
        wireframeColor,
        ghostOpacity,
        emissiveIntensity,
    ]);

    const { actions, names } = useAnimations(gltf.animations, garmentScene);

    useEffect(() => {
        if (names.length > 0) {
            const actionName = names[0];
            if (actionName && actions[actionName]) {
                actions[actionName].reset().fadeIn(0.5).play();
            }
            return () => { actions[actionName]?.fadeOut(0.5); };
        }
    }, [actions, names]);

    const initialColorSet = useRef(false);

    useEffect(() => {
        if (!initialColorSet.current) {
            applyGarmentColor(garmentScene, selectedColor);
            initialColorSet.current = true;
        } else {
            setGarmentTargetColor(garmentScene, selectedColor);
        }
    }, [garmentScene, selectedColor]);

    useEffect(() => {
        applyGarmentHeatmap(garmentScene, heatmapEnabled, heatmapZones, avatarScene, garment.garmentType);
    }, [avatarScene, garmentScene, heatmapEnabled, heatmapZones, garment.garmentType]);

    const adaptiveSkinOffset = useMemo(() => {
        const baseOffset = garment.softness.skinOffset ?? 0;
        const highestTightSeverity = heatmapZones.reduce((maxSeverity, zone) => {
            if (zone.fit !== 'tight') {
                return maxSeverity;
            }
            const currentSeverity = typeof zone.severity === 'number'
                ? Math.min(1, Math.max(0, zone.severity))
                : Math.min(1, Math.abs(zone.delta) / 8);
            return Math.max(maxSeverity, currentSeverity);
        }, 0);

        // Increase cloth lift slightly in tight zones to reduce body clipping.
        return baseOffset + highestTightSeverity * 0.0022;
    }, [garment.softness.skinOffset, heatmapZones]);

    useEffect(() => {
        if (!garment.followAvatarBones || !avatarScene) {
            return;
        }

        // Capture all meshes and their original parents before binding.
        // bindGarmentToAvatarSkeleton() may reparent meshes via attach().
        const trackedMeshes: Array<{ mesh: THREE.Mesh; originalParent: THREE.Object3D | null }> = [];
        garmentScene.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
                const mesh = child as THREE.Mesh;
                trackedMeshes.push({ mesh, originalParent: mesh.parent });
            }
        });

        const bindResult = bindGarmentToAvatarSkeleton(
            garmentScene,
            avatarScene,
            adaptiveSkinOffset,
            garmentScaleFactors,
            garment.garmentType
        );

        if (bindResult.boundMeshCount === 0 && bindResult.attachedMeshCount === 0) {
            console.warn(`[GarmentModel] No mesh found to bind/attach for ${garment.url}`);
        }

        if (bindResult.missingBoneNames.length > 0) {
            console.warn(
                `[GarmentModel] Missing avatar bones while binding ${garment.url}: ${bindResult.missingBoneNames.join(', ')}`,
            );
        }

        // Cleanup: restore meshes to their original parent.
        // This keeps development StrictMode effect re-runs safe.
        return () => {
            for (const { mesh, originalParent } of trackedMeshes) {
                if (!originalParent) {
                    mesh.parent?.remove(mesh);
                    continue;
                }

                if (mesh.parent !== originalParent) {
                    originalParent.attach(mesh);
                }
            }
        };
    }, [adaptiveSkinOffset, avatarScene, garment.followAvatarBones, garment.url, garmentScene]);

    const morphBindings = useMemo(() => {
        if (!avatarScene) {
            return [];
        }

        const { bindings, mappedChannelCount } = createGarmentMorphBindings(garmentScene, avatarScene);
        if (mappedChannelCount === 0) {
            return [];
        }

        return bindings;
    }, [avatarScene, garmentScene]);

    useFrame((_, delta) => {
        if (morphBindings.length > 0) {
            syncGarmentMorphTargets(morphBindings, {
                influenceScale: garment.softness.morphInfluence,
                smoothing: garment.softness.morphSmoothing,
                maxInfluence: garment.softness.maxMorphInfluence,
            });
        }
        lerpGarmentColor(garmentScene, delta);
    });

    return (
        <primitive
            object={garmentScene}
        />
    );
}

export default function GarmentModel({
    config,
    selectedSize,
    selectedColor,
    fabricOverride,
    avatarScene = null,
    heatmapEnabled = false,
    heatmapZones,
    avatarProfile,
}: GarmentModelProps) {
    const garment = useMemo(() => resolveGarmentConfig(config, selectedSize), [config, selectedSize]);
    const normalizedHeatmapZones = useMemo<GarmentHeatmapZone[]>(() => {
        const normalized: GarmentHeatmapZone[] = [];

        (heatmapZones || []).forEach((zone) => {
            if (!zone?.key) {
                return;
            }

            normalized.push({
                key: zone.key,
                fit: zone.fit,
                delta: zone.delta,
                severity: zone.severity,
            });
        });

        return normalized;
    }, [heatmapZones]);

    if (!garment?.url) {
        return null;
    }

    return (
        <Suspense fallback={null}>
            <GarmentInstance
                key={garment.url}
                garment={garment}
                selectedColor={selectedColor}
                fabricOverride={fabricOverride}
                avatarScene={avatarScene}
                heatmapEnabled={Boolean(heatmapEnabled)}
                heatmapZones={normalizedHeatmapZones}
                avatarProfile={avatarProfile}
                config={config}
                selectedSize={selectedSize}
            />
        </Suspense>
    );
}

