        </Html>
    );
}

export type SizeCompare3DCanvasProps = {
    bodyData: Profile;
    modelConfig?: ProductWithModel['model3D'];
    selectedSize: string;
    selectedColor: string;
    selectedFabric?: LocalFabricProfile;
    heatmapEnabled: boolean;
    fitZones?: any[]; // RecommendationZone[]
    pose?: string;
    opacity?: number;
    hoverZone?: string | null;
    ghostSizes?: string[]; // If present, renders 2 wireframes instead of 1 mesh
    diffOnly?: boolean; // In outline mode, only show differences?
    cameraPreset?: string; // 'Front', 'Side', 'Back', '45°'
    outlineIntensity?: number;
};

function CameraPresetController({ preset }: { preset: string }) {
    useFrame(({ camera }) => {
        if (!preset || preset === 'Free') return;
        const radius = 5.2;
        const height = 0.8;
        const targetPos = new THREE.Vector3(0, height, radius);
        if (preset === 'Side') targetPos.set(radius, height, 0);
        else if (preset === 'Back') targetPos.set(0, height, -radius);
        else if (preset === '45°') targetPos.set(radius * 0.707, height, radius * 0.707);

        camera.position.lerp(targetPos, 0.05);
    });
    return null;
}

function CustomOutline({ target1, target2, color1, color2, edgeStrength1, edgeStrength2 }: { target1: THREE.Object3D | null, target2: THREE.Object3D | null, color1: string, color2: string, edgeStrength1: number, edgeStrength2: number }) {
    const { gl, scene, camera, size } = useThree();
    const composer = useRef<EffectComposer | null>(null);
    const pass1 = useRef<OutlinePass | null>(null);
    const pass2 = useRef<OutlinePass | null>(null);

    useEffect(() => {
        const comp = new EffectComposer(gl);
        const renderPass = new RenderPass(scene, camera);
        comp.addPass(renderPass);

        const outline1 = new OutlinePass(new THREE.Vector2(size.width, size.height), scene, camera);
        outline1.edgeThickness = 1.0;
        outline1.visibleEdgeColor.set(color1);
        outline1.hiddenEdgeColor.set(color1);
        comp.addPass(outline1);
        pass1.current = outline1;

        const outline2 = new OutlinePass(new THREE.Vector2(size.width, size.height), scene, camera);
        outline2.edgeThickness = 1.0;
        outline2.visibleEdgeColor.set(color2);
        outline2.hiddenEdgeColor.set(color2);
        comp.addPass(outline2);
        pass2.current = outline2;

        composer.current = comp;

        return () => {
            comp.dispose();
            outline1.dispose();
            outline2.dispose();
        };
    }, [gl, scene, camera, size, color1, color2]);

    useEffect(() => {
        if (pass1.current) {
            pass1.current.selectedObjects = target1 ? [target1] : [];
            pass1.current.edgeStrength = edgeStrength1;
        }
        if (pass2.current) {
            pass2.current.selectedObjects = target2 ? [target2] : [];
            pass2.current.edgeStrength = edgeStrength2;
        }
    }, [target1, target2, edgeStrength1, edgeStrength2]);

    useFrame(() => {
        if (composer.current) {
            composer.current.render();
        }
    }, 1);

    return null;
}

export default function SizeCompare3DCanvas({
    bodyData,
    modelConfig,
    selectedSize,
    selectedColor,
    selectedFabric,
    heatmapEnabled,
    fitZones,
    pose,
    opacity = 1,
    hoverZone = null,
    ghostSizes,
    diffOnly = false,
    cameraPreset = 'Front',
    outlineIntensity,
}: SizeCompare3DCanvasProps) {
    const [avatarScene, setAvatarScene] = useState<THREE.Group | null>(null);
    const ghost1Ref = useRef<THREE.Group>(null);
    const ghost2Ref = useRef<THREE.Group>(null);

    return (
        <div style={{ width: '100%', height: '100%', opacity, transition: 'opacity 0.3s' }}>
            <Canvas camera={{ position: [0, 0.8, 5.2], fov: 32 }} dpr={[1, 1.5]} shadows>
                <ambientLight intensity={0.42} />
                <directionalLight
                    position={[3, 6, 4]}
                    intensity={1.35}
                    castShadow
                    shadow-mapSize-width={1024}
                    shadow-mapSize-height={1024}
                    shadow-camera-near={0.5}
                    shadow-camera-far={20}
                    shadow-camera-left={-3}
                    shadow-camera-right={3}
                    shadow-camera-top={4}
                    shadow-camera-bottom={-2}
                    shadow-bias={-0.0005}
                />
                <directionalLight position={[-2, 3, -2]} intensity={0.3} />

                <Suspense fallback={<Loader />}>
                    <Environment preset="city" />
                    <group position={[0, -1.08, 0]}>


                        <Avatar 
                            body={bodyData} 
                            pose={pose || 'Idle'} 
                            skinColor="#F2C9AC" 
                            color={ghostSizes ? '#FDFBF7' : undefined}
                            opacity={ghostSizes ? 0.2 : 1}
                            onSceneReady={setAvatarScene} 
                        />
                        
                        {modelConfig && selectedSize && selectedColor && (
                            ghostSizes ? (
                                <>
                                    {ghostSizes[0] && (
                                        <group ref={ghost1Ref}>
                                            <GarmentModel
                                                config={modelConfig}
                                                selectedSize={ghostSizes[0]}
                                                selectedColor={selectedColor}
                                                fabricOverride={selectedFabric}
                                                avatarScene={avatarScene}
                                                heatmapEnabled={false}
                                                heatmapZones={[]}
                                                ghostOpacity={diffOnly ? 0.0 : (outlineIntensity !== undefined ? outlineIntensity * 0.4 + 0.1 : 0.3)}
                                                emissiveIntensity={0}
                                                avatarProfile={bodyData}
                                            />
                                        </group>
                                    )}
                                    {ghostSizes[1] && (
                                        <group ref={ghost2Ref}>
                                            <GarmentModel
                                                config={modelConfig}
                                                selectedSize={ghostSizes[1]}
                                                selectedColor={selectedColor}
                                                fabricOverride={selectedFabric}
                                                avatarScene={avatarScene}
                                                heatmapEnabled={false}
                                                heatmapZones={[]}
                                                ghostOpacity={diffOnly ? 0.0 : (outlineIntensity !== undefined ? outlineIntensity * 0.4 + 0.1 : 0.3)}
                                                emissiveIntensity={0}
                                                avatarProfile={bodyData}
                                            />
                                        </group>
                                    )}
                                </>
                            ) : (
                                <GarmentModel
                                    config={modelConfig}
                                    selectedSize={selectedSize}
                                    selectedColor={selectedColor}
                                    fabricOverride={selectedFabric}
                                    avatarScene={avatarScene}
                                    heatmapEnabled={heatmapEnabled || !!hoverZone}
                                    heatmapZones={hoverZone ? fitZones?.filter((z: any) => z.key === hoverZone) : fitZones}
                                    avatarProfile={bodyData}
                                />
                            )
                        )}
                        <ContactShadows position={[0, 0.01, 0]} opacity={0.6} scale={5} blur={2.5} resolution={1024} frames={1} />
                    </group>

                    {ghostSizes && (
                        <CustomOutline 
                            target1={ghost1Ref.current} 
                            target2={ghost2Ref.current} 
                            color1="#D5C9B3" 
                            color2="#C8A867" 
                            edgeStrength1={diffOnly ? 0 : 2}
                            edgeStrength2={diffOnly ? 4 : 3}
                        />
                    )}
                </Suspense>

                <CameraPresetController preset={cameraPreset} />
                <OrbitControls
                    target={[0, 0.3, 0]}
                    enablePan={false}
                    enableDamping
                    dampingFactor={0.08}
                    minDistance={1.5}
                    maxDistance={6.0}
                />
            </Canvas>
        </div>
    );
}

import { useMemo, useState, useEffect } from 'react';
import type { Profile } from '../../../contexts/FittingRoomContext';
import { detectBodyShape } from './BodyPresets';

/* ══════════════════════════════════════════════════════════════
   Size Recommendation Engine
   Uses ease (garment - body) as the primary fit signal.
   ══════════════════════════════════════════════════════════════ */

export type MeasurementZone = 'chest' | 'waist' | 'hips' | 'shoulder' | 'thigh' | 'legOpening';
export type FitLevel = 'tight' | 'fitted' | 'comfortable' | 'loose';
export type GarmentType = 'top' | 'bottom' | 'dress' | 'outerwear' | 'unknown';

interface SizeSpec {
    chest: [number, number];
    waist: [number, number];
    hips: [number, number];
    shoulder: [number, number];
    height: [number, number];
    weight: [number, number];
}

export interface GarmentSizeSpec {
    chest?: number;
    waist?: number;
    hips?: number;
    shoulder?: number;
    thigh?: number;
    legOpening?: number;
    sleeveLength?: number;
    garmentLength?: number;
    stretchWarp?: number;
    stretchWeft?: number;
    fitIntent?: string;
}

export interface RecommendSizeOptions {
    garmentType?: string;
}

export interface FitZone {
    key: MeasurementZone;
    label: string;
    fit: FitLevel;
    delta: number;      // rounded ease in cm (garment - body)
    deltaRaw: number;   // precise ease in cm
    severity: number;   // 0..1 (higher = worse mismatch)
}

export interface SizeResult {
    size: string;
    score: number;      // 0..100, higher = better
    zones: FitZone[];
    isRecommended: boolean;
}

const SIZE_CHART: Record<string, SizeSpec> = {
    XS: {
        chest: [74, 80], waist: [56, 62], hips: [80, 86],
        shoulder: [34, 36], height: [150, 158], weight: [38, 46],
    },
    S: {
        chest: [80, 86], waist: [62, 68], hips: [86, 92],
        shoulder: [36, 38], height: [155, 163], weight: [44, 52],
    },
    M: {
        chest: [86, 92], waist: [68, 74], hips: [92, 98],
        shoulder: [38, 40], height: [160, 168], weight: [50, 60],
    },
    L: {
        chest: [92, 98], waist: [74, 82], hips: [98, 104],
        shoulder: [40, 43], height: [165, 175], weight: [58, 68],
    },
    XL: {
        chest: [98, 106], waist: [82, 90], hips: [104, 112],
        shoulder: [43, 46], height: [170, 182], weight: [66, 80],
    },
    XXL: {
        chest: [106, 114], waist: [90, 100], hips: [112, 120],
        shoulder: [46, 50], height: [175, 190], weight: [78, 95],
    },
};

const SIZE_ORDER = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];

const ZONE_LABELS: Record<MeasurementZone, string> = {
    chest: 'Ngực',
    waist: 'Eo',
    hips: 'Hông',
    shoulder: 'Vai',
    thigh: 'Đùi',
    legOpening: 'Ống quần',
};

const ZONE_WEIGHTS: Record<MeasurementZone, number> = {
    chest: 3,
    waist: 2,
    hips: 2.8,
    shoulder: 1.8,
    thigh: 2.4,
    legOpening: 1.3,
};

const IDEAL_EASE_CM: Record<MeasurementZone, number> = {
    chest: 8,
    waist: 8,
    hips: 8,
    shoulder: 3,
    thigh: 5,
    legOpening: 4,
};

const EASE_TOLERANCE_CM: Record<MeasurementZone, number> = {
    chest: 6,
    waist: 7,
    hips: 6,
    shoulder: 2.5,
    thigh: 5,
    legOpening: 4,
};

const ALL_ZONES: MeasurementZone[] = ['chest', 'waist', 'hips', 'shoulder', 'thigh', 'legOpening'];

const GARMENT_ZONE_PROFILES: Record<GarmentType, MeasurementZone[]> = {
    top: ['chest', 'waist', 'hips', 'shoulder'],
    bottom: ['waist', 'hips', 'thigh', 'legOpening'],
    dress: ['chest', 'waist', 'hips', 'shoulder'],
    outerwear: ['chest', 'waist', 'hips', 'shoulder'],
    unknown: ['chest', 'waist', 'hips', 'shoulder'],
};

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const round2 = (value: number) => Math.round(value * 100) / 100;
const normalizeSize = (value: string) => value.trim().toUpperCase();

const normalizeGarmentType = (value?: string): GarmentType => {
    if (!value) {
        return 'unknown';
    }

    const normalized = value.trim().toLowerCase();
    if (normalized === 'top' || normalized === 'bottom' || normalized === 'dress' || normalized === 'outerwear') {
        return normalized;
    }

    return 'unknown';
};

const getBodyMeasurement = (profile: Profile, zone: MeasurementZone) => {
    if (zone === 'chest') return profile.chest;
    if (zone === 'waist') return profile.waist;
    if (zone === 'hips') return profile.hips;
    if (zone === 'shoulder') return profile.shoulder;

    // Derived lower-body estimates used when avatar profile has no direct thigh/calf measures.
    if (zone === 'thigh') {
        return round2(profile.hips * 0.61);
    }

    return round2(profile.hips * 0.56);
};

const getGarmentMeasurement = (spec: GarmentSizeSpec, zone: MeasurementZone): number | null => {
    const value = spec[zone];
    return typeof value === 'number' && Number.isFinite(value) ? value : null;
};

const resolveActiveZones = (garmentType: GarmentType, garmentSpec?: GarmentSizeSpec): MeasurementZone[] => {
    const preferred = GARMENT_ZONE_PROFILES[garmentType] || ALL_ZONES;
    if (!garmentSpec) {
        return preferred;
    }

    const availableInPreferred = preferred.filter((zone) => getGarmentMeasurement(garmentSpec, zone) !== null);
    if (availableInPreferred.length > 0) {
        return availableInPreferred;
    }

    const availableInAll = ALL_ZONES.filter((zone) => getGarmentMeasurement(garmentSpec, zone) !== null);
    return availableInAll.length > 0 ? availableInAll : preferred;
};

const classifyEase = (easeCm: number): FitLevel => {
    if (easeCm < 2) {
        return 'tight';
    }

    if (easeCm <= 6) {
        return 'fitted';
    }

    if (easeCm <= 12) {
        return 'comfortable';
    }

    return 'loose';
};

const computeEaseSeverity = (zone: MeasurementZone, easeCm: number, fit: FitLevel) => {
    const ideal = IDEAL_EASE_CM[zone];
    const tolerance = EASE_TOLERANCE_CM[zone];

    if (fit === 'tight') {
        return round2(clamp(0.7 + (2 - easeCm) / 4, 0.7, 1));
    }

    if (fit === 'loose') {
        return round2(clamp(0.45 + (easeCm - 12) / 18, 0.45, 1));
    }

    const normalized = Math.abs(easeCm - ideal) / tolerance;
    if (fit === 'fitted') {
        return round2(clamp(0.18 + normalized * 0.35, 0.14, 0.62));
    }

    return round2(clamp(0.08 + normalized * 0.3, 0.08, 0.55));
};

const buildFitZone = (zone: MeasurementZone, easeCm: number): FitZone => {
    const fit = classifyEase(easeCm);
    const severity = computeEaseSeverity(zone, easeCm, fit);

    return {
        key: zone,
        label: ZONE_LABELS[zone],
        fit,
        delta: Math.round(easeCm),
        deltaRaw: round2(easeCm),
        severity,
    };
};

const scoreFromZones = (zones: FitZone[]) => {
    let weightedTotal = 0;
    let weightSum = 0;

    zones.forEach((zone) => {
        const weight = ZONE_WEIGHTS[zone.key];
        const zoneScore = Math.max(0, 100 - zone.severity * 88);
        weightedTotal += zoneScore * weight;
        weightSum += weight;
    });

    return weightSum > 0 ? Math.round(weightedTotal / weightSum) : 0;
};

const scoreGarmentSizeByEase = (
    profile: Profile,
    garmentSpec: GarmentSizeSpec,
    activeZones: MeasurementZone[],
): { score: number; zones: FitZone[] } => {
    const zones: FitZone[] = activeZones.flatMap((zone) => {
        const body = getBodyMeasurement(profile, zone);
        const garment = getGarmentMeasurement(garmentSpec, zone);
        if (garment === null) {
            return [];
        }
        const easeCm = garment - body;
        return [buildFitZone(zone, easeCm)];
    });

    return {
        score: scoreFromZones(zones),
        zones,
    };
};

// Fallback when product-specific garment measurements are unavailable.
const estimateEaseFromRange = (bodyValue: number, range: [number, number]) => {
    const [min, max] = range;

    if (bodyValue > max) {
        return 2 - (bodyValue - max);
    }

    if (bodyValue < min) {
        const gap = min - bodyValue;
        if (gap <= 4) {
            return 6 + gap * 1.2;
        }
        return 12 + (gap - 4) * 1.1;
    }

    const t = (bodyValue - min) / Math.max(max - min, 1);
    return 8 - t * 4.5;
};

const scoreFallbackRangeSize = (
    profile: Profile,
    spec: SizeSpec,
    activeZones: MeasurementZone[],
): { score: number; zones: FitZone[] } => {
    const deriveLowerRangeFromHips = (
        hipsRange: [number, number],
        kind: 'thigh' | 'legOpening',
    ): [number, number] => {
        if (kind === 'thigh') {
            return [round2(hipsRange[0] * 0.58), round2(hipsRange[1] * 0.66)];
        }

        return [round2(hipsRange[0] * 0.5), round2(hipsRange[1] * 0.58)];
    };

    const rangeByZone: Record<MeasurementZone, [number, number]> = {
        chest: spec.chest,
        waist: spec.waist,
        hips: spec.hips,
        shoulder: spec.shoulder,
        thigh: deriveLowerRangeFromHips(spec.hips, 'thigh'),
        legOpening: deriveLowerRangeFromHips(spec.hips, 'legOpening'),
    };

    const zones: FitZone[] = activeZones.map((zone) => {
        const body = getBodyMeasurement(profile, zone);
        const estimatedEase = estimateEaseFromRange(body, rangeByZone[zone]);
        const zoneFit = buildFitZone(zone, estimatedEase);

        // Fallback path is less precise than true garment measurements.
        return {
            ...zoneFit,
            severity: round2(clamp(zoneFit.severity + 0.08, 0, 1)),
        };
    });

    return {
        score: scoreFromZones(zones),
        zones,
    };
};

export function recommendSizes(
    profile: Profile,
    availableSizes: string[],
    garmentSizeSpecs?: Record<string, GarmentSizeSpec>,
    options: RecommendSizeOptions = {},
): SizeResult[] {
    const results: SizeResult[] = [];
    const garmentType = normalizeGarmentType(options.garmentType);

    const normalizedAvailableSizes = [...new Set(availableSizes.map(normalizeSize).filter(Boolean))];
    const orderedAvailableSizes = [
        ...SIZE_ORDER.filter((size) => normalizedAvailableSizes.includes(size)),
        ...normalizedAvailableSizes.filter((size) => !SIZE_ORDER.includes(size)),
    ];

    const normalizedGarmentSpecs = garmentSizeSpecs
        ? Object.entries(garmentSizeSpecs).reduce<Record<string, GarmentSizeSpec>>((acc, [size, spec]) => {
            const key = normalizeSize(size);
            if (!key || !spec) {
                return acc;
            }
            acc[key] = spec;
            return acc;
        }, {})
        : undefined;

    orderedAvailableSizes.forEach((size) => {
        const garmentSpec = normalizedGarmentSpecs?.[size];
        const activeZones = resolveActiveZones(garmentType, garmentSpec);
        const result = garmentSpec
            ? scoreGarmentSizeByEase(profile, garmentSpec, activeZones)
            : (SIZE_CHART[size] ? scoreFallbackRangeSize(profile, SIZE_CHART[size], activeZones) : null);

        if (!result) {
            return;
        }

        results.push({
            size,
            score: result.score,
            zones: result.zones,
            isRecommended: false,
        });
    });

    results.sort((a, b) => b.score - a.score);

    if (results.length > 0) {
        results[0].isRecommended = true;
    }

    return results;
}

/* ─────────────────────────────────────────────────────────────
   UI Component
   ───────────────────────────────────────────────────────────── */

const FIT_LABELS: Record<FitLevel, { text: string; color: string }> = {
    tight: { text: 'Chật', color: '#ef4444' },
    fitted: { text: 'Ôm vừa', color: '#eab308' },
    comfortable: { text: 'Thoải mái', color: '#22c55e' },
    loose: { text: 'Rộng', color: '#166534' },
};

interface SizeRecommendationProps {
    profile: Profile;
    availableSizes: string[];
    selectedSize: string | null;
    onSelectSize: (size: string) => void;
    garmentSizeSpecs?: Record<string, GarmentSizeSpec>;
    garmentType?: string;
}

export default function SizeRecommendation({
    profile, availableSizes, selectedSize, onSelectSize, garmentSizeSpecs, garmentType,
}: SizeRecommendationProps) {
    const [isDetailOpen, setIsDetailOpen] = useState(false);

    const results = useMemo(
        () => recommendSizes(profile, availableSizes, garmentSizeSpecs, { garmentType }),
        [profile, availableSizes, garmentSizeSpecs, garmentType],
    );

    const shape = useMemo(() => detectBodyShape(profile), [profile]);

    const bestResult = results.find((result) => result.isRecommended);
    const selectedResult = results.find((result) => result.size === selectedSize);
    const displayResult = selectedResult || bestResult;

    useEffect(() => {
        setIsDetailOpen(false);
    }, [selectedSize, profile]);

    return (
        <div className="vto-size-rec">
            {bestResult && (
                <div className="vto-size-rec__badge">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                        <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                        <polyline points="22 4 12 14.01 9 11.01" />
                    </svg>
                    <span>
                        Gợi ý: <strong>{bestResult.size}</strong> - phù hợp {bestResult.score}% · Dáng {shape.label}
                    </span>
                </div>
            )}

            <div className="vto-size-rec__grid">
                {results.map((result) => (
                    <button
                        key={result.size}
                        className={`vto-size-rec__btn ${selectedSize === result.size ? 'active' : ''} ${result.isRecommended ? 'recommended' : ''}`}
                        onClick={() => onSelectSize(result.size)}
                    >
                        <span className="vto-size-rec__btn-label">{result.size}</span>
                        <span className="vto-size-rec__btn-score">{result.score}%</span>
                        {result.isRecommended && <span className="vto-size-rec__star">★</span>}
                    </button>
                ))}
            </div>

            {displayResult && (
                <div className="vto-size-rec__detail-wrap">
                    <button
                        type="button"
                        className={`vto-size-rec__toggle ${isDetailOpen ? 'open' : ''}`}
                        onClick={() => setIsDetailOpen((open) => !open)}
                    >
                        <span className="vto-size-rec__toggle-text">
                            {isDetailOpen ? 'Ẩn chi tiết' : `Xem chi tiết size ${displayResult.size}`}
                        </span>
                        <svg className="vto-size-rec__toggle-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                            <polyline points="6 9 12 15 18 9" />
                        </svg>
                    </button>

                    {isDetailOpen && (
                        <div className="vto-size-rec__detail">
                            <p className="vto-size-rec__detail-title">Chi tiết size {displayResult.size}</p>
                            <div className="vto-size-rec__zones">
                                {displayResult.zones.map((zone) => {
                                    const fitInfo = FIT_LABELS[zone.fit];
                                    return (
                                        <div key={zone.key} className="vto-size-rec__zone">
                                            <span className="vto-size-rec__zone-label">{zone.label}</span>
                                            <span className="vto-size-rec__zone-fit" style={{ color: fitInfo.color }}>
                                                {fitInfo.text}
                                            </span>
                                            <span className="vto-size-rec__zone-delta">
                                                {zone.deltaRaw > 0 ? '+' : ''}{zone.deltaRaw} cm
                                            </span>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

import { useState } from 'react';
import './ClosetItemCard.css';

export interface ClosetItemData {
    itemId?: string;
    productId?: string;
    name: string;
    thumbnailUrl?: string;
    imageUrl?: string;
    img?: string;
    purchasedColor?: string;
    purchasedSize?: string;
    availableColors?: { name: string; value: string; hex?: string }[];
    availableSizes?: string[];
    wornCount?: number;
    slotCategory?: string;
    purchasedAt?: string;
}

interface Props {
    item: any;
    matchScore?: number;
    onWear: (item: any, color: string, size: string) => void;
    onViewDetails?: (item: any) => void;
}

export default function VirtualClosetItem({ item, matchScore, onWear, onViewDetails }: Props) {
    const [open, setOpen] = useState(false);
    const [wearing, setWearing] = useState(false);
    const [color, setColor] = useState(item.purchasedColor ?? '');
    const [size, setSize] = useState(item.purchasedSize ?? '');

    const imgSrc = item.thumbnailUrl || item.imageUrl || item.img || '';
    const hasColors = (item.availableColors?.length ?? 0) > 0;
    const hasSizes = (item.availableSizes?.length ?? 0) > 0;
    const hasPicker = hasColors || hasSizes;

    const purchasedColorObj = item.availableColors?.find(
        (c: any) =>
            c.value === item.purchasedColor ||
            c.name === item.purchasedColor ||
            c.hex === item.purchasedColor,
    );

    const displayColorHex = purchasedColorObj?.hex ?? purchasedColorObj?.value ?? item.purchasedColor ?? null;
    const displayColorName = purchasedColorObj?.name ?? item.purchasedColor ?? null;
    const displaySize = item.purchasedSize ?? null;

    const sp = (e: React.MouseEvent) => { e.preventDefault(); e.stopPropagation(); };

    const handleWearBtn = (e: React.MouseEvent) => {
        sp(e);
        // Immediately wear the purchased item with its specific size and color instead of opening picker
        doWear(e);
    };

    const doWear = (e: React.MouseEvent) => {
        sp(e);
        
        // Fallback for older items that were saved without purchasedSize/purchasedColor
        const defaultColor = color || item.purchasedColor || item.availableColors?.[0]?.value || item.availableColors?.[0]?.name || '#222222';
        const defaultSize = size || item.purchasedSize || item.availableSizes?.[0] || 'M';

        onWear(item, defaultColor, defaultSize);
        setOpen(false);
        setWearing(true);
        setTimeout(() => setWearing(false), 2500);
    };

    const handleCancel = (e: React.MouseEvent) => {
        sp(e);
        setOpen(false);
        setColor(item.purchasedColor ?? '');
        setSize(item.purchasedSize ?? '');
    };

    return (
        <article
            className={[
                'cic',
                open ? 'cic--open' : '',
                wearing ? 'cic--wearing' : '',
            ].filter(Boolean).join(' ')}
            data-testid="closet-item"
        >
            {/* ─── IMAGE ZONE ─── */}
            <div
                className="cic__img-wrap"
                onClick={e => { sp(e); if (hasPicker) setOpen(v => !v); }}
                role="button"
                tabIndex={0}
                aria-label={`Xem tùy chọn cho ${item.name}`}
            >
                {imgSrc ? (
                    <img className="cic__img" src={imgSrc} alt={item.name} loading="lazy" />
                ) : (
                    <div className="cic__img-ph">
                        <span>👕</span>
                    </div>
                )}

                {/* overlay top row */}
                <div className="cic__overlay-top">
                    {/* "Đã Mua" badge */}
                    <span className="cic__badge-bought">✓ Đã mua</span>

                    {/* Worn count */}
                    {(item.wornCount ?? 0) > 0 && (
                        <span className="cic__badge-worn">{item.wornCount}× đã thử</span>
                    )}
                </div>

                {/* match score bottom left */}
                {typeof matchScore === 'number' && matchScore >= 50 && (
                    <span className="cic__badge-match">{matchScore}% phù hợp</span>
                )}

                {/* wearing overlay */}
                {wearing && (
                    <div className="cic__wearing-overlay">
                        <span>✦ Đang mặc</span>
                    </div>
                )}

                {/* expand hint */}
                {hasPicker && !wearing && (
                    <span className="cic__hint">{open ? '▲ Thu' : '▼ Chọn size'}</span>
                )}
            </div>

            {/* ─── INFO ZONE ─── */}
            <div className="cic__info">
                <p className="cic__name" title={item.name}>{item.name}</p>

                {/* size + color row — always visible */}
                <div className="cic__attrs">
                    {displaySize ? (
                        <span className="cic__attr cic__attr--size">
                            <span className="cic__attr-label">SIZE</span>
                            <span className="cic__attr-val">{displaySize}</span>
                        </span>
                    ) : (
                        <span className="cic__attr cic__attr--size cic__attr--empty">
                            <span className="cic__attr-label">SIZE</span>
                            <span className="cic__attr-val">—</span>
                        </span>
                    )}

                    {displayColorHex || displayColorName ? (
                        <span className="cic__attr cic__attr--color">
                            {displayColorHex && (
                                <span
                                    className="cic__color-swatch"
                                    style={{ background: displayColorHex }}
                                    title={displayColorName ?? ''}
                                />
                            )}
                            <span className="cic__attr-val">{displayColorName ?? displayColorHex}</span>
                        </span>
                    ) : (
                        <span className="cic__attr cic__attr--color cic__attr--empty">
                            <span className="cic__attr-val">—</span>
                        </span>
                    )}
                </div>
            </div>

            {/* ─── PICKER ZONE (expands when open) ─── */}
            {open && (
                <div className="cic__picker">
                    {hasColors && (
                        <div className="cic__picker-row">
                            <span className="cic__picker-label">Màu</span>
                            <div className="cic__color-list">
                                {item.availableColors!.map((c: any) => {
                                    const isPurchased =
                                        c.value === item.purchasedColor ||
                                        c.name === item.purchasedColor;
                                    const isSelected = color === c.value || color === c.name;
                                    return (
                                        <button
                                            key={c.value}
                                            className={[
                                                'cic__cdot',
                                                isSelected ? 'cic__cdot--on' : '',
                                                isPurchased ? 'cic__cdot--bought' : '',
                                            ].filter(Boolean).join(' ')}
                                            style={{ background: c.hex ?? c.value }}
                                            title={`${c.name}${isPurchased ? ' ★ đã mua' : ''}`}
                                            onClick={e => { sp(e); setColor(c.value); }}
                                            data-testid="color-dot"
                                        >
                                            {isPurchased && <span className="cic__cdot-check">✓</span>}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {hasSizes && (
                        <div className="cic__picker-row">
                            <span className="cic__picker-label">Size</span>
                            <div className="cic__size-list">
                                {item.availableSizes!.map((s: any) => {
                                    const isPurchased = s === item.purchasedSize;
                                    const isSelected = size === s;
                                    return (
                                        <button
                                            key={s}
                                            className={[
                                                'cic__sbtn',
                                                isSelected ? 'cic__sbtn--on' : '',
                                                isPurchased ? 'cic__sbtn--bought' : '',
                                            ].filter(Boolean).join(' ')}
                                            onClick={e => { sp(e); setSize(s); }}
                                            data-testid="size-btn"
                                            title={isPurchased ? `${s} — size đã mua` : s}
                                        >
                                            {s}
                                            {isPurchased && <span className="cic__sbtn-star">★</span>}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* ─── ACTION ZONE ─── */}
            <div className="cic__actions">
                {wearing ? (
                    <>
                        <div className="cic__btn cic__btn--worn">✓ Đang mặc</div>
                        <button
                            className="cic__btn cic__btn--detail"
                            onClick={e => { sp(e); onViewDetails?.(item); }}
                        >
                            Chi tiết
                        </button>
                    </>
                ) : open ? (
                    <>
                        <button className="cic__btn cic__btn--confirm" onClick={doWear} data-testid="confirm-wear-btn">
                            Mặc lên →
                        </button>
                        <button className="cic__btn cic__btn--cancel" onClick={handleCancel}>Huỷ</button>
                    </>
                ) : (
                    <>
                        <button className="cic__btn cic__btn--wear" onClick={handleWearBtn} data-testid="wear-btn">
                            👗 Wear
                        </button>
                        <button
                            className="cic__btn cic__btn--detail"
                            onClick={e => { sp(e); onViewDetails?.(item); }}
                            data-testid="detail-btn"
                        >
                            Chi tiết
                        </button>
                    </>
                )}
            </div>
        </article>
    );
}

import { useEffect, useMemo, useState } from 'react';
import './VirtualPersonalClosetDrawer.css';
import VirtualClosetItem from './VirtualClosetItem';
import { MODEL_INJECTION } from '../../../data/ThreeDConfig';

type ClosetSlotCategory = 'tops' | 'bottoms' | 'outerwear' | 'dresses';

type ClosetColorOption = {
    name: string;
    value: string;
    hex?: string;
};

export type ClosetItem = {
    id: string;
    itemId?: string;
    productId?: string | number;
    orderId?: string;
    name: string;
    category: string;
    categoryKey: string;
    slotCategory: ClosetSlotCategory;
    thumbnail: string;
    imageUrl?: string;
    thumbnailUrl?: string;
    purchasedSize?: string;
    purchasedColor?: string;
    availableColors?: ClosetColorOption[];
    availableSizes?: string[];
    model3D?: Record<string, unknown>;
    wornCount?: number;
    lastWornAt?: string;
    purchasedAt?: string;
    isOwned: boolean;
    source: 'order' | 'fallback' | 'import';
};

type ClosetTab = {
    key: string;
    label: string;
    items: ClosetItem[];
};

type SavedOutfitSlot = {
    itemId?: string;
    name?: string;
    thumbnailUrl?: string;
};

type SavedOutfit = {
    _id: string;
    name?: string;
    slots?: {
        tops?: SavedOutfitSlot;
        bottoms?: SavedOutfitSlot;
        outerwear?: SavedOutfitSlot;
        dresses?: SavedOutfitSlot;
    };
    createdAt?: string;
};

type SortMode = 'all' | 'match' | 'newest';

type ProductLike = {
    id?: number | string;
    name?: string;
    category?: string;
};

type ClosetApiItem = {
    itemId?: string;
    orderId?: string;
    productId?: string | number;
    name?: string;
    category?: string;
    img?: string;
    image?: string;
    imageUrl?: string;
    thumbnailUrl?: string;
    purchasedSize?: string;
    purchasedColor?: string;
    availableColors?: ClosetColorOption[];
    availableSizes?: string[];
    model3D?: Record<string, unknown>;
    size?: string;
    color?: string;
    isActive?: boolean;
    wearCount?: number;
    wornCount?: number;
    lastWorn?: string;
    lastWornAt?: string;
    dateAdded?: string;
    purchasedAt?: string;
    source?: 'order' | 'fallback' | 'import';
};

type ClosetApiResponse = {
    items?: ClosetApiItem[];
};

type ProductCatalogItem = {
    id?: number | string;
    productId?: number | string;
    model3D?: {
        colors?: Array<{ name?: string; hex?: string; value?: string }>;
        sizes?: Record<string, unknown>;
    };
};

const API_URL = import.meta.env.VITE_API_URL || '';

const ABSOLUTE_URL_PATTERN = /^(data:|blob:|https?:\/\/)/i;

function createPlaceholderThumb(title: string): string {
    const safeTitle = title.replace(/[&<>]/g, (char) => {
        if (char === '&') return '&amp;';
        if (char === '<') return '&lt;';
        if (char === '>') return '&gt;';
        return char;
    });

    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='520' height='640' viewBox='0 0 520 640'><defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'><stop offset='0%' stop-color='#f7f1e8'/><stop offset='100%' stop-color='#efe5d7'/></linearGradient></defs><rect width='520' height='640' fill='url(#g)'/><rect x='18' y='18' width='484' height='604' rx='24' fill='none' stroke='#d9c9b5' stroke-width='3'/><text x='50%' y='48%' text-anchor='middle' fill='#6b5a45' font-size='30' font-family='Georgia, serif'>SmartFit Closet</text><text x='50%' y='56%' text-anchor='middle' fill='#8c765c' font-size='20' font-family='Georgia, serif'>${safeTitle}</text></svg>`;
    return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

function inferCategory(input?: string): ClosetSlotCategory {
    const text = String(input || '').trim().toLowerCase();

    if (
        text.includes('dress')
        || text.includes('đầm')
        || text.includes('váy liền')
    ) {
        return 'dresses';
    }

    if (
        text.includes('coat')
        || text.includes('jacket')
        || text.includes('blazer')
        || text.includes('hoodie')
        || text.includes('áo khoác')
    ) {
        return 'outerwear';
    }

    if (
        text.includes('pant')
        || text.includes('jean')
        || text.includes('skirt')
        || text.includes('short')
        || text.includes('quần')
        || text.includes('chân váy')
    ) {
        return 'bottoms';
    }

    return 'tops';
}

function formatCategoryLabel(input?: string): string {
    const value = String(input || '').trim();
    if (!value) {
        return 'Khác';
    }

    return value.replace(/\s+/g, ' ');
}

function normalizeCategoryKey(input?: string): string {
    return formatCategoryLabel(input).toLowerCase();
}

function scoreStylistMatch(item: ClosetItem, viewedProduct?: ProductLike): number {
    if (!viewedProduct) {
        return 0;
    }

    const viewedCategory = inferCategory(viewedProduct.category || viewedProduct.name);
    const viewedName = String(viewedProduct.name || '').toLowerCase();
    const closetName = item.name.toLowerCase();

    let score = 0.36;

    if (viewedCategory !== item.slotCategory) {
        score += 0.22;
    }

    const sharedWords = ['linen', 'denim', 'silk', 'wool', 'basic', 'classic', 'formal', 'casual', 'black', 'white', 'beige'];
    sharedWords.forEach((word) => {
        if (viewedName.includes(word) && closetName.includes(word)) {
            score += 0.04;
        }
    });

    return Math.min(0.95, Number(score.toFixed(2)));
}

function resolveAssetUrl(raw?: string): string {
    const value = String(raw || '').trim();
    if (!value) {
        return '';
    }

    if (ABSOLUTE_URL_PATTERN.test(value)) {
        return value;
    }

    if (value.startsWith('//')) {
        return `https:${value}`;
    }

    const normalized = value.replace(/\\/g, '/').replace(/^\.\//, '');
    const withoutPublicPrefix = normalized.startsWith('public/') ? normalized.slice('public/'.length) : normalized;
    const browserOrigin = typeof window !== 'undefined' ? window.location.origin : API_URL;
    const apiBase = API_URL.replace(/\/$/, '');

    if (withoutPublicPrefix.startsWith('/')) {
        return `${browserOrigin}${withoutPublicPrefix}`;
    }

    if (
        withoutPublicPrefix.startsWith('assets/')
        || withoutPublicPrefix.startsWith('models/')
        || withoutPublicPrefix.startsWith('uploads/')
    ) {
        return `${browserOrigin}/${withoutPublicPrefix}`;
    }

    // Skip unresolved source paths that are not publicly served in production.
    if (withoutPublicPrefix.startsWith('src/')) {
        return '';
    }

    return `${apiBase}/${withoutPublicPrefix}`;
}

function mapProductColors(model3D?: ProductCatalogItem['model3D']): ClosetColorOption[] {
    const colors = model3D?.colors;
    if (!Array.isArray(colors) || colors.length === 0) {
        return [];
    }

    const normalizedColors: ClosetColorOption[] = [];

    colors.forEach((color) => {
        const name = String(color?.name || color?.value || color?.hex || '').trim();
        const value = String(color?.hex || color?.value || color?.name || '').trim();
        if (!name || !value) {
            return;
        }

        normalizedColors.push({
            name,
            value,
            hex: String(color?.hex || '').trim() || undefined,
        });
    });

    return normalizedColors;
}

function mapProductSizes(model3D?: ProductCatalogItem['model3D']): string[] {
    const sizes = model3D?.sizes;
    return sizes ? Object.keys(sizes).map((size) => String(size).trim()).filter(Boolean) : [];
}

function mapApiClosetItems(rawItems: ClosetApiItem[], products: ProductCatalogItem[] = []): ClosetItem[] {
    const dedupe = new Map<string, ClosetItem>();
    const productLookup = new Map<string, ProductCatalogItem>();

    products.forEach((product) => {
        const keys = [product.id, product.productId].filter((value) => value !== undefined && value !== null);
        keys.forEach((value) => {
            productLookup.set(String(value), product);
        });
    });

    rawItems.forEach((item, index) => {
        if (item.isActive === false) {
            return;
        }

        const name = String(item.name || '').trim() || `Purchased Item ${index + 1}`;
        const seed = String(item.itemId || item.productId || `${index}`);
        const id = `closet-${seed}`;
        const product = productLookup.get(String(item.productId || item.itemId || ''));
        const productModel3D = product?.model3D;

        if (dedupe.has(id)) {
            return;
        }

        const sourceModelId = String(item.productId || '').trim();
        // @ts-ignore - indexing MODEL_INJECTION with string
        const fullConfig = MODEL_INJECTION[sourceModelId] || productModel3D;
        
        let finalModel3D = fullConfig || undefined;
        if (fullConfig && item.glbUrl) {
            const sizeKey = String(item.size || item.purchasedSize || 'M').trim().toUpperCase();
            finalModel3D = {
                ...fullConfig,
                sizes: {
                    ...fullConfig.sizes,
                    [sizeKey]: {
                        ...(fullConfig.sizes?.[sizeKey] || {}),
                        url: item.glbUrl,
                        autoNormalize: fullConfig.sizes?.[sizeKey]?.autoNormalize ?? fullConfig.autoNormalize ?? false
                    }
                }
            };
        } else if (item.glbUrl) {
            finalModel3D = {
                enable: true,
                autoNormalize: false,
                sizes: {
                    [String(item.size || item.purchasedSize || 'M').trim().toUpperCase()]: { url: item.glbUrl, autoNormalize: false }
                }
            };
        }

        const availableColors = mapProductColors(productModel3D);
        const availableSizes = mapProductSizes(productModel3D);
        
        const fallbackSize = availableSizes.length > 0 ? availableSizes[0] : 'M';
        const fallbackColor = availableColors.length > 0 ? availableColors[0].hex : '';

        dedupe.set(id, {
            id,
            itemId: item.itemId || item._id,
            productId: Number(item.productId),
            orderId: item.orderId,
            name: String(item.name || '').trim() || name,
            img: resolveAssetUrl(
                String(item.thumbnailUrl || item.imageUrl || item.img || item.image || '').trim(),
            ) || createPlaceholderThumb(name),
            imageUrl: resolveAssetUrl(String(item.imageUrl || item.img || item.image || '').trim()) || undefined,
            thumbnailUrl: resolveAssetUrl(String(item.thumbnailUrl || item.imageUrl || item.img || '').trim()) || undefined,
            category: formatCategoryLabel(item.category || name),
            categoryKey: normalizeCategoryKey(item.category || name),
            slotCategory: inferCategory(item.category || name),
            purchasedSize: String(item.size || item.purchasedSize || '').trim() || fallbackSize,
            purchasedColor: String(item.color || item.purchasedColor || '').trim() || fallbackColor,
            availableColors,
            availableSizes,
            model3D: finalModel3D,
            wornCount: Number(item.wornCount ?? item.wearCount ?? 0),
            lastWornAt: String(item.lastWornAt || item.lastWorn || '').trim() || undefined,
            purchasedAt: String(item.purchasedAt || item.dateAdded || '').trim() || undefined,
            isOwned: true,
            source: item.source || 'order',
        });
    });

    return Array.from(dedupe.values());
}

type VirtualPersonalClosetDrawerProps = {
    viewedProduct?: ProductLike;
    onWearItem?: (item: ClosetItem, selectedColor?: string, selectedSize?: string) => void;
    onViewDetails?: (item: ClosetItem) => void;
    onApplySavedOutfit?: (outfit: SavedOutfit) => void;
    savedOutfitsCount?: number;
    isOpen?: boolean;
    onClose?: () => void;
};

export default function VirtualPersonalClosetDrawer({
    viewedProduct,
    onWearItem,
    onViewDetails,
    onApplySavedOutfit,
    savedOutfitsCount = 0,
    isOpen = false,
    onClose,
}: VirtualPersonalClosetDrawerProps) {
    const [items, setItems] = useState<ClosetItem[]>([]);
    const [activeTab, setActiveTab] = useState<string>('');
    const [sortMode, setSortMode] = useState<SortMode>('all');
    const [savedOutfits, setSavedOutfits] = useState<SavedOutfit[]>([]);

    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;

    useEffect(() => {
        let mounted = true;

        const hydrateCloset = async () => {
            const token = localStorage.getItem('token');
            if (!token) {
                if (mounted) {
                    setItems([]);
                    setSavedOutfits([]);
                }
                return;
            }

            try {
                const [closetResponse, productsResponse] = await Promise.all([
                    fetch(`${API_URL}/api/virtual-closet`, {
                        headers: {
                            Authorization: `Bearer ${token}`,
                        },
                    }),
                    fetch(`${API_URL}/api/products`),
                ]);

                if (!closetResponse.ok) {
                    throw new Error('Unable to load closet data');
                }

                const data = await closetResponse.json();
                const apiResponse = (data || {}) as ClosetApiResponse;
                const productsData = productsResponse.ok ? await productsResponse.json() : [];
                const products = Array.isArray(productsData) ? productsData : [];
                const mapped = mapApiClosetItems(Array.isArray(apiResponse.items) ? apiResponse.items : [], products);

                if (mounted) {
                    setItems(mapped);
                }
            } catch {
                if (mounted) {
                    setItems([]);
                }
            }
        };

        hydrateCloset();

        return () => {
            mounted = false;
        };
    }, []);

    useEffect(() => {
        let mounted = true;

        const hydrateSavedOutfits = async () => {
            if (!token) {
                if (mounted) {
                    setSavedOutfits([]);
                }
                return;
            }

            try {
                const response = await fetch(`${API_URL}/api/saved-outfits`, {
                    headers: {
                        Authorization: `Bearer ${token}`,
                    },
                });

                if (!response.ok) {
                    throw new Error('Unable to load saved outfits');
                }

                const data = await response.json();
                const outfits = Array.isArray(data?.outfits) ? data.outfits : [];
                if (mounted) {
                    setSavedOutfits(outfits);
                }
            } catch {
                if (mounted) {
                    setSavedOutfits([]);
                }
            }
        };

        hydrateSavedOutfits();

        return () => {
            mounted = false;
        };
    }, [token]);

    const groupedCategories = useMemo<ClosetTab[]>(() => {
        const grouped = new Map<string, { label: string; items: ClosetItem[] }>();

        items.forEach((item) => {
            const key = item.categoryKey || normalizeCategoryKey(item.category);
            const existing = grouped.get(key);
            if (existing) {
                existing.items.push(item);
                return;
            }

            grouped.set(key, {
                label: item.category || formatCategoryLabel(item.category),
                items: [item],
            });
        });

        return Array.from(grouped.entries()).map(([key, value]) => ({
            key,
            label: value.label,
            items: value.items,
        }));
    }, [items]);

    const tabs = useMemo<ClosetTab[]>(() => {
        const baseTabs = [...groupedCategories];
        baseTabs.push({
            key: '__saved__',
            label: 'Saved',
            items: [],
        });
        return baseTabs;
    }, [groupedCategories]);

    useEffect(() => {
        if (!tabs.length) {
            setActiveTab('');
            return;
        }

        const hasActiveTab = tabs.some((group) => group.key === activeTab);
        if (!hasActiveTab) {
            setActiveTab(tabs[0].key);
        }
    }, [activeTab, tabs]);

    const activeGroup = tabs.find((group) => group.key === activeTab) || tabs[0];
    const activeItems = activeGroup?.items || [];

    const sortedItems = useMemo(() => {
        if (activeGroup?.key === '__saved__') {
            return [];
        }

        if (sortMode === 'match') {
            return [...activeItems].sort((a, b) =>
                scoreStylistMatch(b, viewedProduct) - scoreStylistMatch(a, viewedProduct),
            );
        }

        if (sortMode === 'newest') {
            return [...activeItems].sort((a, b) => {
                const aTime = new Date(a.purchasedAt || 0).getTime();
                const bTime = new Date(b.purchasedAt || 0).getTime();
                return bTime - aTime;
            });
        }

        return activeItems;
    }, [activeGroup?.key, activeItems, sortMode, viewedProduct]);

    const totalClosetItems = items.length;
    const wornItems = items.filter((item) => (item.wornCount ?? 0) > 0).length;

    const handleWearItem = (item: ClosetItem, selectedColor?: string, selectedSize?: string) => {
        setItems((prev) => prev.map((entry) => {
            if (entry.itemId !== item.itemId) {
                return entry;
            }
            return {
                ...entry,
                wornCount: (entry.wornCount ?? 0) + 1,
                lastWornAt: new Date().toISOString(),
            };
        }));
        onWearItem?.(item, selectedColor, selectedSize);
    };

    return (
        <aside
            className={`vpc-drawer vpc-drawer--sidebar ${isOpen ? 'vpc-drawer--open' : ''}`}
            aria-label="Virtual Personal Closet - SmartFit"
            role="region"
            data-testid="closet-drawer"
        >
            {/* Drawer Content */}
            <div className="vpc-drawer__content">
                {/* Header */}
                <header className="closet-header">
                    <div className="closet-header-top">
                        <div>
                            <span className="closet-brand">SMARTFIT</span>
                            <h2 className="closet-title">Your Closet</h2>
                        </div>
                        <button
                            type="button"
                            className="closet-close"
                            onClick={onClose}
                            aria-label="Close closet drawer"
                            title="Close"
                        >
                            ✕
                        </button>
                    </div>

                        <div className="closet-stats">
                            <div className="closet-stat">
                                <span className="closet-stat-num">{totalClosetItems}</span>
                                <span className="closet-stat-lbl">Tổng đồ</span>
                            </div>
                            <div className="closet-stat">
                                <span className="closet-stat-num">{wornItems}</span>
                                <span className="closet-stat-lbl">Đã mặc thử</span>
                            </div>
                            <div className="closet-stat">
                                <span className="closet-stat-num">{savedOutfitsCount || savedOutfits.length}</span>
                                <span className="closet-stat-lbl">Outfit lưu</span>
                            </div>
                        </div>
                </header>

                {/* Category Tabs */}
                <div className="closet-tabs" role="tablist" aria-label="Closet categories">
                    {tabs.map((category) => {
                        const isActive = activeTab === category.key;
                        const count = category.key === '__saved__' ? savedOutfits.length : category.items.length;

                        return (
                            <div
                                key={category.key}
                                className={`closet-tab${isActive ? ' closet-tab--on' : ''}`}
                                onClick={() => setActiveTab(category.key)}
                            >
                                {category.label}
                                <span className="closet-tab-count">{count}</span>
                            </div>
                        );
                    })}
                </div>

                {activeGroup?.key !== '__saved__' && (
                    <div className="drawer-chips">
                        {(['all', 'match', 'newest'] as SortMode[]).map((mode) => (
                            <button
                                key={mode}
                                type="button"
                                className={`chip${sortMode === mode ? ' chip--on' : ''}`}
                                onClick={() => setSortMode(mode)}
                            >
                                {mode === 'all' ? 'Tất cả' : mode === 'match' ? 'Match cao' : 'Mới nhất'}
                            </button>
                        ))}
                    </div>
                )}

                {/* Items Grid */}
                <div className="closet-items-grid" role="tabpanel">
                    {activeGroup?.key !== '__saved__' && sortedItems.length === 0 && activeGroup && (
                        <div className="closet-empty">Chưa có sản phẩm nào<br />trong danh mục này</div>
                    )}

                    {activeGroup?.key === '__saved__' && savedOutfits.length === 0 && (
                        <div className="closet-empty">Chưa có outfit đã lưu.</div>
                    )}

                    {activeGroup?.key === '__saved__' && savedOutfits.map((outfit) => (
                        <button
                            key={outfit._id}
                            type="button"
                            className="vpc-saved-outfit"
                            onClick={() => onApplySavedOutfit?.(outfit)}
                        >
                            <span className="vpc-saved-outfit__name">{outfit.name || 'Outfit chưa đặt tên'}</span>
                            <span className="vpc-saved-outfit__date">{new Date(outfit.createdAt || Date.now()).toLocaleDateString('vi-VN')}</span>
                        </button>
                    ))}

                    {activeGroup?.key !== '__saved__' && sortedItems.map((item) => {
                        const score = scoreStylistMatch(item, viewedProduct);

                        return (
                            <VirtualClosetItem
                                key={item.id}
                                item={item}
                                matchScore={Math.round(score * 100)}
                                onWear={handleWearItem}
                                onViewDetails={onViewDetails}
                            />
                        );
                    })}
                </div>
            </div>
        </aside>
    );
}

