const HEATMAP_COLORS: Record<HeatmapFitLevel, THREE.Color> = {
    tight: new THREE.Color('#EF4444'),
    fitted: new THREE.Color('#EAB308'),
    comfortable: new THREE.Color('#22C55E'),
    loose: new THREE.Color('#166534'),
};

const HEATMAP_SHADER_KEY = 'vto-heatmap-v1';

const toHeatmapStrength = (fit: HeatmapFitLevel, delta: number, severity?: number) => {
    const normalizedSeverity = typeof severity === 'number'
        ? THREE.MathUtils.clamp(severity, 0, 1)
        : THREE.MathUtils.clamp(Math.abs(delta) / 8, 0, 1);

    if (fit === 'tight') {
        return THREE.MathUtils.clamp(0.72 + normalizedSeverity * 0.28, 0.72, 1);
    }

    if (fit === 'fitted') {
        return THREE.MathUtils.clamp(0.48 + normalizedSeverity * 0.28, 0.45, 0.78);
    }

    if (fit === 'comfortable') {
        return THREE.MathUtils.clamp(0.35 + normalizedSeverity * 0.24, 0.32, 0.68);
    }

    return THREE.MathUtils.clamp(0.5 + normalizedSeverity * 0.32, 0.48, 0.86);
};

const toHeatmapVector = (zone?: GarmentHeatmapZone) => {
    if (!zone) {
        return new THREE.Vector4(0, 0, 0, 0);
    }

    const color = HEATMAP_COLORS[zone.fit];
    const intensity = toHeatmapStrength(zone.fit, zone.delta, zone.severity);
    return new THREE.Vector4(color.r, color.g, color.b, intensity);
};

const getMeshBounds = (mesh: THREE.Mesh) => {
    const geometry = mesh.geometry;
    if (!geometry.boundingBox) {
        geometry.computeBoundingBox();
    }

    const bbox = geometry.boundingBox;
    if (!bbox) {
        const center = new THREE.Vector3();
        const size = new THREE.Vector3(1, 1, 1);
        return {
            min: new THREE.Vector3(-0.5, -0.5, -0.5),
            max: new THREE.Vector3(0.5, 0.5, 0.5),
            center,
            size,
        };
    }

    const center = bbox.getCenter(new THREE.Vector3());
    const size = bbox.getSize(new THREE.Vector3());

    return {
        min: bbox.min.clone(),
        max: bbox.max.clone(),
        center,
        size,
    };
};

type FabricTextureSet = {
    normal: THREE.DataTexture;
    roughness: THREE.DataTexture;
};

const FABRIC_TEXTURE_SIZE = 96;
const fabricTextureCache = new Map<string, FabricTextureSet>();

const resolveFabricPreset = (profile?: GarmentFabricProfile): GarmentFabricPreset => {
    const presetKey = profile?.preset;
    if (presetKey && presetKey in FABRIC_PROFILE_PRESETS) {
        return presetKey;
    }

    const kind = profile?.kind;
    if (kind && kind in FABRIC_PROFILE_PRESETS) {
        return kind;
    }

    return 'cotton';
};

const normalizeFabricProfile = (profile?: GarmentFabricProfile): ResolvedFabricProfile => {
    const presetKey = resolveFabricPreset(profile);
    const preset = FABRIC_PROFILE_PRESETS[presetKey];

    return {
        preset: presetKey,
        kind: preset.kind,
        weaveScale: THREE.MathUtils.clamp(profile?.weaveScale ?? preset.weaveScale, 8, 42),
        weaveStrength: THREE.MathUtils.clamp(profile?.weaveStrength ?? preset.weaveStrength, 0.06, 0.9),
        wrinkleScale: THREE.MathUtils.clamp(profile?.wrinkleScale ?? preset.wrinkleScale, 1.2, 12),
        wrinkleStrength: THREE.MathUtils.clamp(profile?.wrinkleStrength ?? preset.wrinkleStrength, 0.02, 0.45),
        normalScale: THREE.MathUtils.clamp(profile?.normalScale ?? preset.normalScale, 0.05, 1.2),
        roughnessBias: THREE.MathUtils.clamp(profile?.roughnessBias ?? preset.roughnessBias, -0.35, 0.35),
        softness: THREE.MathUtils.clamp(profile?.softness ?? preset.softness, 0, 1),
        reflectance: THREE.MathUtils.clamp(profile?.reflectance ?? preset.reflectance, -0.25, 0.25),
        fuzzStrength: THREE.MathUtils.clamp(profile?.fuzzStrength ?? preset.fuzzStrength, 0, 0.4),
    };
};

const fabricNoise = (x: number, y: number, seed: number) => {
    const v = Math.sin((x + 37.19 * seed) * 12.9898 + (y + 91.73 * seed) * 78.233) * 43758.5453;
    return v - Math.floor(v);
};

const sampleFabricHeight = (u: number, v: number, profile: ResolvedFabricProfile) => {
    const weaveBase = Math.sin(u * profile.weaveScale * Math.PI * 2) * Math.sin(v * profile.weaveScale * Math.PI * 2);
    const weaveDiag = Math.sin((u + v) * profile.weaveScale * Math.PI * 1.35) * 0.4;
    const wrinkle = Math.sin(u * profile.wrinkleScale * Math.PI * 2.4) * Math.cos(v * profile.wrinkleScale * Math.PI * 1.8);
    const grain = (fabricNoise(u * 93, v * 97, profile.weaveScale) - 0.5) * 0.3;

    let kindAdjust = 1;
    if (profile.kind === 'denim') {
        kindAdjust = 1.15;
    } else if (profile.kind === 'satin') {
        kindAdjust = 0.55;
    } else if (profile.kind === 'knit') {
        kindAdjust = 1.25;
    }

    return (weaveBase * 0.56 + weaveDiag * 0.24 + wrinkle * 0.2 + grain) * kindAdjust;
};

const createDataTexture = (data: Uint8Array, size: number) => {
    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.generateMipmaps = true;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.needsUpdate = true;
    return texture;
};

const createFabricTextureSet = (profile: ResolvedFabricProfile): FabricTextureSet => {
    const size = FABRIC_TEXTURE_SIZE;
    const normalData = new Uint8Array(size * size * 4);
    const roughnessData = new Uint8Array(size * size * 4);
    const step = 1 / size;

    for (let y = 0; y < size; y += 1) {
        for (let x = 0; x < size; x += 1) {
            const u = x / size;
            const v = y / size;
            const i = (y * size + x) * 4;

            const h = sampleFabricHeight(u, v, profile);
            const hx = sampleFabricHeight(u + step, v, profile) - h;
            const hy = sampleFabricHeight(u, v + step, profile) - h;

            const softnessNormalFactor = 1 - profile.softness * 0.38;
            const nx = -hx * profile.weaveStrength * 4.2 * softnessNormalFactor;
            const ny = -hy * profile.weaveStrength * 4.2 * softnessNormalFactor;
            const nz = 1;
            const invLen = 1 / Math.sqrt(nx * nx + ny * ny + nz * nz);

            normalData[i + 0] = Math.round((nx * invLen * 0.5 + 0.5) * 255);
            normalData[i + 1] = Math.round((ny * invLen * 0.5 + 0.5) * 255);
            normalData[i + 2] = Math.round((nz * invLen * 0.5 + 0.5) * 255);
            normalData[i + 3] = 255;

            const wrinkleNoise = (fabricNoise(u * 121, v * 119, profile.wrinkleScale) - 0.5) * profile.wrinkleStrength;
            const fuzzNoise = (fabricNoise(u * 211, v * 199, profile.weaveScale + 3.7) - 0.5) * profile.fuzzStrength;
            const softnessLift = profile.softness * 0.08;
            const roughness = THREE.MathUtils.clamp(
                0.62 + profile.roughnessBias + h * 0.1 + wrinkleNoise + fuzzNoise * 0.35 + softnessLift,
                0.12,
                0.96,
            );
            const roughByte = Math.round(roughness * 255);
            roughnessData[i + 0] = roughByte;
            roughnessData[i + 1] = roughByte;
            roughnessData[i + 2] = roughByte;
            roughnessData[i + 3] = 255;
        }
    }

    return {
        normal: createDataTexture(normalData, size),
        roughness: createDataTexture(roughnessData, size),
    };
};

const getFabricTextureSet = (profile: ResolvedFabricProfile): FabricTextureSet => {
    const key = [
        profile.preset || profile.kind,
        profile.kind,
        profile.weaveScale.toFixed(3),
        profile.weaveStrength.toFixed(3),
        profile.wrinkleScale.toFixed(3),
        profile.wrinkleStrength.toFixed(3),
        profile.roughnessBias.toFixed(3),
        profile.softness.toFixed(3),
        profile.reflectance.toFixed(3),
        profile.fuzzStrength.toFixed(3),
    ].join('|');

    const existing = fabricTextureCache.get(key);
    if (existing) {
        return existing;
    }

    const next = createFabricTextureSet(profile);
    fabricTextureCache.set(key, next);
    return next;
};

const computeFabricRepeat = (mesh: THREE.Mesh, profile: ResolvedFabricProfile) => {
    const bounds = getMeshBounds(mesh);
    const width = Math.max(bounds.size.x, 0.25);
    const height = Math.max(bounds.size.y, 0.25);

    const repeatX = THREE.MathUtils.clamp(width * profile.weaveScale * 1.05, 6, 92);
    const repeatY = THREE.MathUtils.clamp(height * profile.weaveScale * 1.3, 8, 128);

    return new THREE.Vector2(repeatX, repeatY);
};

const cloneFabricTextureWithRepeat = (texture: THREE.DataTexture, repeat: THREE.Vector2) => {
    const next = texture.clone();
    next.wrapS = THREE.RepeatWrapping;
    next.wrapT = THREE.RepeatWrapping;
    next.repeat.copy(repeat);
    next.needsUpdate = true;
    return next;
};

const applyFabricProfileToMaterial = (
    material: THREE.MeshStandardMaterial,
    mesh: THREE.Mesh,
    profile?: GarmentFabricProfile,
) => {
    const resolved = normalizeFabricProfile(profile);
    const textures = getFabricTextureSet(resolved);
    const repeat = computeFabricRepeat(mesh, resolved);

    if (!material.normalMap) {
        material.normalMap = cloneFabricTextureWithRepeat(textures.normal, repeat);
    }

    if (!material.roughnessMap) {
        material.roughnessMap = cloneFabricTextureWithRepeat(textures.roughness, repeat);
    }

    if (material.normalScale) {
        const softenedNormal = resolved.normalScale * (1 - resolved.softness * 0.28);
        material.normalScale.set(softenedNormal, softenedNormal);
    } else {
        const softenedNormal = resolved.normalScale * (1 - resolved.softness * 0.28);
        material.normalScale = new THREE.Vector2(softenedNormal, softenedNormal);
    }

    const baseRoughness = material.roughness ?? FABRIC_DEFAULTS.roughness;
    const baseEnv = material.envMapIntensity ?? FABRIC_DEFAULTS.envMapIntensity;
    const baseMetalness = material.metalness ?? FABRIC_DEFAULTS.metalness;

    material.roughness = THREE.MathUtils.clamp(
        baseRoughness + resolved.roughnessBias + resolved.softness * 0.06 - resolved.reflectance * 0.08,
        0.08,
        1,
    );
    material.envMapIntensity = THREE.MathUtils.clamp(baseEnv + resolved.reflectance - resolved.softness * 0.12, 0, 3);
    material.metalness = THREE.MathUtils.clamp(baseMetalness * (1 - resolved.softness * 0.4), 0, 1);
    material.needsUpdate = true;
};

const buildFallbackAnchors = (mesh: THREE.Mesh, garmentType?: string): GarmentHeatmapAnchors => {
    const bounds = getMeshBounds(mesh);
    const { min, max, center, size } = bounds;

    let shoulderY, chestY, waistY, hipsY, thighY, legY;

    if (garmentType === 'bottom') {
        shoulderY = max.y + size.y * 0.5;
        chestY = max.y + size.y * 0.2;
        waistY = max.y - size.y * 0.05;
        hipsY = max.y - size.y * 0.25;
        thighY = max.y - size.y * 0.5;
        legY = min.y + size.y * 0.1;
    } else {
        shoulderY = min.y + size.y * 0.86;
        chestY = min.y + size.y * 0.68;
        waistY = min.y + size.y * 0.5;
        hipsY = min.y + size.y * 0.33;
        thighY = min.y + size.y * 0.2;
        legY = min.y + size.y * 0.09;
    }

    const shoulderOffsetX = Math.max(size.x * 0.22, 0.06);
    const legOffsetX = Math.max(size.x * 0.16, 0.05);
    const depth = Math.max(size.z, size.x * 0.45, 0.08);

    return {
        shoulderL: new THREE.Vector3(center.x - shoulderOffsetX, shoulderY, center.z),
        shoulderR: new THREE.Vector3(center.x + shoulderOffsetX, shoulderY, center.z),
        chest: new THREE.Vector3(center.x, chestY, center.z),
        waist: new THREE.Vector3(center.x, waistY, center.z),
        hips: new THREE.Vector3(center.x, hipsY, center.z),
        thighL: new THREE.Vector3(center.x - legOffsetX, thighY, center.z),
        thighR: new THREE.Vector3(center.x + legOffsetX, thighY, center.z),
        legL: new THREE.Vector3(center.x - legOffsetX, legY, center.z),
        legR: new THREE.Vector3(center.x + legOffsetX, legY, center.z),
        shoulderRadius: new THREE.Vector3(Math.max(size.x * 0.15, 0.04), Math.max(size.y * 0.1, 0.04), Math.max(depth * 0.22, 0.04)),
        chestRadius: new THREE.Vector3(Math.max(size.x * 0.24, 0.06), Math.max(size.y * 0.13, 0.05), Math.max(depth * 0.28, 0.05)),
        waistRadius: new THREE.Vector3(Math.max(size.x * 0.2, 0.05), Math.max(size.y * 0.13, 0.05), Math.max(depth * 0.25, 0.05)),
        hipsRadius: new THREE.Vector3(Math.max(size.x * 0.21, 0.05), Math.max(size.y * 0.14, 0.05), Math.max(depth * 0.27, 0.05)),
        thighRadius: new THREE.Vector3(Math.max(size.x * 0.16, 0.05), Math.max(size.y * 0.1, 0.05), Math.max(depth * 0.2, 0.05)),
        legOpeningRadius: new THREE.Vector3(Math.max(size.x * 0.14, 0.04), Math.max(size.y * 0.09, 0.04), Math.max(depth * 0.18, 0.04)),
    };
};

const getHeatmapState = (material: THREE.MeshStandardMaterial, mesh: THREE.Mesh, garmentType?: string): GarmentHeatmapState => {
    const userData = material.userData as Record<string, unknown>;
    const existing = userData.vtoHeatmap as HeatmapUserData | undefined;
    if (existing?.state) {
        return existing.state;
    }

    const anchors = buildFallbackAnchors(mesh, garmentType);
    const state: GarmentHeatmapState = {
        enabled: { value: 0 },
        shoulder: { value: new THREE.Vector4(0, 0, 0, 0) },
        chest: { value: new THREE.Vector4(0, 0, 0, 0) },
        waist: { value: new THREE.Vector4(0, 0, 0, 0) },
        hips: { value: new THREE.Vector4(0, 0, 0, 0) },
        thigh: { value: new THREE.Vector4(0, 0, 0, 0) },
        legOpening: { value: new THREE.Vector4(0, 0, 0, 0) },
        shoulderLCenter: { value: anchors.shoulderL },
        shoulderRCenter: { value: anchors.shoulderR },
        chestCenter: { value: anchors.chest },
        waistCenter: { value: anchors.waist },
        hipsCenter: { value: anchors.hips },
        thighLCenter: { value: anchors.thighL },
        thighRCenter: { value: anchors.thighR },
        legLCenter: { value: anchors.legL },
        legRCenter: { value: anchors.legR },
        shoulderRadius: { value: anchors.shoulderRadius },
        chestRadius: { value: anchors.chestRadius },
        waistRadius: { value: anchors.waistRadius },
        hipsRadius: { value: anchors.hipsRadius },
        thighRadius: { value: anchors.thighRadius },
        legOpeningRadius: { value: anchors.legOpeningRadius },
    };

    material.onBeforeCompile = (shader) => {
        shader.uniforms.uVtoHeatEnabled = state.enabled;
        shader.uniforms.uVtoHeatShoulder = state.shoulder;
        shader.uniforms.uVtoHeatChest = state.chest;
        shader.uniforms.uVtoHeatWaist = state.waist;
        shader.uniforms.uVtoHeatHips = state.hips;
        shader.uniforms.uVtoHeatThigh = state.thigh;
        shader.uniforms.uVtoHeatLegOpening = state.legOpening;
        shader.uniforms.uVtoHeatShoulderL = state.shoulderLCenter;
        shader.uniforms.uVtoHeatShoulderR = state.shoulderRCenter;
        shader.uniforms.uVtoHeatChestCenter = state.chestCenter;
        shader.uniforms.uVtoHeatWaistCenter = state.waistCenter;
        shader.uniforms.uVtoHeatHipsCenter = state.hipsCenter;
        shader.uniforms.uVtoHeatThighL = state.thighLCenter;
        shader.uniforms.uVtoHeatThighR = state.thighRCenter;
        shader.uniforms.uVtoHeatLegL = state.legLCenter;
        shader.uniforms.uVtoHeatLegR = state.legRCenter;
        shader.uniforms.uVtoHeatShoulderRadius = state.shoulderRadius;
        shader.uniforms.uVtoHeatChestRadius = state.chestRadius;
        shader.uniforms.uVtoHeatWaistRadius = state.waistRadius;
        shader.uniforms.uVtoHeatHipsRadius = state.hipsRadius;
        shader.uniforms.uVtoHeatThighRadius = state.thighRadius;
        shader.uniforms.uVtoHeatLegOpeningRadius = state.legOpeningRadius;

        shader.vertexShader = shader.vertexShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vVtoHeatPos;')
            .replace('#include <begin_vertex>', '#include <begin_vertex>\nvVtoHeatPos = transformed;');

        shader.fragmentShader = shader.fragmentShader
            .replace(
                '#include <common>',
                `#include <common>
varying vec3 vVtoHeatPos;
uniform float uVtoHeatEnabled;
uniform vec4 uVtoHeatShoulder;
uniform vec4 uVtoHeatChest;
uniform vec4 uVtoHeatWaist;
uniform vec4 uVtoHeatHips;
uniform vec4 uVtoHeatThigh;
uniform vec4 uVtoHeatLegOpening;
uniform vec3 uVtoHeatShoulderL;
uniform vec3 uVtoHeatShoulderR;
uniform vec3 uVtoHeatChestCenter;
uniform vec3 uVtoHeatWaistCenter;
uniform vec3 uVtoHeatHipsCenter;
uniform vec3 uVtoHeatThighL;
uniform vec3 uVtoHeatThighR;
uniform vec3 uVtoHeatLegL;
uniform vec3 uVtoHeatLegR;
uniform vec3 uVtoHeatShoulderRadius;
uniform vec3 uVtoHeatChestRadius;
uniform vec3 uVtoHeatWaistRadius;
uniform vec3 uVtoHeatHipsRadius;
uniform vec3 uVtoHeatThighRadius;
uniform vec3 uVtoHeatLegOpeningRadius;

float vtoEllipsoidWeight(vec3 p, vec3 center, vec3 radius) {
    vec3 safeRadius = max(radius, vec3(0.0001));
    vec3 q = (p - center) / safeRadius;
    float d2 = dot(q, q);
    return exp(-d2 * 2.4);
}`,
            )
            .replace(
                '#include <opaque_fragment>',
                `if (uVtoHeatEnabled > 0.5) {
    float shoulderW = max(
        vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatShoulderL, uVtoHeatShoulderRadius),
        vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatShoulderR, uVtoHeatShoulderRadius)
    );
    float chestW = vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatChestCenter, uVtoHeatChestRadius);
    float waistW = vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatWaistCenter, uVtoHeatWaistRadius);
    float hipsW = vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatHipsCenter, uVtoHeatHipsRadius);
    float thighW = max(
        vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatThighL, uVtoHeatThighRadius),
        vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatThighR, uVtoHeatThighRadius)
    );
    float legW = max(
        vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatLegL, uVtoHeatLegOpeningRadius),
        vtoEllipsoidWeight(vVtoHeatPos, uVtoHeatLegR, uVtoHeatLegOpeningRadius)
    );

    chestW *= (1.0 - shoulderW * 0.35);
    waistW *= (1.0 - shoulderW * 0.2);
    hipsW *= (1.0 - shoulderW * 0.1);
    thighW *= (1.0 - shoulderW * 0.08);

    float shoulderI = shoulderW * uVtoHeatShoulder.a;
    float chestI = chestW * uVtoHeatChest.a;
    float waistI = waistW * uVtoHeatWaist.a;
    float hipsI = hipsW * uVtoHeatHips.a;
    float thighI = thighW * uVtoHeatThigh.a;
    float legI = legW * uVtoHeatLegOpening.a;

    float influence = shoulderI + chestI + waistI + hipsI + thighI + legI;
    if (influence > 0.0001) {
        vec3 overlay = (
            uVtoHeatShoulder.rgb * shoulderI +
            uVtoHeatChest.rgb * chestI +
            uVtoHeatWaist.rgb * waistI +
            uVtoHeatHips.rgb * hipsI +
            uVtoHeatThigh.rgb * thighI +
            uVtoHeatLegOpening.rgb * legI
        ) / influence;

        float blend = clamp(influence, 0.0, 1.0) * 0.78;
        outgoingLight = mix(outgoingLight, overlay, blend);
    }
}

#include <opaque_fragment>`,
            );
    };

    material.customProgramCacheKey = () => HEATMAP_SHADER_KEY;
    material.needsUpdate = true;

    userData.vtoHeatmap = { state };
    return state;
};

export type GarmentMorphSyncOptions = {
    influenceScale?: number;
    smoothing?: number;
    maxInfluence?: number;
};

type MorphChannelBinding = {
    targetIndex: number;
    sourceIndex: number;
    sourceInfluences: number[];
};

type MorphMeshBinding = {
    targetMesh: THREE.Mesh;
    channels: MorphChannelBinding[];
};

const normalizeBoneName = (name: string) =>
    name
        .toLowerCase()
        .replace(/mixamorig|armature|skeleton|bone/gi, '')
        .replace(/[^a-z0-9]/g, '');

const BONE_ALIASES: Record<string, string[]> = {
    hips: ['pelvis', 'ccbasepelvis', 'hip', 'root'],
    spine: ['spine01', 'spine1', 'abdomen', 'ccbasespine01', 'lowerback'],
    spine1: ['spine02', 'spine2', 'chest', 'ccbasespine02', 'middleback'],
    spine2: ['spine03', 'spine3', 'upperchest', 'ccbasespine03', 'upperback'],
    neck: ['ccbaseneck', 'neck01'],
    head: ['ccbasehead'],
    leftshoulder: ['lshoulder', 'claviclel', 'leftcollar', 'ccbaselcollarbone', 'shoulderl'],
    leftarm: ['larm', 'upperarml', 'bicepl', 'ccbaselupperarm', 'armleft', 'leftupperarm'],
    leftforearm: ['lforearm', 'lowerarml', 'ccbasellowerarm', 'elbowleft', 'leftlowerarm'],
    lefthand: ['lhand', 'wristl', 'ccbaselhand', 'handleft'],
    rightshoulder: ['rshoulder', 'clavicler', 'rightcollar', 'ccbasercollarbone', 'shoulderr'],
    rightarm: ['rarm', 'upperarmr', 'bicepr', 'ccbaserupperarm', 'armright', 'rightupperarm'],
    rightforearm: ['rforearm', 'lowerarmr', 'ccbaserlowerarm', 'elbowright', 'rightlowerarm'],
    righthand: ['rhand', 'wristr', 'ccbaserhand', 'handright'],
    leftupleg: ['lupleg', 'thighl', 'leftthigh', 'ccbaselthigh', 'uplegleft'],
    leftleg: ['lleg', 'calfl', 'leftcalf', 'ccbaselcalf', 'legleft', 'leftlowerleg'],
    leftfoot: ['lfoot', 'footl', 'ccbaselfoot', 'footleft'],
    rightupleg: ['rupleg', 'thighr', 'rightthigh', 'ccbaserthigh', 'uplegright'],
    rightleg: ['rleg', 'calfr', 'rightcalf', 'ccbasercalf', 'legright', 'rightlowerleg'],
    rightfoot: ['rfoot', 'footr', 'ccbaserfoot', 'footright'],
};

const resolveAlias = (normalizedName: string): string => {
    for (const [standard, aliases] of Object.entries(BONE_ALIASES)) {
        if (normalizedName === standard || aliases.includes(normalizedName)) {
            return standard;
        }
    }
    return normalizedName;
};

const toMaterialArray = (material: THREE.Material | THREE.Material[]) =>
    Array.isArray(material) ? material : [material];

const buildAvatarBoneLookup = (avatarScene: THREE.Object3D): AvatarBoneLookup => {
    const exact = new Map<string, THREE.Bone>();
    const normalized = new Map<string, THREE.Bone>();
    const all: THREE.Bone[] = [];

    avatarScene.traverse((child) => {
        if (!(child as THREE.Bone).isBone) {
            return;
        }

        all.push(child);
        exact.set(child.name.toLowerCase(), child);
        normalized.set(normalizeBoneName(child.name), child);
    });

    return { exact, normalized, all };
};

const findAvatarBone = (boneName: string, lookup: AvatarBoneLookup): THREE.Bone | null => {
    const exactName = boneName.toLowerCase();
    const rawNormalized = normalizeBoneName(boneName);
    const normalizedName = resolveAlias(rawNormalized);

    const exact = lookup.exact.get(exactName);
    if (exact) {
        return exact;
    }

    const normalized = lookup.normalized.get(rawNormalized) || lookup.normalized.get(normalizedName);
    if (normalized) {
        return normalized;
    }

    // Try finding by alias for all avatar bones
    const matchByAlias = lookup.all.find((avatarBone) => {
        const avatarRaw = normalizeBoneName(avatarBone.name);
        const avatarAlias = resolveAlias(avatarRaw);
        return avatarAlias === normalizedName;
    });

    if (matchByAlias) {
        return matchByAlias;
    }

    return (
        lookup.all.find((avatarBone) => {
            const avatarNormalized = normalizeBoneName(avatarBone.name);
            return avatarNormalized.endsWith(rawNormalized) || rawNormalized.endsWith(avatarNormalized);
        }) || null
    );
};

export const isAvatarMesh = (mesh: THREE.Mesh): boolean => {
    const meshName = mesh.name.toLowerCase();
    const regex = /\b(body|skin|avatar|mannequin|flesh|head|face|eye|teeth|hair|shoe|foot|hand|hands|feet)\b/i;

    if (regex.test(meshName)) return true;

    const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
    for (const mat of materials) {
        const matName = mat.name ? mat.name.toLowerCase() : '';
        if (regex.test(matName)) return true;
    }
    return false;
};

/**
 * Convert every mesh material to MeshStandardMaterial (PBR) so that
 * roughness / metalness / envMapIntensity are always available.
 * Preserves color, map (diffuse texture), normalMap and aoMap from the source.
 */
export const prepareGarmentMaterials = (garmentRoot: THREE.Object3D) => {
    garmentRoot.traverse((child) => {
        if (!(child as THREE.Mesh).isMesh) {
            return;
        }

        if (isAvatarMesh(child)) {
            child.visible = false;
        }

        child.castShadow = true;
        child.receiveShadow = true;
        child.frustumCulled = false;

        const currentMaterials = toMaterialArray(child.material);
        const converted = currentMaterials.map((srcMat) => {
            // If already MeshStandardMaterial (or subclass), clone in-place
            if (srcMat instanceof THREE.MeshStandardMaterial) {
                const cloned = srcMat.clone();
                cloned.side = THREE.DoubleSide;
                cloned.transparent = false;
                cloned.opacity = 1;
                // Polygon offset pushes the garment slightly back in depth buffer
                // to prevent z-fighting with the avatar skin surface.
                cloned.polygonOffset = true;
                cloned.polygonOffsetFactor = -1;
                cloned.polygonOffsetUnits = -1;
                // Apply fabric defaults only when the values look like Three.js
                // auto-defaults (roughness 1 / metalness 0) — i.e. the GLB
                // did not provide intentional PBR authoring.
                if (cloned.roughness === 1 && cloned.metalness === 0) {
                    cloned.roughness = FABRIC_DEFAULTS.roughness;
                    cloned.metalness = FABRIC_DEFAULTS.metalness;
                    cloned.envMapIntensity = FABRIC_DEFAULTS.envMapIntensity;
                }
                cloned.needsUpdate = true;
                return cloned;
            }

            // Convert non-PBR material → MeshStandardMaterial
            const srcAny = srcMat as MaterialWithColor & {
                map?: THREE.Texture | null;
                normalMap?: THREE.Texture | null;
                aoMap?: THREE.Texture | null;
            };

            const standard = new THREE.MeshStandardMaterial({
                color: srcAny.color ? srcAny.color.clone() : new THREE.Color(0xffffff),
                map: srcAny.map ?? null,
                normalMap: srcAny.normalMap ?? null,
                aoMap: srcAny.aoMap ?? null,
                roughness: FABRIC_DEFAULTS.roughness,
                metalness: FABRIC_DEFAULTS.metalness,
                envMapIntensity: FABRIC_DEFAULTS.envMapIntensity,
                side: THREE.DoubleSide,
                transparent: false,
                opacity: 1,
                polygonOffset: true,
                polygonOffsetFactor: -1,
                polygonOffsetUnits: -1,
            });
            standard.needsUpdate = true;
            return standard;
        });

        child.material = Array.isArray(child.material) ? converted : converted[0];
    });
};

/**
 * Apply PBR tuning to every mesh material.
 * Materials are guaranteed to be MeshStandardMaterial after prepareGarmentMaterials().
 */
export const tuneGarmentMaterials = (
    garmentRoot: THREE.Object3D,
    tuning: GarmentMaterialTuning = {},
) => {
    const roughness = typeof tuning.roughness === 'number'
        ? THREE.MathUtils.clamp(tuning.roughness, 0, 1)
        : undefined;
    const metalness = typeof tuning.metalness === 'number'
        ? THREE.MathUtils.clamp(tuning.metalness, 0, 1)
        : undefined;
    const envMapIntensity = typeof tuning.envMapIntensity === 'number'
        ? THREE.MathUtils.clamp(tuning.envMapIntensity, 0, 3)
        : undefined;
    const fabricProfile = tuning.fabricProfile;

    garmentRoot.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) {
            return;
        }

        const materials = toMaterialArray(child.material);
        materials.forEach((mat) => {
            // After prepareGarmentMaterials, all materials are MeshStandardMaterial
            const stdMat = mat as THREE.MeshStandardMaterial;

            if (roughness !== undefined) stdMat.roughness = roughness;
            if (metalness !== undefined) stdMat.metalness = metalness;
            if (envMapIntensity !== undefined) stdMat.envMapIntensity = envMapIntensity;

            if (fabricProfile) {
                applyFabricProfileToMaterial(stdMat, child, fabricProfile);
            }

            const userData = stdMat.userData as Record<string, unknown>;
            userData.vtoBaseRoughness = stdMat.roughness;
            userData.vtoBaseEnvMapIntensity = stdMat.envMapIntensity;

            stdMat.needsUpdate = true;
        });
    });
};

export const prepareGarmentMaterialsWithTuning = (
    garmentRoot: THREE.Object3D,
    tuning: GarmentMaterialTuning = {},
) => {
    prepareGarmentMaterials(garmentRoot);
    tuneGarmentMaterials(garmentRoot, tuning);
};

export const applyGarmentColor = (garmentRoot: THREE.Object3D, color?: THREE.ColorRepresentation) => {
    if (!color) return;

    let safeColor = color;
    if (safeColor === '0') safeColor = 0x000000;
    
    let nextColor: THREE.Color;
    try {
        nextColor = new THREE.Color(safeColor);
    } catch (err) {
        console.warn(`[GarmentModel] Invalid color: ${color}, ignoring`);
        return;
    }

    garmentRoot.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) {
            return;
        }

        // Do not color the hidden avatar/body meshes
        if (isAvatarMesh(child)) {
            return;
        }

        const materials = toMaterialArray(child.material);
        materials.forEach((material) => {
            const mutableMaterial = material as MaterialWithColor;
            if (mutableMaterial.color) {
                mutableMaterial.color.copy(nextColor);
                mutableMaterial.needsUpdate = true;
                if (!mutableMaterial.userData) mutableMaterial.userData = {};
                mutableMaterial.userData.targetColor = nextColor.clone();
            }
        });
    });
};

export const setGarmentTargetColor = (garmentRoot: THREE.Object3D, color?: THREE.ColorRepresentation) => {
    if (!color) return;

    let safeColor = color;
    if (safeColor === '0') safeColor = 0x000000;
    
    let nextColor: THREE.Color;
    try {
        nextColor = new THREE.Color(safeColor);
    } catch (err) {
        console.warn(`[GarmentModel] Invalid color: ${color}, ignoring`);
        return;
    }

    garmentRoot.traverse((child) => {
        if (!(child instanceof THREE.Mesh) || isAvatarMesh(child)) {
            return;
        }

        const materials = toMaterialArray(child.material);
        materials.forEach((material) => {
            const mutableMaterial = material as MaterialWithColor;
            if (mutableMaterial.color) {
                if (!mutableMaterial.userData) mutableMaterial.userData = {};
                mutableMaterial.userData.targetColor = nextColor;
            }
        });
    });
};

export const lerpGarmentColor = (garmentRoot: THREE.Object3D, delta: number) => {
    garmentRoot.traverse((child) => {
        if (!(child instanceof THREE.Mesh) || isAvatarMesh(child)) return;

        const materials = toMaterialArray(child.material);
        materials.forEach((material) => {
            const mutableMaterial = material as MaterialWithColor;
            if (mutableMaterial.color && mutableMaterial.userData?.targetColor) {
                mutableMaterial.color.lerp(mutableMaterial.userData.targetColor, delta * 5);
                mutableMaterial.needsUpdate = true;
            }
        });
    });
};

const HEATMAP_BONE_HINTS = {
    shoulderLeft: ['LeftShoulder', 'LeftArm', 'LeftUpperArm'],
    shoulderRight: ['RightShoulder', 'RightArm', 'RightUpperArm'],
    chest: ['UpperChest', 'Spine2', 'Chest'],
    waist: ['Spine1', 'Spine', 'Hips'],
    hips: ['Hips', 'LeftUpLeg', 'RightUpLeg'],
    thighLeft: ['LeftUpLeg', 'LeftLeg'],
    thighRight: ['RightUpLeg', 'RightLeg'],
    legLeft: ['LeftLeg', 'LeftFoot'],
    legRight: ['RightLeg', 'RightFoot'],
};

const averageBoneWorldPosition = (lookup: AvatarBoneLookup, hints: string[]): THREE.Vector3 | null => {
    const points: THREE.Vector3[] = [];

    hints.forEach((hint) => {
        const bone = findAvatarBone(hint, lookup);
        if (!bone) {
            return;
        }

        points.push(bone.getWorldPosition(new THREE.Vector3()));
    });

    if (points.length === 0) {
        return null;
    }

    const sum = points.reduce((acc, point) => acc.add(point), new THREE.Vector3());
    return sum.multiplyScalar(1 / points.length);
};

const worldToMeshLocal = (mesh: THREE.Mesh, worldPoint: THREE.Vector3) => mesh.worldToLocal(worldPoint.clone());

const blendVec3 = (from: THREE.Vector3, to: THREE.Vector3, alpha: number) => from.clone().lerp(to, alpha);

const buildAnchorsFromAvatar = (mesh: THREE.Mesh, avatarScene: THREE.Object3D, garmentType?: string): GarmentHeatmapAnchors => {
    const fallback = buildFallbackAnchors(mesh, garmentType);
    const lookup = buildAvatarBoneLookup(avatarScene);

    const leftShoulderWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.shoulderLeft);
    const rightShoulderWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.shoulderRight);
    const chestWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.chest);
    const waistWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.waist);
    const hipsWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.hips);
    const thighLeftWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.thighLeft);
    const thighRightWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.thighRight);
    const legLeftWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.legLeft);
    const legRightWorld = averageBoneWorldPosition(lookup, HEATMAP_BONE_HINTS.legRight);

    const shoulderL = leftShoulderWorld ? worldToMeshLocal(mesh, leftShoulderWorld) : fallback.shoulderL.clone();
    const shoulderR = rightShoulderWorld ? worldToMeshLocal(mesh, rightShoulderWorld) : fallback.shoulderR.clone();
    const chest = chestWorld ? worldToMeshLocal(mesh, chestWorld) : fallback.chest.clone();
    const waist = waistWorld ? worldToMeshLocal(mesh, waistWorld) : fallback.waist.clone();
    const hips = hipsWorld ? worldToMeshLocal(mesh, hipsWorld) : fallback.hips.clone();
    const thighL = thighLeftWorld ? worldToMeshLocal(mesh, thighLeftWorld) : fallback.thighL.clone();
    const thighR = thighRightWorld ? worldToMeshLocal(mesh, thighRightWorld) : fallback.thighR.clone();
    const legL = legLeftWorld ? worldToMeshLocal(mesh, legLeftWorld) : fallback.legL.clone();
    const legR = legRightWorld ? worldToMeshLocal(mesh, legRightWorld) : fallback.legR.clone();

    const bounds = getMeshBounds(mesh);
    const shoulderSpan = Math.max(shoulderL.distanceTo(shoulderR), bounds.size.x * 0.25, 0.08);
    const lowerSpan = Math.max(thighL.distanceTo(thighR), bounds.size.x * 0.2, 0.08);
    const torsoHeight = Math.max(Math.abs(chest.y - hips.y), Math.abs(waist.y - hips.y), bounds.size.y * 0.2, 0.08);
    const legHeight = Math.max(Math.abs(thighL.y - legL.y), Math.abs(thighR.y - legR.y), bounds.size.y * 0.12, 0.06);
    const depth = Math.max(bounds.size.z, shoulderSpan * 0.42, 0.08);

    const anchorBlend = 0.82;
    const blendedShoulderL = blendVec3(fallback.shoulderL, shoulderL, anchorBlend);
    const blendedShoulderR = blendVec3(fallback.shoulderR, shoulderR, anchorBlend);
    const blendedChest = blendVec3(fallback.chest, chest, anchorBlend);
    const blendedWaist = blendVec3(fallback.waist, waist, anchorBlend);
    const blendedHips = blendVec3(fallback.hips, hips, anchorBlend);
    const blendedThighL = blendVec3(fallback.thighL, thighL, anchorBlend);
    const blendedThighR = blendVec3(fallback.thighR, thighR, anchorBlend);
    const blendedLegL = blendVec3(fallback.legL, legL, anchorBlend);
    const blendedLegR = blendVec3(fallback.legR, legR, anchorBlend);

    return {
        shoulderL: blendedShoulderL,
        shoulderR: blendedShoulderR,
        chest: blendedChest,
        waist: blendedWaist,
        hips: blendedHips,
        thighL: blendedThighL,
        thighR: blendedThighR,
        legL: blendedLegL,
        legR: blendedLegR,
        shoulderRadius: new THREE.Vector3(
            Math.max(shoulderSpan * 0.18, fallback.shoulderRadius.x),
            Math.max(torsoHeight * 0.12, fallback.shoulderRadius.y),
            Math.max(depth * 0.2, fallback.shoulderRadius.z),
        ),
        chestRadius: new THREE.Vector3(
            Math.max(shoulderSpan * 0.28, fallback.chestRadius.x),
            Math.max(torsoHeight * 0.18, fallback.chestRadius.y),
            Math.max(depth * 0.28, fallback.chestRadius.z),
        ),
        waistRadius: new THREE.Vector3(
            Math.max(shoulderSpan * 0.24, fallback.waistRadius.x),
            Math.max(torsoHeight * 0.17, fallback.waistRadius.y),
            Math.max(depth * 0.24, fallback.waistRadius.z),
        ),
        hipsRadius: new THREE.Vector3(
            Math.max(shoulderSpan * 0.25, fallback.hipsRadius.x),
            Math.max(torsoHeight * 0.18, fallback.hipsRadius.y),
            Math.max(depth * 0.27, fallback.hipsRadius.z),
        ),
        thighRadius: new THREE.Vector3(
            Math.max(lowerSpan * 0.2, fallback.thighRadius.x),
            Math.max(legHeight * 0.55, fallback.thighRadius.y),
            Math.max(depth * 0.2, fallback.thighRadius.z),
        ),
        legOpeningRadius: new THREE.Vector3(
            Math.max(lowerSpan * 0.17, fallback.legOpeningRadius.x),
            Math.max(legHeight * 0.5, fallback.legOpeningRadius.y),
            Math.max(depth * 0.17, fallback.legOpeningRadius.z),
        ),
    };
};

export const applyGarmentHeatmap = (
    garmentRoot: THREE.Object3D,
    enabled: boolean,
    zones: GarmentHeatmapZone[] = [],
    avatarScene: THREE.Object3D | null = null,
    garmentType?: string,
) => {
    const zoneMap = zones.reduce<Partial<Record<GarmentHeatmapZoneKey, GarmentHeatmapZone>>>((acc, zone) => {
        acc[zone.key] = zone;
        return acc;
    }, {});

    const getFitSeverity = (fit: HeatmapFitLevel) => zones.reduce((maxSeverity, zone) => {
        if (zone.fit !== fit) {
            return maxSeverity;
        }

        const severity = typeof zone.severity === 'number'
            ? THREE.MathUtils.clamp(zone.severity, 0, 1)
            : THREE.MathUtils.clamp(Math.abs(zone.delta) / 8, 0, 1);
        return Math.max(maxSeverity, severity);
    }, 0);

    const tightSeverity = getFitSeverity('tight');
    const looseSeverity = getFitSeverity('loose');

    garmentRoot.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) {
            return;
        }

        const materials = toMaterialArray(child.material);
        materials.forEach((material) => {
            if (!(material instanceof THREE.MeshStandardMaterial)) {
                return;
            }

            const userData = material.userData as Record<string, unknown>;
            const existing = userData.vtoHeatmap as HeatmapUserData | undefined;
            if (!enabled && !existing?.state && zones.length === 0) {
                return;
            }

            const state = existing?.state || getHeatmapState(material, child, garmentType);
            state.enabled.value = enabled ? 1 : 0;

            const anchors = avatarScene
                ? buildAnchorsFromAvatar(child, avatarScene, garmentType)
                : buildFallbackAnchors(child, garmentType);

            state.shoulderLCenter.value.copy(anchors.shoulderL);
            state.shoulderRCenter.value.copy(anchors.shoulderR);
            state.chestCenter.value.copy(anchors.chest);
            state.waistCenter.value.copy(anchors.waist);
            state.hipsCenter.value.copy(anchors.hips);
            state.thighLCenter.value.copy(anchors.thighL);
            state.thighRCenter.value.copy(anchors.thighR);
            state.legLCenter.value.copy(anchors.legL);
            state.legRCenter.value.copy(anchors.legR);
            state.shoulderRadius.value.copy(anchors.shoulderRadius);
            state.chestRadius.value.copy(anchors.chestRadius);
            state.waistRadius.value.copy(anchors.waistRadius);
            state.hipsRadius.value.copy(anchors.hipsRadius);
            state.thighRadius.value.copy(anchors.thighRadius);
            state.legOpeningRadius.value.copy(anchors.legOpeningRadius);

            state.shoulder.value.copy(toHeatmapVector(zoneMap.shoulder));
            state.chest.value.copy(toHeatmapVector(zoneMap.chest));
            state.waist.value.copy(toHeatmapVector(zoneMap.waist));
            state.hips.value.copy(toHeatmapVector(zoneMap.hips));
            state.thigh.value.copy(toHeatmapVector(zoneMap.thigh));
            state.legOpening.value.copy(toHeatmapVector(zoneMap.legOpening));

            const baseRoughness = typeof userData.vtoBaseRoughness === 'number'
                ? (userData.vtoBaseRoughness as number)
                : material.roughness;
            const baseEnv = typeof userData.vtoBaseEnvMapIntensity === 'number'
                ? (userData.vtoBaseEnvMapIntensity as number)
                : material.envMapIntensity;

            if (typeof userData.vtoBaseRoughness !== 'number') {
                userData.vtoBaseRoughness = baseRoughness;
            }

            if (typeof userData.vtoBaseEnvMapIntensity !== 'number') {
                userData.vtoBaseEnvMapIntensity = baseEnv;
            }

            // Tight cloth tends to look smoother and slightly shinier; loose cloth does the opposite.
            material.roughness = THREE.MathUtils.clamp(baseRoughness - tightSeverity * 0.18 + looseSeverity * 0.06, 0.08, 1);
            material.envMapIntensity = THREE.MathUtils.clamp(baseEnv + tightSeverity * 0.28 - looseSeverity * 0.08, 0, 3);
        });
    });
};

export const bindGarmentToAvatarSkeleton = (
    garmentRoot: THREE.Object3D,
    avatarScene: THREE.Object3D,
    skinOffset = 0,
    scaleFactors?: THREE.Vector3,
    garmentType?: string
): { boundMeshCount: number; attachedMeshCount: number; missingBoneNames: string[] } => {
    const lookup = buildAvatarBoneLookup(avatarScene);
    const missingBoneNames = new Set<string>();
    let boundMeshCount = 0;
    let attachedMeshCount = 0;

    // Collect meshes BEFORE processing — calling attach() during traverse()
    // mutates the scene graph and causes nodes to be skipped or revisited.
    const skinnedMeshes: THREE.SkinnedMesh[] = [];
    const staticMeshes: THREE.Mesh[] = [];

    garmentRoot.traverse((child) => {
        if ((child as THREE.SkinnedMesh).isSkinnedMesh && (child as THREE.SkinnedMesh).skeleton) {
            skinnedMeshes.push(child as THREE.SkinnedMesh);
        } else if ((child as THREE.Mesh).isMesh) {
            staticMeshes.push(child as THREE.Mesh);
        }
    });

    // ── SkinnedMesh: remap skeleton to avatar bones ──
    for (const mesh of skinnedMeshes) {
        const mappedBones = mesh.skeleton.bones.map((garmentBone) => {
            const avatarBone = findAvatarBone(garmentBone.name, lookup);
            if (!avatarBone) {
                missingBoneNames.add(garmentBone.name);
                return garmentBone;
            }
            return avatarBone;
        });

        const remappedSkeleton = new THREE.Skeleton(
            mappedBones,
            mesh.skeleton.boneInverses.map((inverse) => inverse.clone()),
        );

        if (scaleFactors) {
            // Find the original authored Y-position of the anchor bone.
            // For bottoms, we anchor at the Hips.
            // For tops/dresses, we anchor at the Neck or Chest.
            let garmentAnchorY = 1.0; // Fallback
            
            const gAnchor = mesh.skeleton.bones.find(b => {
                const name = b.name.toLowerCase();
                if (garmentType === 'top' || garmentType === 'dress') {
                    return name.includes('neck') || name.includes('spine2') || name.includes('chest') || name.includes('shoulder');
                }
                return name.includes('hips') || name.includes('pelvis') || name.includes('waist');
            });

            if (gAnchor) {
                const anchorIndex = mesh.skeleton.bones.indexOf(gAnchor);
                if (anchorIndex >= 0 && mesh.skeleton.boneInverses[anchorIndex]) {
                    const anchorInverse = mesh.skeleton.boneInverses[anchorIndex];
                    const anchorWorld = anchorInverse.clone().invert();
                    const pos = new THREE.Vector3();
                    pos.setFromMatrixPosition(anchorWorld);
                    garmentAnchorY = pos.y;
                }
            } else if (garmentType === 'top' || garmentType === 'dress') {
                garmentAnchorY = 1.4; // Fallback for tops
            }

            const scaleMatrix = new THREE.Matrix4().makeScale(scaleFactors.x, scaleFactors.y, scaleFactors.z);
            const transToOrigin = new THREE.Matrix4().makeTranslation(0, -garmentAnchorY, 0);
            const transBack = new THREE.Matrix4().makeTranslation(0, garmentAnchorY, 0);
            
            // M = TransBack * Scale * TransToOrigin
            const anchorScaleMatrix = new THREE.Matrix4()
                .multiply(transBack)
                .multiply(scaleMatrix)
                .multiply(transToOrigin);

            const scaledBindMatrix = anchorScaleMatrix.clone().multiply(mesh.bindMatrix);
            
            mesh.bind(remappedSkeleton, scaledBindMatrix);
        } else {
            mesh.bind(remappedSkeleton, mesh.bindMatrix.clone());
        }

        mesh.normalizeSkinWeights();
        mesh.frustumCulled = false;
        boundMeshCount += 1;

        // Clone geometry then push vertices outward along normals to avoid
        // z-fighting and body-through-cloth clipping.
        if (skinOffset > 0) {
            mesh.geometry = mesh.geometry.clone();
            inflateGeometryAlongNormals(mesh.geometry, skinOffset);
        }
    }

    // ── Regular Mesh (no skinning): attach to nearest avatar bone ──
    const bonePos = new THREE.Vector3();
    const worldPos = new THREE.Vector3();

    for (const mesh of staticMeshes) {
        mesh.getWorldPosition(worldPos);

        let closest: THREE.Bone | null = null;
        let bestDist = Infinity;

        for (const bone of lookup.all) {
            bone.getWorldPosition(bonePos);
            const d = worldPos.distanceTo(bonePos);
            if (d < bestDist) {
                bestDist = d;
                closest = bone;
            }
        }

        if (closest) {
            closest.attach(mesh);
            mesh.frustumCulled = false;
            attachedMeshCount += 1;
        }
    }

    return {
        boundMeshCount,
        attachedMeshCount,
        missingBoneNames: [...missingBoneNames],
    };
};

/**
 * Push every vertex of a BufferGeometry outward along its normal.
 * Used to create a slight "inflation" so the cloth sits just above the skin.
 */
const inflateGeometryAlongNormals = (geometry: THREE.BufferGeometry, offset: number) => {
    const posAttr = geometry.getAttribute('position');
    const normalAttr = geometry.getAttribute('normal');
    if (!posAttr || !normalAttr) return;

    for (let i = 0; i < posAttr.count; i++) {
        posAttr.setXYZ(
            i,
            posAttr.getX(i) + normalAttr.getX(i) * offset,
            posAttr.getY(i) + normalAttr.getY(i) * offset,
            posAttr.getZ(i) + normalAttr.getZ(i) * offset,
        );
    }
    posAttr.needsUpdate = true;
    geometry.computeBoundingSphere();
    geometry.computeBoundingBox();
};

export const createGarmentMorphBindings = (
    garmentRoot: THREE.Object3D,
    avatarScene: THREE.Object3D,
): { bindings: MorphMeshBinding[]; mappedChannelCount: number } => {
    const sourceChannelsByName = new Map<string, { sourceIndex: number; sourceInfluences: number[] }>();

    avatarScene.traverse((child) => {
        if (!(child instanceof THREE.Mesh) || !child.morphTargetDictionary || !child.morphTargetInfluences) {
            return;
        }

        Object.entries(child.morphTargetDictionary).forEach(([morphName, sourceIndex]) => {
            if (!sourceChannelsByName.has(morphName)) {
                sourceChannelsByName.set(morphName, {
                    sourceIndex,
                    sourceInfluences: child.morphTargetInfluences as number[],
                });
            }
        });
    });

    const bindings: MorphMeshBinding[] = [];
    let mappedChannelCount = 0;

    garmentRoot.traverse((child) => {
        if (!(child instanceof THREE.Mesh) || !child.morphTargetDictionary || !child.morphTargetInfluences) {
            return;
        }

        const channels: MorphChannelBinding[] = [];
        Object.entries(child.morphTargetDictionary).forEach(([morphName, targetIndex]) => {
            const source = sourceChannelsByName.get(morphName);
            if (!source) {
                return;
            }

            channels.push({
                targetIndex,
                sourceIndex: source.sourceIndex,
                sourceInfluences: source.sourceInfluences,
            });
        });

        if (channels.length > 0) {
            bindings.push({ targetMesh: child, channels });
            mappedChannelCount += channels.length;
        }
    });

    return { bindings, mappedChannelCount };
};

export const syncGarmentMorphTargets = (
    bindings: MorphMeshBinding[],
    options: GarmentMorphSyncOptions = {},
) => {
    const influenceScale = THREE.MathUtils.clamp(options.influenceScale ?? 1, 0, 1.5);
    const smoothing = THREE.MathUtils.clamp(options.smoothing ?? 1, 0, 1);
    const maxInfluence = THREE.MathUtils.clamp(options.maxInfluence ?? 1, 0, 1);

    bindings.forEach(({ targetMesh, channels }) => {
        const targetInfluences = targetMesh.morphTargetInfluences;
        if (!targetInfluences) {
            return;
        }

        channels.forEach(({ targetIndex, sourceIndex, sourceInfluences }) => {
            const sourceValue = sourceInfluences[sourceIndex] ?? 0;
            
            let targetValue = 0;
            if (sourceValue >= 0) {
                // Avatar is getting fatter/wider.
                // To prevent clipping, the garment MUST stretch heavily to cover the body.
                // We boost the influenceScale for positive morphs.
                const stretchInfluence = Math.max(influenceScale, 0.98); 
                targetValue = THREE.MathUtils.clamp(sourceValue * stretchInfluence, 0, 1.5);
            } else {
                // Avatar is getting skinnier/narrower.
                // To preserve "loose/oversized" fits, we allow the garment to shrink LESS than the avatar.
                targetValue = THREE.MathUtils.clamp(sourceValue * influenceScale, -1.5, 0);
            }

            const currentValue = targetInfluences[targetIndex] ?? 0;
            targetInfluences[targetIndex] = THREE.MathUtils.lerp(currentValue, targetValue, smoothing);
        });
    });
};

/**
 * Custom Hook: useOutfitGenerator
 * Implements Circuit Breaker pattern for resilient outfit generation
 * 
 * Flow:
 * 1. Try Gemini API (with 8s timeout) — SUCCESS → use Gemini outfits
 * 2. Gemini timeout/error → CIRCUIT BREAKER TRIGGERS
 * 3. Try Local Engine — SUCCESS → use local outfits + set fallbackMode = true
 * 4. Local Engine also fails → FALLBACK ERROR → show error message
 */

import { useState, useCallback, useEffect } from 'react';
import axios from 'axios';
import type { OutfitFilter, OutfitResult } from '../types/outfit';
import { fetchWithTimeout } from '../utils/fetchWithTimeout';
import { generateLocalOutfits } from '../utils/generateLocalOutfits';

type Product = {
    _id?: string;
    id?: string;
    name?: string;
    price?: number;
    category?: string;
    imageUrl?: string;
    aiStylist?: {
        styles?: string[];
        occasions?: string[];
        colorTone?: string;
    };
};

interface UseOutfitGeneratorOptions {
    closetItems: any[];
    shopItems?: any[];
    userId?: string;
    avatarData?: any;
}

// Helper: Get authentication token from localStorage
const getToken = (): string => {
    return (
        localStorage.getItem('token') ||
        localStorage.getItem('accessToken') ||
        localStorage.getItem('authToken') ||
        localStorage.getItem('jwt') ||
        ''
    );
};
// Helper: Generate fallback prompt from filter selections when user doesn't provide description
const generateFallbackPrompt = (filters: OutfitFilter): string => {
    const parts: string[] = [];

    // Map occasions to Vietnamese descriptions
    const occasionMap: Record<string, string> = {
        cafe: 'đi cafe',
        office: 'công sở',
        street: 'dạo phố',
        party: 'dự tiệc',
        travel: 'du lịch',
        date: 'hẹn hò',
    };

    if (filters.occasions.length > 0) {
        const occasionTexts = filters.occasions.map(o => occasionMap[o] || o);
        parts.push(`Tôi muốn mặc ${occasionTexts.join(' hoặc ')}`);
    }

    if (filters.styles.length > 0) {
        parts.push(`phong cách ${filters.styles.join(', ')}`);
    }

    if (filters.colors.length > 0) {
        // Color hex map
        const colorNames: Record<string, string> = {
            '#1a1a1a': 'đen',
            '#ffffff': 'trắng',
            '#93c5fd': 'xanh nhạt',
            '#f9a8d4': 'hồng',
            '#86efac': 'xanh lá',
            '#fcd34d': 'vàng',
            '#fdba74': 'cam',
            '#c4b5fd': 'tím',
        };
        const colorTexts = filters.colors.map(c => colorNames[c] || c);
        parts.push(`tông màu ${colorTexts.join(', ')}`);
    }

    // Combine parts into a sentence
    if (parts.length === 0) {
        return 'Gợi ý cho tôi một bộ trang phục đẹp';
    }

    // "Tôi muốn mặc... + phong cách... + tông màu..."
    return parts.join(', ');
};

const normalizeText = (value = ''): string =>
    value
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '');

const productMatchesFilter = (product: Product, filters: OutfitFilter): boolean => {
    const budgetMatch = (product.price ?? 0) <= filters.budget;
    if (!budgetMatch) {
        return false;
    }

    const styleMatch = filters.styles.length === 0
        ? true
        : filters.styles.some((style) =>
            product.aiStylist?.styles?.some((candidate) =>
                normalizeText(candidate).includes(normalizeText(style))
            )
        );

    const occasionMatch = filters.occasions.length === 0
        ? true
        : filters.occasions.some((occasion) =>
            product.aiStylist?.occasions?.some((candidate) =>
                normalizeText(candidate).includes(normalizeText(occasion))
            )
        );

    return styleMatch || occasionMatch;
};

const buildGeminiProducts = (shopItems: Product[], filters: OutfitFilter): Product[] => {
    const topKeywords = ['áo', 'shirt', 'top', 'blouse', 'hoodie', 'crop'];
    const bottomKeywords = ['quần', 'váy', 'jean', 'pant', 'skirt', 'short'];
    const shoeKeywords = ['giày', 'dép', 'sneaker', 'boot', 'sandal'];

    const filtered = shopItems.filter((product) => productMatchesFilter(product, filters));

    const pickCategory = (items: Product[], keywords: string[]) =>
        items
            .filter((product) => {
                const category = normalizeText(product.category ?? '');
                const name = normalizeText(product.name ?? '');
                return keywords.some((keyword) =>
                    category.includes(normalizeText(keyword)) || name.includes(normalizeText(keyword))
                );
            })
            .slice(0, 10);

    const merged = [
        ...pickCategory(filtered, topKeywords),
        ...pickCategory(filtered, bottomKeywords),
        ...pickCategory(filtered, shoeKeywords),
    ];

    const unique: Product[] = [];
    const seen = new Set<string>();

    merged.forEach((product) => {
        const id = String(product._id ?? product.id ?? product.name ?? Math.random());
        if (seen.has(id)) {
            return;
        }
        seen.add(id);
        unique.push(product);
    });

    return unique.slice(0, 30);
};

export function useOutfitGenerator(options: UseOutfitGeneratorOptions) {
    const { closetItems, shopItems: initialShopItems = [], userId, avatarData } = options;

    const [outfits, setOutfits] = useState<OutfitResult[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string>('');
    const [fallbackMode, setFallbackMode] = useState(false);
    const [shopItems, setShopItems] = useState<Product[]>(initialShopItems);
    const [shopLoading, setShopLoading] = useState(true);

    useEffect(() => {
        let mounted = true;
        const abortController = new AbortController();

        const fetchShopItems = async () => {
            try {
                const token = getToken();
                const response = await axios.get('/api/products', {
                    headers: token ? { Authorization: `Bearer ${token}` } : undefined,
                    params: { limit: 100, isActive: true },
                    signal: abortController.signal,
                });

                const products =
                    response.data?.products ??
                    response.data?.data ??
                    response.data?.items ??
                    response.data ??
                    [];

                if (!mounted) {
                    return;
                }

                const normalizedProducts = Array.isArray(products) ? products : [];
                setShopItems(normalizedProducts);
                console.log('[ShopItems] Loaded:', normalizedProducts.length, 'products');
            } catch (err) {
                if (!mounted) {
                    return;
                }

                if (axios.isAxiosError(err) && err.code === 'ERR_CANCELED') {
                    return;
                }

                console.error('[ShopItems] Failed to fetch:', err);
                setShopItems([]);
            } finally {
                if (mounted) {
                    setShopLoading(false);
                }
            }
        };

        fetchShopItems();

        return () => {
            mounted = false;
            abortController.abort();
        };
    }, []);

    const handleGenerateOutfit = useCallback(
        async (filters: OutfitFilter) => {
            if (shopLoading) {
                setError('Đang tải danh sách sản phẩm, vui lòng thử lại...');
                return;
            }

            if (shopItems.length === 0) {
                setError('Không có sản phẩm nào trong hệ thống.');
                return;
            }

            setIsLoading(true);
            setError('');
            setFallbackMode(false);
            setOutfits([]);

            try {
                // ─── HAPPY PATH: Try Gemini API with timeout ───
                console.info('[AI] Attempting Gemini API...');

                const token = getToken();
                if (!token) {
                    console.warn('[AI] No authentication token found. Request may fail.');
                }

                const geminiProducts = buildGeminiProducts(shopItems, filters);
                console.log('[Gemini] Sending', geminiProducts.length, 'products (pre-filtered)');

                const response = await fetchWithTimeout(
                    '/api/ai/outfit-suggest',
                    {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': token ? `Bearer ${token}` : ''
                        },
                        body: JSON.stringify({
                            ...filters,
                            userPrompt: filters.description || generateFallbackPrompt(filters),
                            userId,
                            products: geminiProducts.map((product) => ({
                                _id: product._id,
                                id: product.id,
                                name: product.name,
                                price: product.price,
                                category: product.category,
                                imageUrl: product.imageUrl,
                                aiStylist: product.aiStylist,
                            })),
                        }),
                    },
                    8000 // 8 second timeout
                );

                // ─── Check for server-side Gemini timeout (503 + GEMINI_TIMEOUT code) ───
                if (!response.ok) {
                    const responseData = await response.json().catch(() => ({}));

                    // Server signaled Gemini timeout → trigger local engine immediately
                    if (response.status === 503 && responseData.code === 'GEMINI_TIMEOUT') {
                        console.warn('[AI] Server: Gemini timed out at 10s. Triggering local engine fallback.');
                        throw new Error('SERVER_GEMINI_TIMEOUT');
                    }

                    throw new Error(`API returned ${response.status}: ${responseData.message || responseData.error || 'Unknown error'}`);
                }

                const data = await response.json();

                // Check if Gemini returned valid outfits
                if (!data.outfits || data.outfits.length === 0) {
                    throw new Error('Gemini returned empty outfits');
                }

                setOutfits(data.outfits);
                console.info('[AI] ✓ Gemini API succeeded. Outfits loaded:', data.outfits.length);
                return data.outfits;

            } catch (err: any) {
                // ─── FALLBACK: Circuit Breaker Triggered ───
                console.warn('[AI] ⚠ Circuit Breaker activated. Reason:', err.message);
                console.info('[AI] Attempting Local Outfit Engine...');

                try {
                    // Try generating outfits locally without Gemini
                    const localOutfits = generateLocalOutfits(filters, closetItems, shopItems);

                    if (localOutfits.length > 0) {
                        setOutfits(localOutfits);
                        setFallbackMode(true); // Signal to UI that we're using fallback
                        console.info('[AI] ✓ Local Engine succeeded. Outfits generated:', localOutfits.length);
                        return localOutfits;
                    } else {
                        throw new Error('Local engine generated no outfits');
                    }

                } catch (localErr: any) {
                    // ─── TOTAL FAILURE: Both Gemini and Local Engine failed ───
                    console.error('[AI] ✗ Both Gemini and Local Engine failed:', localErr.message);
                    setError(
                        'Hệ thống tạm thời gián đoạn. Vui lòng thử lại sau hoặc điều chỉnh bộ lọc.'
                    );
                    setOutfits([]);
                    return [];
                }

            } finally {
                setIsLoading(false);
            }
        },
        [closetItems, shopItems, userId]
    );

    return {
        outfits,
        isLoading,
        error,
        fallbackMode,
        shopLoading,
        shopItems,
        handleGenerateOutfit,
        setOutfits,
        setError,
        setFallbackMode,
    };
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { Sparkles, MessageCircle } from 'lucide-react'
import { useAuth } from '../contexts/AuthContext'
import { generateOutfit } from '../services/aiOutfitService'
import LeftPanel from '../components/ai-outfit/LeftPanel'
import AvatarPanel from '../components/outfit/AvatarPanel'
import AIOutfitSuggestionsPanel from '../components/outfit/AIOutfitSuggestionsPanel'
import TryOnPanel from '../components/outfit/TryOnPanel'
import BodyEditorDrawer from '../features/virtual-tryon/components/BodyEditorDrawer'
import { MODEL_INJECTION } from '../data/ThreeDConfig'
import { useFittingRoom, type GarmentSlot, type Profile } from '../contexts/FittingRoomContext'
import type { OutfitFilter, OutfitResult, ChatMessage, ViewAngle } from '../types/outfit'
import type { OutfitItem } from '../types/outfit'
import { useOutfitGenerator } from '../hooks/useOutfitGenerator'
import { initSelection, SelectionState, resolveGlbUrl } from '../utils/glb'
import '../features/virtual-tryon/VirtualTryOn.css'

interface AIOutfitGeneratorProps {
  onAddToCart?: (product: any, size?: string) => void;
  onBuyNow?: (product: any, size?: string) => void;
  showToast?: (message: string, type?: string) => void;
}

export default function AIOutfitGenerator({ onAddToCart, onBuyNow, showToast }: AIOutfitGeneratorProps = {}) {
  const navigate = useNavigate()
  const { user } = useAuth()
  const {
    currentAvatar,
    currentAvatarId,
    setCurrentAvatarId,
    avatars,
    layeredGarments,
    applySilentWear,
    applyFullOutfit,
    updateAvatar,
    addAvatar,
  } = useFittingRoom()

  // State management
  const [activeTab, setActiveTab] = useState<'describe' | 'occasion'>('describe')
  const [filter, setFilter] = useState<OutfitFilter>({
    occasions: [],
    styles: [],
    colors: [],
    budget: 2000000,
    description: ''
  })
  const [selectedOutfitId, setSelectedOutfitId] = useState<string | null>(null)
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [viewAngle, setViewAngle] = useState<ViewAngle>('front')
  const [closetItems, setClosetItems] = useState<any[]>([])
  const [isBodyEditorOpen, setIsBodyEditorOpen] = useState(false)
  const [bodyEditorNotice, setBodyEditorNotice] = useState<string>('')
  
  // TryOnPanel State
  const [isTryOnPanelOpen, setIsTryOnPanelOpen] = useState(false)
  const [tryOnPanelOutfitId, setTryOnPanelOutfitId] = useState<string | null>(null)
  const [selections, setSelections] = useState<SelectionState>({})

  // Floating Bubble State
  const [isLeftPanelExpanded, setIsLeftPanelExpanded] = useState(true)

  // Circuit Breaker Hook - handles Gemini fallback to Local Engine
  const {
    outfits,
    isLoading: isGenerating,
    error,
    fallbackMode,
    shopLoading,
    handleGenerateOutfit,
    setOutfits,
    setError,
  } = useOutfitGenerator({
    closetItems,
    shopItems: [],
    userId: user?._id,
    avatarData: {
      avatar: currentAvatar,
      layeredGarments,
    },
  })

  const selectedOutfit = outfits.find(o => o.id === selectedOutfitId) || outfits[0] || null

  useEffect(() => {
    if (selectedOutfit) {
      setSelections(initSelection(selectedOutfit));
    }
  }, [selectedOutfitId, outfits]);

  const activeAvatarData = useMemo(() => ({
    avatar: currentAvatar,
    layeredGarments,
  }), [currentAvatar, layeredGarments])

  const showBodyEditorToast = (message: string) => {
    setBodyEditorNotice(message)
    window.setTimeout(() => setBodyEditorNotice(''), 2200)
  }

  const ensureEditableAvatarId = (): string => {
    if (currentAvatarId) return currentAvatarId

    const newAvatar: Profile = {
      ...currentAvatar,
      id: `ai-avatar-${Date.now()}`,
      name: 'Avatar AI',
    }
    addAvatar(newAvatar)
    setCurrentAvatarId(newAvatar.id)
    return newAvatar.id
  }

  const handleBodyProfileChange = (nextProfile: Profile) => {
    const targetAvatarId = ensureEditableAvatarId()
    updateAvatar(targetAvatarId, nextProfile)
  }

  const mapToSilentWearSlot = (category: OutfitItem['category']): GarmentSlot | null => {
    if (category === 'top') return 'tops'
    if (category === 'bottom') return 'bottoms'
    if (category === 'outerwear') return 'outerwear'
    if (category === 'shoes') return null
    return null
  }

  const resolveModel3D = (itemId: string | number, itemModel3D?: any, productUrl?: string, category?: string) => {
    // If backend returns a config object
    if (itemModel3D && typeof itemModel3D === 'object' && itemModel3D.sizes) return itemModel3D;
    
    // If backend returns a raw URL string
    if (itemModel3D && typeof itemModel3D === 'string') {
        return {
            enable: true,
            sizes: {
                S: { url: itemModel3D, autoNormalize: true, followAvatarBones: false },
                M: { url: itemModel3D, autoNormalize: true, followAvatarBones: false },
                L: { url: itemModel3D, autoNormalize: true, followAvatarBones: false },
                XL: { url: itemModel3D, autoNormalize: true, followAvatarBones: false },
            }
        };
    }

    const modelMap = MODEL_INJECTION as any;
    
    // First try the item ID
    let strId = String(itemId).trim();
    if (strId && modelMap[strId]) return modelMap[strId];
    
    // If it didn't match, the item ID might be a MongoDB ObjectID. 
    // Try to extract the real product ID from the productUrl.
    if (productUrl && productUrl.includes('/product/')) {
        const extractedId = productUrl.split('/product/').pop()?.trim();
        if (extractedId && modelMap[extractedId]) return modelMap[extractedId];
    }
    
    return undefined;
  }

  const applyOutfitToAvatar = (outfit: OutfitResult) => {
    const silentWearItems = outfit.items
      .map((item) => {
        const slot = mapToSilentWearSlot(item.category)
        if (!slot) return null
        
        const size = selections[item.id]?.size || item.selectedSize || item.suggestedSize || 'M'
        const color = selections[item.id]?.colorHex || item.selectedColor || item.color
        
        let glbUrl = resolveGlbUrl(item, size, color)

        return {
          itemId: item.id,
          productId: item.id,
          name: item.name,
          category: slot,
          purchasedSize: size,
          purchasedColor: color,
          thumbnail: item.imageUrl,
          source: 'fallback' as const,
          model3D: glbUrl ? { enable: true, sizes: { [size]: { url: glbUrl, autoNormalize: true } } } : resolveModel3D(item.id, item.model3D, item.productUrl, item.category),
        }
      })
      .filter((item): item is NonNullable<typeof item> => Boolean(item))

    if (silentWearItems.length > 0) {
      applyFullOutfit(silentWearItems)
    }
  }

  const handleSelectOutfit = (outfitId: string) => {
    const outfit = outfits.find((entry) => entry.id === outfitId)
    if (!outfit) return
    setSelectedOutfitId(outfitId)
  }

  const handleUpdateOutfitItem = (outfitId: string, itemId: string, updates: Partial<OutfitItem>) => {
    setOutfits(prevOutfits => prevOutfits.map(outfit => {
      if (outfit.id !== outfitId) return outfit;
      return {
        ...outfit,
        items: outfit.items.map(item => {
          if (item.id !== itemId) return item;
          return { ...item, ...updates };
        })
      };
    }));
  };

  const handleOpenTryOnPanel = (outfitId: string) => {
    setTryOnPanelOutfitId(outfitId);
    setIsTryOnPanelOpen(true);
  };

  const handleCloseTryOnPanel = () => {
    setIsTryOnPanelOpen(false);
  };

  const handleTryOnPanelIndexChange = (index: number) => {
    const nextOutfit = outfits[index];
    if (nextOutfit) {
      setTryOnPanelOutfitId(nextOutfit.id);
      setSelectedOutfitId(nextOutfit.id);
      applyOutfitToAvatar(nextOutfit);
    }
  };

  const handleAddToCart = (outfit: OutfitResult) => {
    if (!onAddToCart) {
      alert('Đã thêm Outfit vào giỏ hàng!');
      return;
    }
    outfit.items.forEach(item => {
      onAddToCart({
        id: item.id,
        name: item.name,
        price: item.price,
        img: item.imageUrl,
        category: item.category,
      }, item.selectedSize || item.suggestedSize || 'M');
    });
    if (showToast) showToast('Đã thêm Outfit vào giỏ hàng!');
  };

  const handleBuyNow = (outfit: OutfitResult) => {
    if (!onBuyNow) {
      alert('Đang chuyển đến trang thanh toán...');
      handleCloseTryOnPanel();
      return;
    }
    outfit.items.forEach((item, index) => {
      const product = {
        id: item.id,
        name: item.name,
        price: item.price,
        img: item.imageUrl,
        category: item.category,
      };
      const size = item.selectedSize || item.suggestedSize || 'M';
      if (index === outfit.items.length - 1) {
         onBuyNow(product, size);
      } else {
         if (onAddToCart) onAddToCart(product, size);
      }
    });
    handleCloseTryOnPanel();
  };

  const handleTryItem = (item: OutfitItem) => {
    const slot = mapToSilentWearSlot(item.category)
    if (!slot) return

    applySilentWear({
      itemId: item.id,
      productId: item.id,
      name: item.name,
      category: slot,
      purchasedSize: item.selectedSize || item.suggestedSize || 'M',
      purchasedColor: item.selectedColor || item.color,
      thumbnail: item.imageUrl,
      source: 'fallback',
      model3D: resolveModel3D(item.id, item.model3D, item.productUrl, item.category),
    })
  }

  // Fetch closet items when component mounts
  useEffect(() => {
    const token = localStorage.getItem('token') || ''
    if (!token) return

    fetch('/api/virtual-closet', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(data => setClosetItems(data.items ?? []))
      .catch(() => { }) // không crash nếu chưa có closet
  }, [])

  // Close bubble if there are already generated outfits when the component loads
  useEffect(() => {
    if (outfits && outfits.length > 0) {
      setIsLeftPanelExpanded(false)
    }
  }, [outfits.length])

  // Handle outfit generation with Circuit Breaker pattern
  const handleGenerate = async () => {
    setIsLeftPanelExpanded(false)
    setMessages([])
    const generatedOutfits = await handleGenerateOutfit(filter)

    // After outfit generation, select the first outfit but do NOT apply it automatically
    if (generatedOutfits && generatedOutfits.length > 0) {
      setSelectedOutfitId(generatedOutfits[0].id)
    }
  }

  // Handle chat/refinement with real API
  const handleSendMessage = async (text: string) => {
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date(),
    }
    setMessages(prev => [...prev, userMsg])
    setIsGenerating(true)
    setError('')

    try {
      const result = await generateOutfit(filter, closetItems, activeAvatarData, user?._id)
      if (result.outfits.length > 0) {
        setOutfits(result.outfits)
        setSelectedOutfitId(result.outfits[0].id)
      }
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `${result.message} (Đã ưu tiên mô tả từ panel bên trái)`,
        timestamp: new Date(),
        suggestions: result.suggestions,
      }])
    } catch (err: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `⚠️ ${err.message}`,
        timestamp: new Date(),
      }])
    } finally {
      setIsGenerating(false)
    }
  }

  return (
    <div style={{
      height: '100vh',
      display: 'flex',
      flexDirection: 'column',
      background: 'var(--bg-primary)',
      color: 'var(--text-primary)',
      overflow: 'hidden',
    }}>
      <style>{`
        .ai-gen-btn {
          border: 1px solid #cbd5e1;
          background: #fff;
          border-radius: 999px;
          padding: 8px 12px;
          display: inline-flex;
          align-items: center;
          gap: 8px;
          cursor: pointer;
          box-shadow: 0 1px 2px rgba(15, 23, 42, 0.05);
        }
        .ai-gen-tab {
          border: 1px solid transparent;
          background: transparent;
          border-radius: 10px;
          padding: 7px 12px;
          font-size: 13px;
          cursor: pointer;
          color: #475569;
        }
        .ai-gen-tab.active {
          background: #0f172a;
          color: #fff;
        }
        .ai-gen-card {
          background: rgba(255,255,255,0.84);
          border: 1px solid rgba(148,163,184,0.35);
          box-shadow: 0 10px 35px rgba(15,23,42,0.10);
          backdrop-filter: blur(18px);
        }
      `}</style>

      {/* Topbar */}
      <header style={{
        background: 'rgba(15,11,7,0.96)',
        borderBottom: '1px solid var(--gold-divider)',
        backdropFilter: 'blur(12px)',
        padding: '0 24px',
        height: '60px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        position: 'sticky',
        top: 0,
        zIndex: 100,
        flexShrink: 0,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <button
            onClick={() => navigate(-1)}
            style={{
              background: 'transparent',
              border: 'none',
              color: 'var(--text-secondary)',
              padding: '0',
              fontSize: '13px',
              display: 'flex',
              alignItems: 'center',
              gap: '6px',
              cursor: 'pointer',
            }}
          >
            <span>←</span>
          </button>
          
          <div style={{ width: '1px', height: '20px', background: 'var(--gold-divider)' }} />
          
          <div style={{ 
            fontSize: '15px', 
            color: 'var(--gold-primary)', 
            display: 'flex', 
            alignItems: 'center', 
            gap: '8px',
            fontWeight: '700',
            letterSpacing: '0.02em'
          }}>
            ✨ VFit Stylist
          </div>
        </div>

        <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            background: 'var(--surface-subtle)',
            border: '1px solid var(--gold-border)',
            borderRadius: '100px',
            padding: '4px 14px',
            gap: '8px',
            height: '34px',
          }}>
            <span style={{ fontSize: '10px', color: 'var(--text-secondary)', fontWeight: '600', letterSpacing: '0.05em' }}>
              AVATAR
            </span>
            <select
              value={currentAvatarId || ''}
              onChange={(e) => setCurrentAvatarId(e.target.value)}
              disabled={avatars?.length === 0}
              style={{
                background: 'transparent',
                border: 'none',
                color: 'var(--text-primary)',
                fontSize: '12px',
                fontWeight: '600',
                outline: 'none',
                cursor: 'pointer',
                appearance: 'none',
                paddingRight: '12px',
              }}
            >
              {(!avatars || avatars.length === 0) && <option value="" style={{ color: '#000' }}>Khách mặc định</option>}
              {avatars?.map((avatar) => (
                <option key={avatar.id} value={avatar.id} style={{ color: '#000' }}>
                  {avatar.name}
                </option>
              ))}
            </select>
            <div style={{ width: '1px', height: '14px', background: 'var(--gold-divider)' }} />
            <button
              type="button"
              onClick={() => navigate('/avatar-studio', { state: { returnTo: '/ai-outfit' } })}
              style={{
                background: 'transparent',
                border: 'none',
                color: 'var(--gold-primary)',
                fontSize: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                padding: '0 4px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
              title="Tạo avatar mới"
            >
              +
            </button>
          </div>
        </div>
      </header>

      {/* Error Banner */}
      {error && (
        <div style={{
          margin: '12px 16px 0',
          padding: '10px 12px',
          background: '#fef2f2',
          border: '1px solid #fecaca',
          borderRadius: 12,
          fontSize: 13,
          color: '#dc2626',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
        }}>
          <span>⚠️ {error}</span>
          <button onClick={() => setError('')} style={{ color: '#f87171', border: 'none', background: 'transparent', cursor: 'pointer', fontSize: 16 }}>✕</button>
        </div>
      )}

      {/* Fallback Mode Banner */}
      {bodyEditorNotice && (
        <div style={{
          margin: '10px 16px 0',
          padding: '10px 12px',
          background: '#ecfeff',
          border: '1px solid #a5f3fc',
          borderRadius: 12,
          fontSize: 13,
          color: '#0f766e',
        }}>
          {bodyEditorNotice}
        </div>
      )}

      {/* Inspiration Strip */}
      <div style={{
        background: 'var(--surface-elevated)',
        borderBottom: '1px solid var(--gold-divider)',
        padding: '12px 24px',
        display: 'flex',
        alignItems: 'center',
        gap: '16px',
        flexShrink: 0,
        overflowX: 'auto',
        scrollbarWidth: 'none',
      }}>
        <div style={{ fontSize: '11px', fontWeight: '600', color: 'var(--text-secondary)', letterSpacing: '0.04em', flexShrink: 0, display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ color: '#ef4444' }}>🔥</span> TRENDING TODAY
        </div>
        
        <div style={{ width: '1px', height: '14px', background: 'var(--gold-divider)', flexShrink: 0 }} />
        
        <div style={{ display: 'flex', gap: '8px' }}>
          {['Old Money', 'Korean Chic', 'Quiet Luxury', 'Summer Vibes', 'Minimalist'].map(tag => (
            <button
              key={tag}
              onClick={() => {
                setActiveTab('describe');
                setFilter(prev => ({ ...prev, description: prev.description ? `${prev.description}, ${tag}` : tag }));
              }}
              style={{
                background: 'linear-gradient(135deg, rgba(212,169,66,0.08) 0%, rgba(242,216,120,0.02) 100%)',
                border: '1px solid rgba(212,169,66,0.2)',
                borderRadius: '8px',
                padding: '6px 14px',
                fontSize: '12px',
                color: 'var(--text-primary)',
                cursor: 'pointer',
                whiteSpace: 'nowrap',
                transition: 'all 0.2s ease',
              }}
              onMouseEnter={e => {
                e.currentTarget.style.borderColor = 'var(--gold-primary)';
                e.currentTarget.style.background = 'var(--gold-light)';
              }}
              onMouseLeave={e => {
                e.currentTarget.style.borderColor = 'rgba(212,169,66,0.2)';
                e.currentTarget.style.background = 'linear-gradient(135deg, rgba(212,169,66,0.08) 0%, rgba(242,216,120,0.02) 100%)';
              }}
            >
              {tag}
            </button>
          ))}
        </div>
      </div>

      <div style={{
        display: 'grid',
        gridTemplateColumns: '1fr 480px',
        height: 'calc(100vh - 60px - 53px)', /* 60px header + 53px strip */
        background: 'var(--bg-primary)',
        overflow: 'hidden',
        position: 'relative',
      }}>
        {/* Floating Left Panel (Bubble) */}
        <div style={{
          position: 'absolute',
          bottom: '24px',
          left: '24px',
          zIndex: 50,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start',
          pointerEvents: 'none', // Let clicks pass through empty space
        }}>
          {isLeftPanelExpanded ? (
            <div style={{
              pointerEvents: 'auto',
              background: 'rgba(15, 15, 30, 0.92)',
              backdropFilter: 'blur(8px)',
              borderRadius: '24px',
              border: '1px solid rgba(212, 169, 66, 0.3)',
              boxShadow: '0 20px 40px rgba(0,0,0,0.4)',
              width: '320px',
              maxHeight: 'calc(100vh - 120px)',
              overflowY: 'auto',
              transform: 'translateY(0)',
              opacity: 1,
              transition: 'transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease',
              display: 'flex',
              flexDirection: 'column',
              scrollbarWidth: 'none',
            }}>
              <LeftPanel
                activeTab={activeTab}
                setActiveTab={setActiveTab}
                filter={filter}
                onChange={setFilter}
                onGenerate={handleGenerate}
                isGenerating={isGenerating}
                shopLoading={shopLoading}
                onClose={() => setIsLeftPanelExpanded(false)}
              />
            </div>
          ) : (
            <button
              onClick={() => setIsLeftPanelExpanded(true)}
              style={{
                pointerEvents: 'auto',
                height: '56px',
                width: outfits.length > 0 ? 'auto' : '56px',
                borderRadius: '28px',
                padding: outfits.length > 0 ? '0 24px' : '0',
                background: outfits.length > 0 ? 'rgba(15,15,30,0.92)' : 'linear-gradient(135deg, var(--gold-primary) 0%, #E8B84B 100%)',
                border: outfits.length > 0 ? '1px solid rgba(212,169,66,0.4)' : 'none',
                boxShadow: outfits.length > 0 ? '0 10px 30px rgba(0,0,0,0.3)' : '0 8px 24px rgba(201,150,63,0.3)',
                backdropFilter: 'blur(8px)',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                justifyContent: 'center',
                transform: 'translateY(0) scale(1)',
                transition: 'transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s',
                color: outfits.length > 0 ? 'var(--gold-primary)' : '#0F0B07'
              }}
              onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-4px) scale(1.02)'}
              onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0) scale(1)'}
              title={outfits.length > 0 ? "Chỉnh sửa bộ lọc" : "Mở bộ lọc AI"}
            >
              {outfits.length > 0 ? (
                <>
                  <span style={{ fontSize: '20px' }}>✨</span>
                  <span style={{ fontSize: '13px', fontWeight: '600' }}>Sửa bộ lọc</span>
                  <div style={{ background: 'var(--gold-primary)', color: '#0F0B07', fontSize: '11px', fontWeight: 'bold', padding: '2px 8px', borderRadius: '10px', marginLeft: '2px' }}>
                    {outfits.length}
                  </div>
                </>
              ) : (
                <span style={{ fontSize: '24px' }}>✨</span>
              )}
            </button>
          )}
        </div>

        {/* Middle Column - Avatar Panel */}
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          overflow: 'hidden',
        }}>
          <AvatarPanel
            selectedOutfit={selectedOutfit}
            isGenerating={isGenerating}
            viewAngle={viewAngle}
            onViewChange={setViewAngle}
          />
          {isTryOnPanelOpen && (
            <div 
                style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.18)', zIndex: 40, cursor: 'pointer' }}
                onClick={handleCloseTryOnPanel}
            />
          )}
        </div>

        {/* Right Column - AI Suggestions Panel */}
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          overflow: 'hidden',
        }}>
          <AIOutfitSuggestionsPanel
            isOpen={true}
            onClose={() => { }}
            outfits={outfits}
            selectedOutfitId={selectedOutfitId}
            onSelectOutfit={handleSelectOutfit}
            onWearSet={applyOutfitToAvatar}
            onTryItem={handleTryItem}
            isGenerating={isGenerating}
            messages={messages}
            onSendMessage={handleSendMessage}
            activeTab={activeTab}
            fallbackMode={fallbackMode}
            onUpdateItem={handleUpdateOutfitItem}
            onOpenTryonPanel={handleOpenTryOnPanel}
          />
        </div>

        {/* Try On Panel Overlay */}
        <TryOnPanel
            isOpen={isTryOnPanelOpen}
            outfits={outfits}
            currentIndex={outfits.findIndex(o => o.id === tryOnPanelOutfitId)}
            closetItems={closetItems}
            onClose={handleCloseTryOnPanel}
            onIndexChange={handleTryOnPanelIndexChange}
            onUpdateItem={handleUpdateOutfitItem}
            onAddToCart={handleAddToCart}
            onBuyNow={handleBuyNow}
            onTryOutfit={(outfit) => applyOutfitToAvatar(outfit)}
        />
      </div>

      <BodyEditorDrawer
        profile={currentAvatar}
        isOpen={isBodyEditorOpen}
        onClose={() => setIsBodyEditorOpen(false)}
        onSave={handleBodyProfileChange}
        onChange={handleBodyProfileChange}
        showToast={(message) => showBodyEditorToast(message)}
      />
    </div>
  )
}

