            >
                <SceneContent
                    environmentPreset={environmentPreset}
                    cameraPos={cameraPos}
                    cameraTarget={cameraTarget}
                    isRotating={isRotating}
                />
            </Canvas>

            <div className="vto-canvas-overlay vto-canvas-overlay--bottom-left">
                <CameraPresets
