                />
            </div>

            {isWebglContextLost && (
                <div style={{
                    position: 'absolute',
                    inset: 0,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: 'rgba(255,255,255,0.55)',
                    color: '#111827',
                    fontSize: 14,
                    fontWeight: 600,
                }}>
                    Đang khôi phục 3D canvas...
                </div>
            )}
        </div>
    );

    return (
        <>
            <div className="vto-container">
                {/* Top Navigation */}
                <header className="vto-nav">
                    <button className="vto-nav__back" onClick={handleBackToHome}>
