export default SizeComparisonRoom;

import type { OutfitResult, OutfitFilter, OutfitItem } from '../types/outfit'

const SYSTEM_ADDITION = `
Với mỗi sản phẩm trong suggestions, hãy thêm field "suggestedSize" dựa trên số đo avatar.
Ví dụ: "suggestedSize": "S" hoặc "suggestedSize": "M" hoặc "suggestedSize": "37" (cho giày).
Nếu không có thông tin số đo, để "suggestedSize": "M" làm mặc định.
`

// Lấy token từ localStorage — dùng đúng key project đang dùng
const getToken = (): string => {
  return (
    localStorage.getItem('token') ||
    localStorage.getItem('accessToken') ||
    localStorage.getItem('authToken') ||
    localStorage.getItem('jwt') ||
    ''
  )
}

// ── Chuyển OutfitFilter thành prompt text ──
const buildPromptFromFilter = (filter: OutfitFilter): string => {
  const parts: string[] = []

  if (filter.description.trim()) {
    parts.push(filter.description.trim())
  }

  if (filter.occasions.length > 0) {
    const occasionMap: Record<string, string> = {
      cafe: 'đi cafe',
      office: 'đi làm công sở',
      street: 'dạo phố',
      party: 'đi tiệc',
      travel: 'đi du lịch',
      date: 'hẹn hò'
    }
    parts.push(`Dịp: ${filter.occasions.map(o => occasionMap[o] ?? o).join(', ')}`)
  }

  if (filter.styles.length > 0) {
    parts.push(`Phong cách: ${filter.styles.join(', ')}`)
  }

  if (filter.colors.length > 0) {
    parts.push(`Tông màu ưa thích: ${filter.colors.join(', ')}`)
  }

  if (filter.budget > 0) {
    parts.push(`Ngân sách tối đa: ${new Intl.NumberFormat('vi-VN').format(filter.budget)}đ`)
  }

  // Include measurements if provided
  if (filter.measurements) {
    const { height, weight, chest, waist, hip } = filter.measurements
    const measurements: string[] = []
    if (height) measurements.push(`Cao ${height}cm`)
    if (weight) measurements.push(`Nặng ${weight}kg`)
    if (chest) measurements.push(`Ngực ${chest}cm`)
    if (waist) measurements.push(`Eo ${waist}cm`)
    if (hip) measurements.push(`Mông ${hip}cm`)
    if (measurements.length > 0) {
      parts.push(`Số đo: ${measurements.join(', ')}`)
    }
  }

  return parts.length > 0
    ? parts.join('. ')
    : 'Gợi ý outfit phù hợp cho tôi'
}

const buildSystemAddendum = (): string => SYSTEM_ADDITION.trim()

// ── Parse response từ backend thành OutfitResult[] ──
const parseBackendResponse = (data: any): OutfitResult[] => {
  const normalizeItem = (item: any, source: 'closet' | 'shop'): OutfitItem => ({
    id: String(item.itemId ?? item.id ?? item.productId ?? Math.random()),
    name: item.name ?? 'Sản phẩm',
    category: mapCategory(item.slot ?? item.category),
    price: item.price ?? 0,
    imageUrl: item.thumbnailUrl ?? item.imageUrl ?? item.img ?? '',
    productUrl: item.productId ? `/product/${item.productId}` : '#',
    color: item.color ?? '#888888',
    source,
    suggestedSize: item.suggestedSize ?? item.purchasedSize,
    sizeReason: item.sizeReason,
    owned: item.owned ?? false,
    slot: item.slot ?? item.category,
    model3D: item.model3D ?? item.model3d ?? undefined,
  })

  const closetItems = (data.outfit ?? []).map((item: any) => normalizeItem(item, 'closet'))
  const shopItems = (data.suggestions ?? []).map((item: any) => normalizeItem(item, 'shop'))

  const outfitVariants: OutfitItem[][] = []

  if (Array.isArray(data.outfits) && data.outfits.length > 0) {
    data.outfits.forEach((variant: any) => {
      outfitVariants.push((variant.items ?? []).map((item: any) => normalizeItem(item, item.type === 'closet' ? 'closet' : 'shop')))
    })
  } else {
    const base = [...closetItems, ...shopItems]
    const top = base.find((item) => item.category === 'top')
    const bottom = base.find((item) => item.category === 'bottom')
    const shoes = base.find((item) => item.category === 'shoes')
    const outerwear = base.find((item) => item.category === 'outerwear')
    const accessory = base.find((item) => item.category === 'accessory')

    const variant1 = [top, bottom, shoes, accessory].filter(Boolean) as OutfitItem[]
    const variant2 = [top, outerwear, bottom, shoes].filter(Boolean) as OutfitItem[]
    const variant3 = [...base].slice(0, 4)

    outfitVariants.push(variant1.length > 0 ? variant1 : base.slice(0, 3))
    outfitVariants.push(variant2.length > 0 ? variant2 : base.slice(0, 4))
    outfitVariants.push(variant3.length > 0 ? variant3 : base.slice(0, 3))
  }

  const uniqueVariants = outfitVariants
    .map((items) => items.filter((item, index, all) => all.findIndex((candidate) => candidate.id === item.id) === index))
    .filter((items) => items.length > 0)
    .slice(0, 3)

  return uniqueVariants.map((items, index) => ({
    id: `outfit-${Date.now()}-${index}`,
    name: data.outfits?.[index]?.name ?? (data.occasion ? `Outfit ${index + 1} - ${data.occasion}` : `Outfit ${index + 1}`),
    matchScore: calculateMatchScore(items),
    items,
    totalPrice: items.reduce((sum, item) => sum + (item.price ?? 0), 0),
    aiReason: data.outfits?.[index]?.aiReason ?? data.explanation ?? '',
    stats: data.stats ?? {
      ownedCount: items.filter(item => item.owned).length,
      buyCount: items.filter(item => !item.owned).length,
      totalBuyPrice: items.filter(item => !item.owned).reduce((sum, item) => sum + (item.price ?? 0), 0),
    },
  }))
}

// Helper: map slot name sang category
const mapCategory = (slot: string): 'top' | 'bottom' | 'shoes' | 'accessory' | 'outerwear' => {
  const map: Record<string, any> = {
    tops: 'top', top: 'top',
    bottoms: 'bottom', bottom: 'bottom',
    outerwear: 'outerwear',
    shoes: 'shoes', footwear: 'shoes',
    accessory: 'accessory', accessories: 'accessory',
    dress: 'bottom', dresses: 'bottom',
  }
  return map[slot?.toLowerCase()] ?? 'top'
}

// Helper: tính match score dựa trên số items từ closet
const calculateMatchScore = (items: any[]): number => {
  const total = items.length
  if (total === 0) return 70
  // Tính dựa trên số lượng items, max 99
  return Math.min(99, 70 + Math.round((Math.min(items.length, 3) / 3) * 29))
}

// ── API call chính ──
export const generateOutfit = async (
  filter: OutfitFilter,
  closetItems: any[] = [],
  avatarData: any = {},
  userId?: string
): Promise<{ outfits: OutfitResult[], message: string, suggestions: string[] }> => {

  const token = getToken()
  if (!token) {
    throw new Error('Vui lòng đăng nhập để sử dụng AI Stylist')
  }

  const userPrompt = buildPromptFromFilter(filter)
  const systemAddendum = buildSystemAddendum()

  const response = await fetch('/api/ai/outfit-suggest', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      userPrompt: `${userPrompt}\n\n${systemAddendum}`,
      closetItems: closetItems.slice(0, 10),
      avatarData,
      userId,
      filter: {
        occasions: filter.occasions,
        styles: filter.styles,
        colors: filter.colors,
        budget: filter.budget,
      },
      measurements: filter.measurements || {},
    }),
  })

  if (response.status === 401) {
    throw new Error('Phiên đăng nhập hết hạn. Vui lòng đăng nhập lại.')
  }

  if (response.status === 429) {
    throw new Error('AI đang bận, vui lòng thử lại sau vài giây.')
  }

  if (!response.ok) {
    const err = await response.json().catch(() => ({}))
    throw new Error(err.error ?? 'Không thể tạo outfit. Vui lòng thử lại.')
  }

  const data = await response.json()
  const outfits = parseBackendResponse(data)

  if (!Array.isArray(outfits) || outfits.length === 0) {
    throw new Error('AI chưa trả về sản phẩm cụ thể. Vui lòng thử lại với mô tả chi tiết hơn.')
  }

  // Tạo suggestions từ explanation
  const suggestions: string[] = [
    'Đổi sang tông tối hơn',
    'Thêm phụ kiện',
    'Giảm ngân sách',
    'Phong cách năng động hơn',
    'Thêm áo khoác bên ngoài',
  ]

  return {
    outfits,
    message: (typeof data.explanation === 'string' && data.explanation.trim().length > 0)
      ? data.explanation
      : `AI đã gợi ý ${outfits[0]?.items?.length ?? 0} sản phẩm phù hợp cho bạn.`,
    suggestions,
  }
}

// ── Chat tinh chỉnh outfit ──
export const refineOutfit = async (
  message: string,
  currentOutfits: OutfitResult[],
  closetItems: any[] = [],
  avatarData: any = {}
): Promise<{ outfits: OutfitResult[], reply: string, suggestions: string[] }> => {

  const token = getToken()
  if (!token) throw new Error('Chưa đăng nhập')

  // Thêm context về outfit hiện tại vào prompt
  const currentContext = currentOutfits.length > 0
    ? `Outfit hiện tại: ${currentOutfits[0].items.map(i => i.name).join(', ')}. `
    : ''

  const response = await fetch('/api/ai/outfit-suggest', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      userPrompt: `${currentContext}Yêu cầu chỉnh sửa: ${message}\n\n${buildSystemAddendum()}`,
      closetItems: closetItems.slice(0, 10),
      avatarData,
    }),
  })

  if (!response.ok) {
    throw new Error('Không thể xử lý yêu cầu. Vui lòng thử lại.')
  }

  const data = await response.json()
  const outfits = parseBackendResponse(data)

  return {
    outfits,
    reply: data.explanation ?? `Đã điều chỉnh theo yêu cầu "${message}"`,
    suggestions: ['Thử lại', 'Xem lựa chọn khác', 'Tông khác'],
  }
}

/**
 * Wrapper für fetch mit Timeout-Schutz
 * Prevents indefinite hangs when external APIs (like Gemini) are slow or unresponsive
 */
export async function fetchWithTimeout(
    url: string,
    options: RequestInit = {},
    timeout: number = 8000
): Promise<Response> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);

    try {
        const response = await fetch(url, {
            ...options,
            signal: controller.signal
        });
        return response;
    } catch (err: any) {
        if (err.name === 'AbortError') {
            throw new Error(`TIMEOUT: Request took longer than ${timeout}ms to respond`);
        }
        throw err;
    } finally {
        clearTimeout(timer);
    }
}

/**
 * Local Outfit Generation Engine
 * Used as fallback when Gemini API is unavailable or times out
 * Generates outfit suggestions using rule-based algorithm without external API calls
 */
import type { OutfitFilter, OutfitResult, OutfitItem } from '../types/outfit';

interface Product {
    _id?: string;
    id?: string;
    name: string;
    category: string;
    price: number;
    imageUrl?: string;
    img?: string;
    color?: string;
    aiStylist?: {
        styles?: string[];
        occasions?: string[];
        colorTone?: string;
    };
    productId?: string;
}

interface ClosetItem {
    _id?: string;
    id?: string;
    productId?: string;
    name: string;
    category: string;
    imageUrl?: string;
    img?: string;
    color?: string;
}

function mapCategory(rawCategory: string): 'top' | 'bottom' | 'shoes' | 'accessory' | 'outerwear' {
    const cat = rawCategory?.toLowerCase() || '';

    if (cat.includes('áo') || cat.includes('shirt') || cat.includes('top') || cat.includes('hoodie') || cat.includes('croptop')) {
        return 'top';
    }
    if (cat.includes('quần') || cat.includes('pants') || cat.includes('jeans') || cat.includes('chân váy') || cat.includes('váy') || cat.includes('dress')) {
        return 'bottom';
    }
    if (cat.includes('giày') || cat.includes('shoes') || cat.includes('sneaker') || cat.includes('dép')) {
        return 'shoes';
    }
    if (cat.includes('khoác') || cat.includes('jacket') || cat.includes('coat') || cat.includes('outerwear')) {
        return 'outerwear';
    }
    if (cat.includes('phụ kiện') || cat.includes('accessory') || cat.includes('túi') || cat.includes('nón')) {
        return 'accessory';
    }

    return 'accessory';
}

function calculateScore(product: Product, filter: OutfitFilter): number {
    let score = 0;

    // Style match
    if (product.aiStylist?.styles) {
        filter.styles.forEach(style => {
            if (product.aiStylist?.styles?.some(s => s.toLowerCase().includes(style.toLowerCase()))) {
                score += 3;
            }
        });
    }

    // Occasion match
    if (product.aiStylist?.occasions) {
        filter.occasions.forEach(occasion => {
            if (product.aiStylist?.occasions?.some(o => o.toLowerCase().includes(occasion.toLowerCase()))) {
                score += 3;
            }
        });
    }

    // Color tone match
    if (product.aiStylist?.colorTone && filter.colors.length > 0) {
        if (filter.colors.some(c => c.toLowerCase().includes(product.aiStylist?.colorTone?.toLowerCase() || ''))) {
            score += 2;
        }
    }

    return score;
}

export function generateLocalOutfits(
    filters: OutfitFilter,
    closetItems: ClosetItem[],
    shopItems: Product[]
): OutfitResult[] {
    const ownedIds = new Set<string>(
        closetItems.map(item => String(item._id || item.id || item.productId || ''))
    );

    // Step 1: Filter by budget
    const affordable = shopItems.filter(p => (p.price || 0) <= (filters.budget || 2000000));

    // Step 2: Score products based on filter preferences
    const scored = affordable
        .map(p => ({
            ...p,
            score: calculateScore(p, filters)
        }))
        .sort((a, b) => b.score - a.score);

    // Step 3: Separate by category
    const tops = scored.filter(p => mapCategory(p.category) === 'top');
    const bottoms = scored.filter(p => mapCategory(p.category) === 'bottom');
    const shoes = scored.filter(p => mapCategory(p.category) === 'shoes');

    // Step 4: Generate 3 outfits with no duplicate products
    const usedIds = new Set<string>();
    const outfits: OutfitResult[] = [];
    const styleNames = ['Casual Everyday', 'Minimal Chic', 'Street Style'];

    for (let i = 0; i < 3; i++) {
        const top = tops.find(p => !usedIds.has(String(p._id || p.id || '')));
        const bottom = bottoms.find(p => !usedIds.has(String(p._id || p.id || '')));
        const shoe = shoes.find(p => !usedIds.has(String(p._id || p.id || '')));

        // Need at least top + bottom
        if (!top || !bottom) continue;

        // Mark as used
        [top, bottom, shoe].filter(Boolean).forEach(p => {
            usedIds.add(String(p._id || p.id || ''));
        });

        // Build items array
        const items: OutfitItem[] = [top, bottom, shoe]
            .filter(Boolean)
            .map(p => {
                const productId = String(p?.productId || p?.id || p?._id || '');
                const isOwned = ownedIds.has(productId);

                    let availableColors: any[] | undefined = undefined;
                    let availableSizes: string[] | undefined = undefined;

                    if ((p as any).variants && Array.isArray((p as any).variants)) {
                        const variants = (p as any).variants;
                        availableColors = variants.map((v: any) => ({
                            hex: v.color?.hex,
                            label: v.color?.name,
                            image: v.color?.image || v.color?.img
                        })).filter((c: any) => c.hex);

                        const sizesSet = new Set<string>();
                        variants.forEach((v: any) => {
                            if (Array.isArray(v.sizes)) {
                                v.sizes.forEach((s: any) => sizesSet.add(s.size));
                            }
                        });
                        if (sizesSet.size > 0) {
                            availableSizes = Array.from(sizesSet);
                        }
                    }

                    return {
                        id: productId,
                        name: p?.name || 'Sản phẩm',
                        category: mapCategory(p?.category || ''),
                        price: p?.price || 0,
                        imageUrl: p?.imageUrl || p?.img || 'https://via.placeholder.com/300x400?text=No+Image',
                        productUrl: `/product/${productId}`,
                        color: p?.color || '#888888',
                        source: isOwned ? 'closet' : 'shop',
                        suggestedSize: 'M', // Default size for local engine
                        sizeReason: 'Kích thước mặc định',
                        owned: isOwned,
                        slot: mapCategory(p?.category || ''),
                        model3D: (p as any).model3D || (p as any).model3d,
                        availableColors,
                        availableSizes,
                    };
            });

        if (items.length < 2) continue;

        // Calculate totals
        const totalPrice = items.reduce((sum, item) => sum + item.price, 0);
        const ownedCount = items.filter(item => item.owned).length;
        const buyCount = items.filter(item => !item.owned).length;
        const totalBuyPrice = items.filter(item => !item.owned).reduce((sum, item) => sum + item.price, 0);

        outfits.push({
            id: `local-${i + 1}`,
            name: styleNames[i] || `Outfit ${i + 1}`,
            matchScore: Math.max(50 + Math.random() * 40, 60), // 60-100 range for local suggestions
            items,
            totalPrice,
            aiReason: `Được gợi ý bởi hệ thống nội bộ dựa trên bộ lọc của bạn (${filters.styles.join(', ') || 'Phong cách'})`,
            stats: {
                ownedCount,
                buyCount,
                totalBuyPrice,
            },
        });
    }

    return outfits;
}

import { OutfitItem, OutfitResult } from '../types/outfit';
import { MODEL_INJECTION } from '../data/ThreeDConfig';

export interface SelectionState {
  [productId: string]: {
    size: string;
    colorHex?: string;
  };
}

export function resolveGlbUrl(
  item: OutfitItem,
  selectedSize: string,
  selectedColorHex?: string
): string | undefined {
  if (item.glbVariants && item.glbVariants.length > 0) {
    const variant = item.glbVariants.find(
      v => v.size === selectedSize && v.colorHex === selectedColorHex
    );

    if (!variant) {
      const sizeMatch = item.glbVariants.find(v => v.size === selectedSize);
      return sizeMatch?.glbUrl ?? item.glbVariants[0].glbUrl;
    }
    return variant.glbUrl;
  }

  // If glbVariants is missing, return undefined so the caller can fall back to resolveModel3D
  return undefined;
}

export function resolveOutfitGlbs(
  outfit: OutfitResult,
  selections: SelectionState
): { productId: string; glbUrl: string | undefined }[] {
  return outfit.items.map(item => ({
    productId: item.id,
    glbUrl: resolveGlbUrl(
      item,
      selections[item.id]?.size || 'M',
      selections[item.id]?.colorHex
    ),
  }));
}

export function resolveVariantId(
  productId: string,
  size: string,
  colorHex: string,
  variants?: { size: string; colorHex: string; variantId?: string }[]
): string | undefined {
  if (!variants) return undefined;
  const variant = variants.find(v => v.size === size && v.colorHex === colorHex);
  return variant?.variantId;
}

export function initSelection(outfit: OutfitResult): SelectionState {
  const selections: SelectionState = {};
  if (!outfit || !outfit.items) return selections;

  outfit.items.forEach(item => {
    let defaultColor = item.color;
    
    // Explicit override for AI styles (Áo and Quần)
    const itemName = (item.name || '').toLowerCase();
    if (itemName.includes('áo')) {
      defaultColor = '#f5f5f5'; // Trắng
    } else if (itemName.includes('quần')) {
      defaultColor = '#222222'; // Đen
    } else if (item.availableColors && item.availableColors.length > 0) {
      const firstColor = item.availableColors[0];
      if (typeof firstColor === 'string') {
        defaultColor = firstColor;
      } else {
        const defaultColorObj = (item.availableColors as any[]).find((c: any) => c.isDefault);
        defaultColor = defaultColorObj ? defaultColorObj.hex : firstColor.hex;
      }
    }
    
    selections[item.id] = {
      size: item.selectedSize || item.suggestedSize || (item.availableSizes && item.availableSizes.length > 0 ? item.availableSizes[0] : 'M'),
      colorHex: item.selectedColor || defaultColor,
    };
  });
  return selections;
}

